<?php

/**
 * Run the NumPy/SciPy parity fixtures (tests/fixtures/parity/*.json) against one backend and record the
 * outcome per function in tools/parity/results.json (read by tools/parity/report.py).
 *
 *   php -d ffi.enable=1 tools/parity/run-tests.php --backend=ffi [--module=special] [--only=gammainc,jv] [-v]
 *   php -d extension=tessero tools/parity/run-tests.php --backend=ext
 *   ... --fixtures=<file.json> --no-record     # one fixture file; do not update results.json
 *   ... --preload=DIR/Stats.php                # façades generated with gen-facades.php --out=DIR
 *
 * Element-wise modules (`blocks`, generated by fixtures.py): every block is checked twice: once with arrays (the element loop, broadcasting, float64) and once with
 * PHP scalars on a sample of rows (the scalar path). A value passes when both are NaN, both are the same
 * infinity, or |got - want| <= atol + rtol |want| (defaults: rtol 1e-13, atol 0; per-function overrides in
 * the spec's `tol:`). Call-based modules (`calls`, generated by fixtures_np.py) replay each recorded call with
 * its keyword arguments as PHP named arguments and compare the result's kind (int/float/bool), shape and values
 * (default rtol 1e-12; NumPy's summation order is replicated, so most results are exact). Exit status 1 when
 * anything fails.
 */

declare(strict_types=1);

$opt = [];
foreach (array_slice($argv, 1) as $a) {
    if (preg_match('/^--([a-z-]+)(?:=(.*))?$/', $a, $m)) {
        $opt[$m[1]] = $m[2] ?? true;
    } elseif ($a === '-v') {
        $opt['verbose'] = true;
    }
}
// --preload=a.php,b.php: façade classes generated for a work-in-progress library (gen-facades.php --out=DIR)
foreach (isset($opt['preload']) ? explode(',', (string) $opt['preload']) : [] as $f) {
    require_once $f;
}
require dirname(__DIR__, 2) . '/tests/autoload.php';
$backend = $opt['backend'] ?? (extension_loaded('tessero') ? 'ext' : 'ffi');
$only = isset($opt['only']) ? array_flip(explode(',', (string) $opt['only'])) : null;
$verbose = isset($opt['verbose']);
$root = dirname(__DIR__, 2);
$files = isset($opt['fixtures']) ? [(string) $opt['fixtures']] : (glob("{$root}/tests/fixtures/parity/*.json") ?: []);
$record = ! isset($opt['no-record']);
if (isset($opt['module'])) {
    $files = array_filter($files, static fn (string $f): bool => basename($f, '.json') === $opt['module']);
}

$classes = [
    'ffi' => ['special' => \Tessero\Special::class, 'stats' => \Tessero\Stats::class, 'np' => \Tessero\Np::class,
        'linalg' => \Tessero\Linalg::class, 'slinalg' => \Tessero\ScipyLinalg::class, 'distance' => \Tessero\Distance::class, 'sparse' => \Tessero\Sparse::class, 'signal' => \Tessero\Signal::class, 'windows' => \Tessero\SignalWindows::class, 'ndimage' => \Tessero\Ndimage::class, 'csgraph' => \Tessero\Csgraph::class, 'interpolate' => \Tessero\Interpolate::class, 'cluster' => \Tessero\Cluster::class, 'npoly' => \Tessero\Polynomial::class, 'hierarchy' => \Tessero\Hierarchy::class, 'splinalg' => \Tessero\SparseLinalg::class, 'scipyfft' => \Tessero\ScipyFft::class, 'fft' => \Tessero\Fft\Fft::class, 'random' => \Tessero\Random\Generator::class],
    'ext' => ['special' => 'Tessero\\Ext\\Special', 'stats' => 'Tessero\\Ext\\Stats', 'np' => 'Tessero\\Ext\\Np',
        'linalg' => 'Tessero\\Ext\\Linalg', 'slinalg' => 'Tessero\\Ext\\ScipyLinalg', 'distance' => 'Tessero\\Ext\\Distance', 'sparse' => 'Tessero\\Ext\\Sparse', 'signal' => 'Tessero\\Ext\\Signal', 'windows' => 'Tessero\\Ext\\SignalWindows', 'ndimage' => 'Tessero\\Ext\\Ndimage', 'csgraph' => 'Tessero\\Ext\\Csgraph', 'interpolate' => 'Tessero\\Ext\\Interpolate', 'cluster' => 'Tessero\\Ext\\Cluster', 'npoly' => 'Tessero\\Ext\\Polynomial', 'hierarchy' => 'Tessero\\Ext\\Hierarchy', 'splinalg' => 'Tessero\\Ext\\SparseLinalg', 'scipyfft' => 'Tessero\\Ext\\ScipyFft', 'fft' => 'Tessero\\Ext\\Fft\\Fft', 'random' => 'Tessero\\Ext\\Random\\Generator'],
];
$arrayClass = $backend === 'ext' ? 'Tessero\\Ext\\NDArray' : \Tessero\NDArray::class;

function dec(mixed $v): ?float
{
    return match ($v) {
        'nan' => NAN, 'inf' => INF, '-inf' => -INF, 'undef' => null, default => (float) $v,
    };
}

function camelName(string $s): string
{
    $parts = explode('_', $s);
    $out = array_shift($parts);
    foreach ($parts as $p) {
        $out .= $p === '' ? '_' : ucfirst($p);   /* gen-facades.php camel(): lambda_ stays lambda_ */
    }

    return $out;
}

/** @return array{bool, float} ok, relative error (0 when exact) */
function close(float $got, float $want, float $rtol, float $atol): array
{
    if (is_nan($want)) {
        return [is_nan($got), is_nan($got) ? 0.0 : INF];
    }
    if (is_infinite($want)) {
        return [$got === $want, $got === $want ? 0.0 : INF];
    }
    if (is_nan($got) || is_infinite($got)) {
        return [false, INF];
    }
    $err = abs($got - $want);
    $rel = $want != 0.0 ? $err / abs($want) : $err;

    return [$err <= $atol + $rtol * abs($want), $rel];
}

/** Per-function tolerances for call fixtures, each with its reason (the default is rtol 1e-12). */
const CALL_RTOL = [
    // Generator draws run NumPy's own C code on the same PCG64 stream and, with the fixtures generated in the
    // pinned environment (tools/parity/fixture_env.py: NumPy's float64 loops are the C library's), must be
    // bit-identical
    'random' => 0.0,
    // multivariate_normal factorises cov by SVD and applies X @ factor by gemm; both differ from NumPy's
    // own LAPACK/BLAS in the last digits (cf. matrix_normal/wishart), so it cannot be bit-identical (ADR 0012).
    'multivariate_normal' => 1e-9,
    // LAPACK-backed polynomial helpers: a different LAPACK may differ in the last few digits (ADR 0012)
    'polyfit' => 1e-6,
    'roots' => 1e-6,
    'chebfit' => 1e-6, 'legfit' => 1e-6, 'lagfit' => 1e-6, 'hermfit' => 1e-6, 'hermefit' => 1e-6,
    // Gauss quadrature: eigenvalues of the companion + one Newton step may differ in the last couple of digits
    'leggauss' => 1e-9, 'laggauss' => 1e-9, 'hermgauss' => 1e-9, 'hermegauss' => 1e-9,
    // tensor B-spline: per-dimension de Boor composition sums in a different order than SciPy's direct tensor eval
    'NdBSpline' => 1e-9,
    // Newton-Cotes weights: solving the moment Vandermonde in float64 vs SciPy's exact-rational weights
    'newton_cotes' => 1e-6,
    // gaussian_kde: Cholesky-whitening sum accumulates slightly differently than SciPy's vectorized form
    'gaussian_kde' => 1e-9,
    // vonmises_fisher: normalization uses the modified Bessel I_v, which differs from SciPy in the last digits
    'vonmises_fisher' => 1e-9,
    // matrix-variate densities: Cholesky logdets + dgesv traces + multivariate log-gamma vs SciPy's own
    'matrix_normal' => 1e-8, 'wishart' => 1e-8, 'invwishart' => 1e-8,
];
// absolute tolerances: polyfit/roots/*fit coefficients can be legitimately ~0, where a relative tolerance is meaningless
const CALL_ATOL = ['polyfit' => 1e-8, 'roots' => 1e-8,
    'chebfit' => 1e-8, 'legfit' => 1e-8, 'lagfit' => 1e-8, 'hermfit' => 1e-8, 'hermefit' => 1e-8,
    'leggauss' => 1e-11, 'laggauss' => 1e-11, 'hermgauss' => 1e-11, 'hermegauss' => 1e-11];

function decodeValue(mixed $v, string $arrayClass): mixed
{
    if (! is_array($v)) {
        return is_string($v) ? dec($v) : $v;
    }
    if (isset($v['s'])) {
        return $v['s'];
    }
    if (array_key_exists('rng', $v)) {                         // a seeded numpy.random.default_rng
        $gen = str_contains($arrayClass, 'Ext') ? 'Tessero\\Ext\\Random\\Generator' : \Tessero\Random\Generator::class;

        return $gen::defaultRng($v['rng']);
    }
    if (array_key_exists('list', $v)) {
        return array_map(static fn ($x) => decodeValue($x, $arrayClass), $v['list']);
    }
    $data = array_map(static fn ($x) => is_string($x) ? dec($x) : $x, $v['data']);
    if (($v['dtype'] ?? '') === 'complex128') {          // interleaved [re, im, ...] -> a complex NDArray
        $re = [];
        $im = [];
        foreach ($data as $j => $val) {
            if ($j % 2 === 0) {
                $re[] = $val;
            } else {
                $im[] = $val;
            }
        }
        $a = $arrayClass::complex($arrayClass::array($re, 'float64'), $arrayClass::array($im, 'float64'));

        return $v['shape'] === [count($re)] ? $a : $a->reshape($v['shape']);
    }
    $a = $arrayClass::array($data, $v['dtype']);

    return $v['shape'] === [count($data)] ? $a : $a->reshape($v['shape']);
}

function kindOf(mixed $v): string
{
    return is_bool($v) ? 'bool' : (is_int($v) ? 'int' : 'float');
}

function dtypeKind(object $a): string
{
    $d = $a->dtype();
    $d = is_string($d) ? $d : strtolower($d->name);

    return str_starts_with($d, 'int') || str_starts_with($d, 'uint') ? 'int' : ($d === 'bool' ? 'bool' : 'float');
}

function describeCall(array $case): string
{
    $f = static function ($v) use (&$f): string {
        if (! is_array($v)) {
            return var_export($v, true);
        }
        if (isset($v['s'])) {
            return "'{$v['s']}'";
        }
        if (array_key_exists('list', $v)) {
            return '[' . implode(', ', array_map($f, $v['list'])) . ']';
        }
        $n = count($v['data']);

        return $v['dtype'] . '(' . implode('x', $v['shape']) . ')' . ($n <= 6 ? json_encode($v['data']) : '');
    };
    $parts = array_map($f, $case['args']);
    foreach ($case['kwargs'] as $k => $v) {
        $parts[] = camelName($k) . ': ' . $f($v);
    }

    return '(' . implode(', ', $parts) . ')';
}

/** Compare one expected (encoded) value with what Tessero returned; null when they agree. */
function compareValue(mixed $want, mixed $got, float $rtol, float $atol, float &$worst): ?string
{
    if (is_array($want) && array_key_exists('list', $want)) {    // a pair (support, interval)
        if (! is_array($got) || count($got) !== count($want['list'])) {
            return 'expected a list of ' . count($want['list']) . ' values, got ' . get_debug_type($got);
        }
        foreach (array_values($want['list']) as $i => $w) {
            $p = compareValue($w, array_values($got)[$i], $rtol, $atol, $worst);
            if ($p !== null) {
                return "[{$i}] {$p}";
            }
        }

        return null;
    }
    if (is_array($want) && isset($want['dict'])) {
        if (! is_array($got)) {
            return 'expected keys ' . implode(',', array_keys($want['dict'])) . ', got ' . get_debug_type($got);
        }
        if (array_keys($want['dict']) !== array_keys($got)) {
            return 'expected keys ' . implode(',', array_keys($want['dict'])) . ', got ' . implode(',', array_keys($got));
        }
        foreach ($want['dict'] as $k => $w) {
            $p = compareValue($w, $got[$k], $rtol, $atol, $worst);
            if ($p !== null) {
                return "[{$k}] {$p}";
            }
        }

        return null;
    }
    if (is_array($want) && isset($want['s'])) {              // a string result (e.g. a dtype name)
        return is_string($got) && $got === $want['s'] ? null : 'got ' . var_export($got, true) . " want '{$want['s']}'";
    }
    if (is_array($want) && isset($want['bytes'])) {          // numpy.random.Generator.bytes: raw bytes, hex-compared
        return is_string($got) && bin2hex($got) === $want['bytes'] ? null
            : 'bytes differ: got ' . (is_string($got) ? bin2hex($got) : get_debug_type($got)) . " want {$want['bytes']}";
    }
    if (is_array($want)) {                                   // an array
        if (! is_object($got)) {
            return 'expected an array of shape (' . implode(',', $want['shape']) . '), got ' . var_export($got, true);
        }
        if ($got->shape() !== $want['shape']) {
            return 'shape (' . implode(',', $got->shape()) . ') instead of (' . implode(',', $want['shape']) . ')';
        }
        if ($want['dtype'] === 'complex128') {              // interleaved [re, im, ...]; compare parts (toList of
            $re = $got->real()->toList();                   // a complex array is not portable across backends)
            $im = $got->imag()->toList();
            $nel = intdiv(count($want['data']), 2);
            for ($i = 0; $i < $nel; $i++) {
                $wr = is_string($want['data'][2 * $i]) ? dec($want['data'][2 * $i]) : $want['data'][2 * $i];
                $wi = is_string($want['data'][2 * $i + 1]) ? dec($want['data'][2 * $i + 1]) : $want['data'][2 * $i + 1];
                [$ok1, $r1] = close((float) $re[$i], (float) $wr, $rtol, $atol);
                [$ok2, $r2] = close((float) $im[$i], (float) $wi, $rtol, $atol);
                if ($r1 !== INF && $r1 > $worst) { $worst = $r1; }
                if ($r2 !== INF && $r2 > $worst) { $worst = $r2; }
                if (! $ok1 || ! $ok2) {
                    return sprintf('element %d: got %.17g%+.17gi want %.17g%+.17gi', $i, (float) $re[$i], (float) $im[$i], (float) $wr, (float) $wi);
                }
            }

            return null;
        }
        $wk = $want['dtype'] === 'int64' ? 'int' : ($want['dtype'] === 'bool' ? 'bool' : 'float');
        if (dtypeKind($got) !== $wk) {
            return 'dtype kind ' . dtypeKind($got) . " instead of {$wk}";
        }
        $vals = $got->toList();
        foreach ($want['data'] as $i => $w) {
            $w = is_string($w) ? dec($w) : $w;
            if (is_int($w) && is_int($vals[$i])) {            // integers compare exactly (float64 rounds above 2^53)
                if ($vals[$i] !== $w) {
                    return sprintf('element %d: got %d want %d', $i, $vals[$i], $w);
                }
                continue;
            }
            [$ok, $rel] = close((float) $vals[$i], (float) $w, $rtol, $atol);
            if ($rel !== INF && $rel > $worst) {
                $worst = $rel;
            }
            if (! $ok) {
                return sprintf('element %d: got %.17g want %.17g', $i, $vals[$i], $w);
            }
        }

        return null;
    }
    $w = is_string($want) ? dec($want) : $want;
    if (is_object($got)) {
        return 'expected a scalar, got an array of shape (' . implode(',', $got->shape()) . ')';
    }
    if (kindOf($got) !== kindOf($w) && ! ($GLOBALS['scalarKindLoose'] && ! is_bool($got) && ! is_bool($w))) {
        return 'scalar kind ' . kindOf($got) . ' instead of ' . kindOf($w) . sprintf(' (%s vs %s)', var_export($got, true), var_export($w, true));
    }
    if (is_int($got) && is_int($w)) {
        return $got === $w ? null : sprintf('got %d want %d', $got, $w);
    }
    [$ok, $rel] = close((float) $got, (float) $w, $rtol, $atol);
    if ($rel !== INF && $rel > $worst) {
        $worst = $rel;
    }

    return $ok ? null : sprintf('got %.17g want %.17g', $got, $w);
}

/** partition / argpartition: NumPy fixes only the kth element and the invariant, so check exactly that. */
function comparePartition(string $method, array $case, mixed $got, string $arrayClass): ?string
{
    $want = $case['expect'];
    if (! is_object($got) || $got->shape() !== $want['shape']) {
        return 'shape mismatch';
    }
    $a = $case['args'][0];
    $in = array_map(static fn ($x) => is_string($x) ? dec($x) : $x, $a['data']);
    $shape = $a['shape'];
    $axis = $case['kwargs']['axis'] ?? -1;
    $nd = count($shape);
    $axis = $axis < 0 ? $axis + $nd : $axis;
    $kth = $case['args'][1];
    $kths = is_array($kth) ? array_map('intval', $kth['data'] ?? $kth['list']) : [(int) $kth];
    $g = $got->toList();
    $strides = [];
    $st = 1;
    for ($d = $nd - 1; $d >= 0; $d--) {
        $strides[$d] = $st;
        $st *= $shape[$d];
    }
    $len = $shape[$axis];
    $total = array_product($shape);
    $key = static fn (float $x): float => is_nan($x) ? INF : $x;
    for ($base = 0; $base < $total; $base++) {
        if (intdiv($base, $strides[$axis]) % $len !== 0) {
            continue;                                         // not the start of a lane
        }
        $lane = [];
        $orig = [];
        for ($i = 0; $i < $len; $i++) {
            $idx = $base + $i * $strides[$axis];
            $v = $g[$idx];
            if ($method === 'argpartition') {
                if (! is_int($v) || $v < 0 || $v >= $len) {
                    return "index {$v} out of range";
                }
                $v = $in[$base + $v * $strides[$axis]];
            }
            $lane[] = (float) $v;
            $orig[] = (float) $in[$idx];
        }
        $s1 = $orig;
        $s2 = $lane;
        usort($s1, static fn ($x, $y) => $key($x) <=> $key($y));
        usort($s2, static fn ($x, $y) => $key($x) <=> $key($y));
        if (array_map('strval', $s1) !== array_map('strval', $s2)) {
            return 'not a permutation of the input lane';
        }
        foreach ($kths as $k) {
            $k = $k < 0 ? $k + $len : $k;
            if (strval($lane[$k]) !== strval($s1[$k])) {
                return "kth {$k}: got {$lane[$k]} want {$s1[$k]}";
            }
            for ($i = 0; $i < $len; $i++) {
                if (($i < $k && $key($lane[$i]) > $key($lane[$k])) || ($i > $k && $key($lane[$i]) < $key($lane[$k]))) {
                    return "partition invariant broken at {$i} around kth {$k}";
                }
            }
        }
    }

    return null;
}

/**
 * maximum_flow: flow value unique (checked exactly); .flow NON-UNIQUE, validated semantically
 * (integer, antisymmetric, capacity bound, conservation) against the capacity matrix from args[0].
 */
function compareMaxflow(array $case, mixed $got): ?string
{
    $wantFv = $case['expect']['flow_value'] ?? $case['expect'];   // integer, exact
    if (! is_array($got) || ! array_key_exists('flow_value', $got) || ! array_key_exists('flow', $got)) {
        return 'expected a {flow_value, flow} result, got ' . get_debug_type($got);
    }
    $fv = $got['flow_value'];
    if (! is_int($fv) || $fv !== (int) $wantFv) {
        return sprintf('flow_value got %s want %d', var_export($fv, true), (int) $wantFv);
    }
    $flow = $got['flow'];
    if (! is_object($flow)) {
        return 'flow must be a matrix, got ' . get_debug_type($flow);
    }

    // capacity matrix, recomputed from args[0] (the original capacities), like comparePartition.
    $a = $case['args'][0];
    $cap = array_map(static fn ($x) => is_string($x) ? dec($x) : $x, $a['data']);
    $shape = $a['shape'];
    $n = $shape[0];
    if (count($shape) !== 2 || $shape[0] !== $shape[1]) {
        return 'capacity must be a square matrix';
    }
    $s = (int) $case['args'][1];
    $t = (int) $case['args'][2];

    if ($flow->shape() !== [$n, $n]) {
        return 'flow shape ' . implode(',', $flow->shape()) . " != {$n},{$n}";
    }
    $F = $flow->toList();                                         // row-major, length n*n
    $at = static fn (array $m, int $i, int $j) => $m[$i * $n + $j];

    // all integer
    foreach ($F as $v) {
        if (((float) $v) !== floor((float) $v)) {
            return 'flow has a non-integer entry';
        }
    }
    // antisymmetry: F[i][j] == -F[j][i]
    for ($i = 0; $i < $n; $i++) {
        for ($j = 0; $j < $n; $j++) {
            if ((int) $at($F, $i, $j) !== -(int) $at($F, $j, $i)) {
                return "flow not antisymmetric at {$i},{$j}";
            }
        }
    }
    // capacity bound on positive (forward) flow: 0 <= F[i][j] <= cap[i][j]
    for ($i = 0; $i < $n; $i++) {
        for ($j = 0; $j < $n; $j++) {
            $f = (int) $at($F, $i, $j);
            if ($f > 0 && $f > (int) $at($cap, $i, $j)) {
                return "flow {$f} exceeds capacity " . (int) $at($cap, $i, $j) . " at {$i},{$j}";
            }
        }
    }
    // conservation: every node except source/sink has zero net out-flow (sum of its row of F)
    for ($u = 0; $u < $n; $u++) {
        if ($u === $s || $u === $t) {
            continue;
        }
        $net = 0;
        for ($j = 0; $j < $n; $j++) {
            $net += (int) $at($F, $u, $j);
        }
        if ($net !== 0) {
            return "conservation broken at node {$u}: net {$net}";
        }
    }
    // source net out = +flow_value, sink net out = -flow_value
    $src = 0; $snk = 0;
    for ($j = 0; $j < $n; $j++) {
        $src += (int) $at($F, $s, $j);
        $snk += (int) $at($F, $t, $j);
    }
    if ($src !== $fv) {
        return "source net {$src} != flow_value {$fv}";
    }
    if ($snk !== -$fv) {
        return "sink net {$snk} != -flow_value {$fv}";
    }
    return null;
}

/**
 * reverse_cuthill_mckee: the RCM permutation is non-unique (degree ties); the fitted
 * permutation is validated to be a valid permutation achieving scipy's permuted bandwidth.
 */
function compareRcmBandwidth(array $case, mixed $got): ?string
{
    $wantBw = (int) $case['expect'];                             // scipy's permuted bandwidth, exact
    if (! is_object($got)) {
        return 'expected a node_array, got ' . get_debug_type($got);
    }
    // adjacency recomputed from args[0] (the original dense matrix), like comparePartition/compareMaxflow.
    $a = $case['args'][0];
    $A = array_map(static fn ($x) => is_string($x) ? dec($x) : $x, $a['data']);
    $shape = $a['shape'];
    if (count($shape) !== 2 || $shape[0] !== $shape[1]) {
        return 'graph must be a square matrix';
    }
    $n = (int) $shape[0];
    if ($got->shape() !== [$n]) {
        return 'perm shape ' . implode(',', $got->shape()) . " != {$n}";
    }
    $perm = array_map('intval', $got->toList());
    // valid permutation of 0..n-1
    $seen = $perm;
    sort($seen);
    if ($seen !== range(0, $n - 1)) {
        return 'result is not a valid permutation of 0..' . ($n - 1);
    }
    // pos[old node] = new position
    $pos = array_fill(0, $n, 0);
    foreach ($perm as $newpos => $old) {
        $pos[$old] = $newpos;
    }
    $at = static fn (array $m, int $i, int $j) => $m[$i * $n + $j];
    $bw = 0;
    for ($i = 0; $i < $n; $i++) {
        for ($j = 0; $j < $n; $j++) {
            if ($i !== $j && ((float) $at($A, $i, $j) !== 0.0 || (float) $at($A, $j, $i) !== 0.0)) {
                $d = abs($pos[$i] - $pos[$j]);
                if ($d > $bw) { $bw = $d; }
            }
        }
    }
    if ($bw !== $wantBw) {
        return "permuted bandwidth {$bw} != scipy {$wantBw}";
    }

    return null;
}

/**
 * maximum_bipartite_matching: the matching is non-unique; validated semantically against the
 * biadjacency from args[0] (valid structural edges, no row/col reused) with scipy's matching size.
 */
function compareBipartiteMatch(array $case, mixed $got): ?string
{
    $wantSize = (int) ($case['expect']['size'] ?? $case['expect']);
    if (! is_object($got)) {
        return 'expected a matching array, got ' . get_debug_type($got);
    }
    // biadjacency structure recomputed from args[0] (rows x columns), like compareMaxflow.
    $a = $case['args'][0];
    $shape = $a['shape'];
    if (count($shape) !== 2) {
        return 'graph must be a 2-D biadjacency';
    }
    [$m, $n] = [(int) $shape[0], (int) $shape[1]];
    $data = array_map(static fn ($x) => is_string($x) ? dec($x) : $x, $a['data']);
    $edge = static fn (int $i, int $j): bool => ((float) $data[$i * $n + $j]) !== 0.0;

    $out = $got->toList();
    // perm_type='row' (the default): one entry per COLUMN; entry j = row matched to col j, or -1.
    // perm_type='column': one entry per ROW; entry i = column matched to row i, or -1.
    $len = count($out);
    if ($len !== $n && $len !== $m) {
        return "matching length {$len} is neither n_columns {$n} nor n_rows {$m}";
    }
    $byColumn = ($len === $n);                 // length n => row-perm (indexed by column)
    $usedRow = [];
    $usedCol = [];
    $size = 0;
    foreach ($out as $k => $v) {
        $v = (int) $v;
        if ($v === -1) {
            continue;
        }
        // (row, col) pair depending on orientation
        [$row, $col] = $byColumn ? [$v, (int) $k] : [(int) $k, $v];
        if ($row < 0 || $row >= $m || $col < 0 || $col >= $n) {
            return "matched index out of range at {$k}";
        }
        if (! $edge($row, $col)) {
            return "matched pair ({$row},{$col}) is not a structural edge";
        }
        if (isset($usedRow[$row])) {
            return "row {$row} matched twice";
        }
        if (isset($usedCol[$col])) {
            return "column {$col} matched twice";
        }
        $usedRow[$row] = true;
        $usedCol[$col] = true;
        $size++;
    }
    if ($size !== $wantSize) {
        return "matching size {$size} != expected {$wantSize}";
    }
    return null;
}

/** scipy.integrate.dblquad/tplquad/nquad named integrands + limits (the PHP runner rebuilds them). */
function makeIntegrand2(string $kind): callable {   // func(y, x)
    return match ($kind) {
        'xy' => fn ($y, $x) => $x * $y,
        'gauss2d' => fn ($y, $x) => exp(-($x * $x + $y * $y)),
        'triangle' => fn ($y, $x) => 1.0,
        'affinef' => fn ($y, $x) => $x + $y,
        'sincos' => fn ($y, $x) => sin($x) * cos($y),
        default => throw new \RuntimeException("integrand2 {$kind}"),
    };
}
function makeIntegrand3(string $kind): callable {   // func(z, y, x)
    return match ($kind) {
        'unitcube' => fn ($z, $y, $x) => 1.0,
        'xyzcube' => fn ($z, $y, $x) => $x * $y * $z,
        'simplex' => fn ($z, $y, $x) => 1.0,
        default => throw new \RuntimeException("integrand3 {$kind}"),
    };
}
function makeFixedIntegrand(string $kind): callable {   // nquad func(...x)
    return match ($kind) {
        'xy' => fn (...$a) => $a[0] * $a[1],
        'xyz' => fn (...$a) => $a[0] + $a[1] + $a[2],
        'gauss2' => fn (...$a) => exp(-($a[0] * $a[0] + $a[1] * $a[1])),
        default => throw new \RuntimeException("fixedintegrand {$kind}"),
    };
}
function makeLimit1(array $spec): callable {    // g(x)
    if (isset($spec['const'])) { return fn ($x) => (float) $spec['const']; }
    if (isset($spec['affine'])) { return fn ($x) => $spec['affine'][0] + $spec['affine'][1] * $x; }
    if (isset($spec['affine_x'])) { return fn ($x) => $spec['affine_x'][0] + $spec['affine_x'][1] * $x; }
    throw new \RuntimeException('limit1');
}
function makeLimit2(array $spec): callable {    // q(x, y)
    if (isset($spec['const'])) { return fn ($x, $y) => (float) $spec['const']; }
    if (isset($spec['affine_xy'])) { return fn ($x, $y) => $spec['affine_xy'][0] + $spec['affine_xy'][1] * $x + $spec['affine_xy'][2] * $y; }
    throw new \RuntimeException('limit2');
}
function makeTerm(string $kind, array $p): callable {   // scipy.integrate.nsum term f(i)
    return match ($kind) {
        'inv_pow' => fn ($i) => 1.0 / ($i ** $p['p']),
        'geom' => fn ($i) => $p['r'] ** $i,
        'linear' => fn ($i) => $p['m'] * $i + $p['c'],
        'expneg' => fn ($i) => exp(-$p['rate'] * $i),
        default => throw new \RuntimeException("term {$kind}"),
    };
}


/** Rebuild a named bootstrap / monte_carlo_test statistic (scipy.stats fixtures) as a callable. */
function makeStat(string $kind): callable
{
    return match ($kind) {
        'mean'     => static fn (array $x): float => array_sum($x) / count($x),
        'std'      => static function (array $x): float {
            $m = array_sum($x) / count($x); $s = 0.0;
            foreach ($x as $v) { $d = $v - $m; $s += $d * $d; }
            return sqrt($s / count($x));
        },
        'median'   => static function (array $x): float {
            $s = $x; sort($s); $n = count($s);
            return $n % 2 ? (float) $s[intdiv($n, 2)] : ($s[$n / 2 - 1] + $s[$n / 2]) / 2.0;
        },
        'diffmean' => static fn (array $a, array $b): float => array_sum($a) / count($a) - array_sum($b) / count($b),
        'range'    => static fn (array $x): float => max($x) - min($x),
        'skew'     => static function (array $x): float {
            $n = count($x); $m = array_sum($x) / $n; $m2 = 0.0; $m3 = 0.0;
            foreach ($x as $v) { $d = $v - $m; $m2 += $d * $d; $m3 += $d * $d * $d; }
            $m2 /= $n; $m3 /= $n;
            return $m2 == 0.0 ? 0.0 : $m3 / ($m2 ** 1.5);
        },
        default    => throw new \RuntimeException("unknown stat '{$kind}'"),
    };
}

function runCall(string|object $class, string $method, array $case, string $arrayClass, float $rtol, float $atol, float &$worst): ?string
{
    $args = array_map(static fn ($v) => decodeValue($v, $arrayClass), $case['args']);
    foreach ($case['kwargs'] as $k => $v) {
        $args[camelName($k)] = decodeValue($v, $arrayClass);
    }
    $want = $case['expect'];
    try {
        $got = [$class, $method](...$args);
        if (($case['compare'] ?? 'tol') === 'inplace' && ! (is_array($want) && isset($want['error']))) {
            // numpy.put, place, copyto ...: None is returned and the first argument holds the result
            if ($got !== null) {
                return 'expected null (the array is modified in place), got ' . get_debug_type($got);
            }
            $got = $args[0];
        }
    } catch (\Throwable $e) {
        if (is_array($want) && isset($want['error'])) {
            return null;                                      // NumPy raises too
        }

        return 'threw ' . get_class($e) . ': ' . $e->getMessage();
    }
    if (is_array($want) && isset($want['error'])) {
        return "NumPy raises {$want['error']}, Tessero returned " . get_debug_type($got);
    }
    if (($case['compare'] ?? 'tol') === 'shape') {         // numpy.empty_like: only the shape and dtype are specified
        if (! is_object($got) || ! is_array($want) || ! isset($want['shape'])) {
            return is_object($got) || ! is_array($want) ? null : 'expected an array';
        }
        $wk = $want['dtype'] === 'int64' ? 'int' : ($want['dtype'] === 'bool' ? 'bool' : 'float');

        return $got->shape() !== $want['shape'] ? 'shape mismatch' : (dtypeKind($got) !== $wk ? 'dtype kind ' . dtypeKind($got) . " instead of {$wk}" : null);
    }
    if (($case['compare'] ?? 'tol') === 'partition') {
        return comparePartition($method, $case, $got, $arrayClass);
    }
    if (($case['compare'] ?? 'tol') === 'maxflow') {
        return compareMaxflow($case, $got);
    }
    if (($case['compare'] ?? 'tol') === 'rcm_bandwidth') {
        return compareRcmBandwidth($case, $got);
    }
    if (($case['compare'] ?? 'tol') === 'bipartite_match') {
        return compareBipartiteMatch($case, $got);
    }
    if (($case['compare'] ?? 'tol') === 'sorted' && is_object($got) && is_array($want) && isset($want['data'])) {
        $key = static fn ($x): float => is_nan((float) $x) ? INF : (float) $x;
        $w = array_map(static fn ($x) => is_string($x) ? dec($x) : $x, $want['data']);
        usort($w, static fn ($a, $b) => $key($a) <=> $key($b));
        $want['data'] = $w;
        $vals = $got->toList();
        usort($vals, static fn ($a, $b) => $key($a) <=> $key($b));
        $got = $arrayClass::array($vals, $got->dtype());
    }

    return compareValue($want, $got, $rtol, $atol, $worst);
}

/** Rebuild a named objective (used by the scipy.optimize solver fixtures) as a PHP callable. */
function makeTaylorFunc(string $kind): callable {
    return match ($kind) {
        'sinx'    => static fn (float $z): float => sin($z),
        'expx'    => static fn (float $z): float => exp($z),
        'cos2x'   => static fn (float $z): float => cos(2.0 * $z),
        'lorentz' => static fn (float $z): float => 1.0 / (1.0 + $z * $z),
        'gauss'   => static fn (float $z): float => exp(-$z * $z),
        default   => throw new \RuntimeException("unknown taylor func '{$kind}'"),
    };
}

function makeConProblem(string $prob): array
{
    $rosen = static function (array $x): float {
        $s = 0.0;
        for ($i = 0, $n = count($x); $i < $n - 1; $i++) { $s += 100.0 * ($x[$i + 1] - $x[$i] ** 2) ** 2 + (1.0 - $x[$i]) ** 2; }
        return $s;
    };
    $rd = static fn (array $x): array => \Tessero\Optimize\Minimize::rosenDer($x);
    $cfun = [
        'sum_m1' => static fn (array $x): float => $x[0] + $x[1] - 1,
        'g1' => static fn (array $x): float => $x[0] - 2 * $x[1] + 2,
        'g2' => static fn (array $x): float => -$x[0] - 2 * $x[1] + 6,
        'g3' => static fn (array $x): float => -$x[0] + 2 * $x[1] + 2,
        'h1' => static fn (array $x): float => 1 - $x[0] - 2 * $x[1],
        'h2' => static fn (array $x): float => $x[0],
        'h3' => static fn (array $x): float => $x[1],
        'line' => static fn (array $x): float => $x[0] + $x[1] - 1,
    ];
    $con = static fn (array $names, string $type) => array_map(static fn ($n) => ['type' => $type, 'fun' => $cfun[$n]], $names);
    return match ($prob) {
        'rosen2'    => ['f' => $rosen, 'jac' => $rd, 'x0' => [-1.2, 1.0], 'bounds' => [[-2, 2], [-2, 2]], 'cons' => []],
        'rosen4'    => ['f' => $rosen, 'jac' => $rd, 'x0' => [0.0, 0.0, 0.0, 0.0], 'bounds' => [[-5, 5], [-5, 5], [-5, 5], [-5, 5]], 'cons' => []],
        'quad2'     => ['f' => static fn (array $x): float => ($x[0] - 2) ** 2 + ($x[1] + 3) ** 2, 'jac' => static fn (array $x): array => [2 * ($x[0] - 2), 2 * ($x[1] + 3)], 'x0' => [0, 0], 'bounds' => [[0, 1], [-1, 1]], 'cons' => []],
        'quad3'     => ['f' => static fn (array $x): float => ($x[0] - 1) ** 2 + ($x[1] - 2) ** 2 + ($x[2] + 1) ** 2, 'jac' => static fn (array $x): array => [2 * ($x[0] - 1), 2 * ($x[1] - 2), 2 * ($x[2] + 1)], 'x0' => [0, 0, 0], 'bounds' => null, 'cons' => []],
        'sphere_lo' => ['f' => static fn (array $x): float => $x[0] ** 2 + $x[1] ** 2, 'jac' => static fn (array $x): array => [2 * $x[0], 2 * $x[1]], 'x0' => [3, 3], 'bounds' => [[1, null], [2, null]], 'cons' => []],
        'sphere_eq' => ['f' => static fn (array $x): float => $x[0] ** 2 + $x[1] ** 2, 'jac' => null, 'x0' => [2, 2], 'bounds' => null, 'cons' => $con(['sum_m1'], 'eq')],
        'qp_tri'    => ['f' => static fn (array $x): float => ($x[0] - 1) ** 2 + ($x[1] - 2.5) ** 2, 'jac' => null, 'x0' => [2, 0], 'bounds' => [[0, null], [0, null]], 'cons' => $con(['g1', 'g2', 'g3'], 'ineq')],
        'qp_tri0'   => ['f' => static fn (array $x): float => ($x[0] - 1) ** 2 + ($x[1] - 2.5) ** 2, 'jac' => null, 'x0' => [0, 0], 'bounds' => null, 'cons' => $con(['g1', 'g2', 'g3'], 'ineq')],
        'rosen_con' => ['f' => $rosen, 'jac' => null, 'x0' => [0.5, 0.0], 'bounds' => null, 'cons' => $con(['h1', 'h2', 'h3'], 'ineq')],
        'sphere_line' => ['f' => static fn (array $x): float => $x[0] ** 2 + $x[1] ** 2, 'jac' => null, 'x0' => [2, 2], 'bounds' => null, 'cons' => $con(['line'], 'ineq')],
        'uncon'     => ['f' => static fn (array $x): float => ($x[0] - 3) ** 2 + ($x[1] + 1) ** 2, 'jac' => null, 'x0' => [0, 0], 'bounds' => null, 'cons' => []],
        default     => throw new \RuntimeException("makeConProblem: unknown prob '{$prob}'"),
    };
}

function makeQmcIntegrand(string $kind): callable
{
    // integrand receives an n_points x d list of points, returns n_points scalars
    switch ($kind) {
        case 'sum':
            return static fn (array $x) => array_map(static fn ($p) => array_sum($p), $x);
        case 'gauss':
            return static fn (array $x) => array_map(static fn ($p) => exp(-array_sum(array_map(static fn ($v) => $v * $v, $p))), $x);
        case 'cosprod':
            return static fn (array $x) => array_map(static fn ($p) => array_product(array_map('cos', $p)), $x);
        case 'sumsq1':
            return static fn (array $x) => array_map(static fn ($p) => array_sum(array_map(static fn ($v) => $v * $v, $p)) + 1.0, $x);
        case 'invsum':
            return static fn (array $x) => array_map(static fn ($p) => 1.0 / (1.0 + array_sum($p)), $x);
        default:
            throw new \RuntimeException("unknown qmc integrand kind {$kind}");
    }
}

function makeLinOpMatrix(string $kind): array
{
    return match ($kind) {
        'm33a' => [[1.0, 2.0, 0.0], [0.0, 3.0, 1.0], [4.0, 0.0, 2.0]],
        'm33b' => [[2.0, 0.0, 1.0], [1.0, 1.0, 0.0], [0.0, 2.0, 3.0]],
        'm23'  => [[1.0, -2.0, 3.0], [0.5, 4.0, -1.0]],
        'm32'  => [[2.0, 1.0], [-1.0, 3.0], [0.0, 2.0]],
        'm44'  => [[1.0, 0.0, -1.0, 2.0], [3.0, 2.0, 0.0, 1.0], [0.0, 1.0, 4.0, -2.0], [2.0, -1.0, 1.0, 3.0]],
        's33'  => [[2.0, -1.0, 0.0], [-1.0, 2.0, -1.0], [0.0, -1.0, 2.0]],
        default => throw new \RuntimeException("unknown linop kind '{$kind}'"),
    };
}

function buildLinOp(string $kind, string $source): \Tessero\Sparse\Linalg\LinearOperator
{
    $A = makeLinOpMatrix($kind);
    if ($source === 'matrix') { return \Tessero\Sparse\Linalg\LinearOperator::fromMatrix($A); }
    if ($source === 'csr') {
        $m = count($A); $n = count($A[0]); $data = []; $indices = []; $indptr = [0];
        for ($i = 0; $i < $m; $i++) { for ($j = 0; $j < $n; $j++) { $v = (float) $A[$i][$j]; if ($v !== 0.0) { $data[] = $v; $indices[] = $j; } } $indptr[] = count($data); }
        return \Tessero\Sparse\Linalg\Aslinearoperator::aslinearoperator(['data' => $data, 'indices' => $indices, 'indptr' => $indptr, 'shape' => [$m, $n]]);
    }
    $m = count($A); $n = count($A[0]);
    $mv = static function (array $x) use ($A, $m, $n): array { $o = []; for ($i = 0; $i < $m; $i++) { $t = 0.0; for ($j = 0; $j < $n; $j++) { $t += $A[$i][$j] * $x[$j]; } $o[] = $t; } return $o; };
    $rmv = static function (array $y) use ($A, $m, $n): array { $o = array_fill(0, $n, 0.0); for ($i = 0; $i < $m; $i++) { for ($j = 0; $j < $n; $j++) { $o[$j] += $A[$i][$j] * $y[$i]; } } return $o; };
    return \Tessero\Sparse\Linalg\LinearOperator::fromCallbacks([$m, $n], $mv, $rmv);
}

function runLinopCase(array $c): array
{
    if ($c['op'] === 'linop') {
        $op = buildLinOp($c['kind'], $c['source']);
        $act = $c['act'];
        if ($act === 'sum') { $op2 = buildLinOp($c['kind2'], 'matrix'); return $op->add($op2)->matvec($c['x']); }
        if ($act === 'scale') { return $op->scale((float) $c['scalar'])->matvec($c['x']); }
        if ($act === 'compose') { $op2 = buildLinOp($c['kind2'], 'matrix'); return $op->compose($op2)->matvec($c['x']); }
        if ($act === 'scaledsum') { $op2 = buildLinOp($c['kind2'], 'matrix'); return $op->scale((float) $c['scalar'])->add($op2)->matvec($c['x']); }
        if ($act === 'matvec') { return $op->matvec($c['x']); }
        if ($act === 'dot') { return $op->dot($c['x']); }
        if ($act === 'rmatvec') { return $op->rmatvec($c['x']); }
        if ($act === 'H.matvec') { return $op->getH()->matvec($c['x']); }
        if ($act === 'T.matvec') { return $op->getT()->matvec($c['x']); }
        if ($act === 'matmat') { return $op->matmat($c['X']); }
        throw new \RuntimeException("unknown act '{$act}'");
    }
    if ($c['op'] === 'laplacian') {
        $lap = new \Tessero\Sparse\Linalg\LaplacianNd($c['grid'], $c['bc']);
        $method = $c['method'];
        if ($method === 'toarray') { return $lap->toarray(); }
        if ($method === 'tosparse') { return $lap->tosparse(); }
        if ($method === 'eigenvalues') { return isset($c['m']) ? $lap->eigenvalues((int) $c['m']) : $lap->eigenvalues(); }
        if ($method === 'matvec') { return $lap->matvec($c['x']); }
        throw new \RuntimeException("unknown method '{$method}'");
    }
    throw new \RuntimeException("unknown op '{$c['op']}'");
}

function makeSobolIndicesFunc(string $kind): callable
{
    return match ($kind) {
        'ishigami' => static function (array $x): array {
            $n = count($x[0]); $o = [];
            for ($k = 0; $k < $n; $k++) {
                $o[$k] = sin($x[0][$k]) + 7 * sin($x[1][$k]) ** 2 + 0.1 * ($x[2][$k] ** 4) * sin($x[0][$k]);
            }
            return $o;
        },
        'linear' => static function (array $x): array {
            $n = count($x[0]); $o = [];
            for ($k = 0; $k < $n; $k++) { $o[$k] = $x[0][$k] + 2 * $x[1][$k] + 3 * $x[2][$k]; }
            return $o;
        },
        'poly' => static function (array $x): array {
            $n = count($x[0]); $o = [];
            for ($k = 0; $k < $n; $k++) { $o[$k] = $x[0][$k] ** 2 + $x[1][$k] * $x[2][$k] + sin($x[0][$k]); }
            return $o;
        },
        'sum4' => static function (array $x): array {
            $n = count($x[0]); $o = [];
            for ($k = 0; $k < $n; $k++) { $o[$k] = $x[0][$k] + $x[1][$k] + $x[2][$k] + $x[3][$k]; }
            return $o;
        },
        default => throw new RuntimeException("unknown sobol_indices kind $kind"),
    };
}

function makeObjective(array $spec): callable
{
    return match ($spec['kind']) {
        'poly' => static function (float $x) use ($spec): float { $s = 0.0; $p = 1.0; foreach ($spec['c'] as $ck) { $s += $ck * $p; $p *= $x; } return $s; },
        'cosx' => static fn (float $x): float => cos($x) - $x,
        'gauss' => static fn (float $x): float => exp(-$x * $x),
        'sinx' => static fn (float $x): float => sin($x),
        'lorentz' => static fn (float $x): float => 1.0 / (1.0 + $x * $x),
        'invsqrt' => static fn (float $x): float => 1.0 / sqrt($x),
        'logx' => static fn (float $x): float => log($x),
        'rosen' => static function (array $x): float { $s = 0.0; for ($i = 0, $n = count($x); $i < $n - 1; $i++) { $s += 100.0 * ($x[$i + 1] - $x[$i] ** 2) ** 2 + (1.0 - $x[$i]) ** 2; } return $s; },
        // vector residuals for leastsq (data embedded in the spec)
        'linresid' => static function (array $p) use ($spec): array { $r = []; foreach ($spec['x'] as $i => $xi) { $r[] = $p[0] * $xi + $p[1] - $spec['y'][$i]; } return $r; },
        'expresid' => static function (array $p) use ($spec): array { $r = []; foreach ($spec['x'] as $i => $xi) { $r[] = $p[0] * exp($p[1] * $xi) + $p[2] - $spec['y'][$i]; } return $r; },
        'vecsys' => static fn (array $x): array => [$x[0] - 0.5 * cos($x[1]) - 0.5, $x[1] - 0.5 * sin($x[0]) - 0.3],
        'vecsys_rotten' => static fn (array $x): array => [$x[0] + 0.5 * ($x[0] - $x[1]) ** 3 - 1.0, 0.5 * ($x[1] - $x[0]) ** 3 + $x[1]],
        'vecsys_quad2'  => static fn (array $x): array => [$x[0] ** 2 + $x[1] ** 2 - 4.0, $x[0] - $x[1]],
        'vecsys_nkexample' => static fn (array $x): array => [$x[0] + 0.5 * $x[1] - 1.0, 0.5 * ($x[1] - $x[0]) ** 2],
        'vecsys_exp2'      => static fn (array $x): array => [exp($x[0]) + $x[1] - 2.0, $x[0] + exp($x[1]) - 2.0],
        'vecsys_mix2'      => static fn (array $x): array => [$x[0] + sin($x[1]) - 1.0, $x[1] + cos($x[0]) - 0.5],
        'softbowl'         => static function (array $x): float { $c=[1.5,-0.5]; $s=0.0; for($i=0;$i<2;$i++){$s+=sqrt(1+($x[$i]-$c[$i])**2)-1;} return $s; },
        'bowl3'            => static fn (array $x): float => ($x[0]-1)**2+($x[1]+2)**2+2*($x[2]-0.5)**2,
        'qbowl'            => static fn (array $x): float => $x[0]**2+2*$x[1]**2+$x[0]*$x[1],
        'styblinski'       => static fn (array $x): float => 0.5 * array_sum(array_map(static fn ($v): float => $v ** 4 - 16.0 * $v ** 2 + 5.0 * $v, $x)),
        'vecsys_lin2'   => static fn (array $x): array => [2.0 * $x[0] + $x[1] - 5.0, $x[0] + 3.0 * $x[1] - 10.0],
        'vecsys_trig2'  => static fn (array $x): array => [$x[0] - 0.5 * cos($x[1]) - 0.5, $x[1] - 0.5 * sin($x[0]) - 0.3],
        'vecsys_lin3'   => static fn (array $x): array => [3 * $x[0] + $x[1] - $x[2] - 2.0, $x[0] + 4 * $x[1] + $x[2] - 6.0, -$x[0] + $x[1] + 5 * $x[2] - 5.0],
        'vecsys_mtrig1' => static fn (array $x): array => [cos($x[0]) + 0.1 * $x[1] - 1.0, 0.1 * $x[0] + sin($x[1]) - 0.5],
        'vecsys_mtrig3' => static fn (array $x): array => [cos($x[0]) + 0.15 * $x[1] - 0.9, 0.15 * $x[0] + sin($x[1]) - 0.4],
        'sphere' => static function (array $x): float { $s = 0.0; foreach ($x as $v) { $s += $v * $v; } return $s; },
        'shifted_quadratic' => static function (array $x) use ($spec): float { $s = 0.0; foreach ($x as $i => $v) { $d = $v - $spec['shift'][$i]; $s += $d * $d; } return $s; },
        'rastrigin' => static function (array $x): float { $s = 0.0; foreach ($x as $v) { $s += $v * $v - 10.0 * cos(2.0 * M_PI * $v); } return $s + 10.0 * count($x); },
        'ackley' => static function (array $x): float { $n = count($x); $s1 = 0.0; $s2 = 0.0; foreach ($x as $v) { $s1 += $v * $v; $s2 += cos(2.0 * M_PI * $v); } return -20.0 * exp(-0.2 * sqrt($s1 / $n)) - exp($s2 / $n) + 20.0 + M_E; },
        'booth' => static fn (array $x): float => ($x[0] + 2 * $x[1] - 7) ** 2 + (2 * $x[0] + $x[1] - 5) ** 2,
        'matyas' => static fn (array $x): float => 0.26 * ($x[0] ** 2 + $x[1] ** 2) - 0.48 * $x[0] * $x[1],
        'vquad' => static function (array $x): float { $s = 0.0; foreach ($x as $v) { $s += $v * $v; } return $s; },
        'wquad' => static fn (array $x): float => $x[0] ** 2 + 3.0 * $x[1] ** 2,
        'shift3' => static fn (array $x): float => ($x[0] - 1.0) ** 2 + ($x[1] - 2.5) ** 2 + ($x[2] + 0.3) ** 2,
        'expsum' => static function (array $x): float { $s = 0.0; foreach ($x as $v) { $s += exp(0.5 * $v) + $v ** 2; } return $s; },
        'trig' => static fn (array $x): float => sin($x[0]) * cos($x[1]) + 0.5 * ($x[0] ** 2 + $x[1] ** 2),
        'qcross' => static fn (array $x): float => $x[0] ** 2 + 3.0 * $x[1] ** 2 + 2.0 * $x[0] * $x[1],
        'trigq'  => static fn (array $x): float => sin($x[0]) * cos($x[1]) + 0.5 * ($x[0] ** 2 + $x[1] ** 2),
        'prodq'  => static fn (array $x): float => $x[0] * $x[1] * $x[2] + $x[0] ** 2 * $x[2],
        default => throw new \RuntimeException("unknown objective '{$spec['kind']}'"),
    };
}

/** Rebuild a quad_vec integrand (scalar kinds return float; vector kinds 'xpow'/'osc' return list<float>). */
/** Vector function kinds f: R^m -> R^k for scipy.differentiate.jacobian (mirrors makeObjective's naming). */
function makeVecFunc(string $kind): callable
{
    return match ($kind) {
        'vlin'   => static fn (array $v): array => [2.0 * $v[0] + $v[1], $v[0] - 3.0 * $v[1], $v[0] * $v[1]],
        'vtrig'  => static fn (array $v): array => [sin($v[0]) + $v[1] ** 2, cos($v[1]) * $v[0]],
        'vexp'   => static fn (array $v): array => [exp($v[0]) * $v[1], $v[0] + $v[1] ** 3, $v[0] - $v[1]],
        'vquad3' => static fn (array $v): array => [$v[0] ** 2 + $v[1], $v[1] * $v[2], $v[0] + $v[2] ** 2],
        default  => throw new \RuntimeException("unknown vecfunc '{$kind}'"),
    };
}

function makeDiffScalar(string $kind, array $c): callable
{
    return match ($kind) {
        'poly'    => static function (float $x) use ($c): float { $s = 0.0; $p = 1.0; foreach ($c as $ck) { $s += $ck * $p; $p *= $x; } return $s; },
        'expx'    => static fn (float $x): float => exp($x),
        'sinx'    => static fn (float $x): float => sin($x),
        'cosx'    => static fn (float $x): float => cos($x),
        'sincos'  => static fn (float $x): float => sin($x) * cos(2.0 * $x),
        'expquad' => static fn (float $x): float => exp(0.3 * $x) + $x * $x,
        default   => throw new \RuntimeException("unknown diffscalar '{$kind}'"),
    };
}

function makeIntegrand(array $spec): callable
{
    return match ($spec['kind']) {
        'poly' => static function (float $x) use ($spec): float { $s = 0.0; $p = 1.0; foreach ($spec['c'] as $ck) { $s += $ck * $p; $p *= $x; } return $s; },
        'gauss' => static fn (float $x): float => exp(-$x * $x),
        'sinx' => static fn (float $x): float => sin($x),
        'lorentz' => static fn (float $x): float => 1.0 / (1.0 + $x * $x),
        'xpow' => static function (float $x) use ($spec): array { $o = []; foreach ($spec['alpha'] as $al) { $o[] = $x ** (float) $al; } return $o; },
        'osc' => static function (float $x) use ($spec): array { $o = []; for ($i = 1, $k = (int) $spec['k']; $i <= $k; $i++) { $o[] = sin($i * $x); } return $o; },
        default => throw new \RuntimeException("unknown integrand '{$spec['kind']}'"),
    };
}

/** Structural equality for datetime fixtures: ints/bools/strings exact, floats within a small tolerance. */
function dtEqual(mixed $got, mixed $want): bool
{
    if (is_array($want)) {
        if (! is_array($got) || count($got) !== count($want)) {
            return false;
        }
        $got = array_values($got);
        foreach (array_values($want) as $i => $w) {
            if (! dtEqual($got[$i] ?? null, $w)) {
                return false;
            }
        }
        return true;
    }
    if (is_bool($want)) {
        return (bool) $got === $want;
    }
    if (is_int($want)) {
        return is_numeric($got) && (int) $got === $want;
    }
    if (is_float($want)) {
        return is_numeric($got) && abs((float) $got - $want) <= 1e-9;
    }
    return (string) $got === (string) $want;
}

/** Flatten a (possibly nested) numeric array to a flat list. */
function flattenNums(mixed $a): array
{
    $arr = is_array($a) ? $a : [$a];
    $out = [];
    array_walk_recursive($arr, static function ($v) use (&$out) { $out[] = $v; });
    return $out;
}

/** @param list<float> $got @param list<float> $want */
function vecClose(array $got, array $want, float $rtol): bool
{
    if (count($got) !== count($want)) {
        return false;
    }
    foreach ($want as $i => $w) {
        if (abs($got[$i] - $w) > $rtol * (1 + abs((float) $w))) {
            return false;
        }
    }
    return true;
}

/**
 * Run the scipy.optimize solver fixtures (brentq/newton/minimize/fmin): the pure-PHP solvers verified against
 * scipy on the current backend's process. Returns a status map keyed "optimize.<fn>".
 *
 * @param list<array<string, mixed>> $cases
 * @return array<string, string>
 */
function makeStencil(array $spec): callable
{
    return match ($spec['kind']) {
        'mavg' => static function (array $inbuf, int $outlen): array {   // moving average, window = filter_size
            $size = count($inbuf) - $outlen + 1;
            $out = [];
            for ($i = 0; $i < $outlen; $i++) {
                $s = 0.0;
                for ($j = 0; $j < $size; $j++) { $s += $inbuf[$i + $j]; }
                $out[] = $s / $size;
            }
            return $out;
        },
        'fdiff' => static function (array $inbuf, int $outlen): array {   // forward difference (filter_size=2)
            $out = [];
            for ($i = 0; $i < $outlen; $i++) { $out[] = $inbuf[$i + 1] - $inbuf[$i]; }
            return $out;
        },
        'wstencil' => static function (array $inbuf, int $outlen) use ($spec): array {  // fixed weighted stencil
            $w = $spec['weights'];
            $size = count($w);
            $out = [];
            for ($i = 0; $i < $outlen; $i++) {
                $s = 0.0;
                for ($j = 0; $j < $size; $j++) { $s += $inbuf[$i + $j] * $w[$j]; }
                $out[] = $s;
            }
            return $out;
        },
        default => throw new \RuntimeException("unknown stencil '{$spec['kind']}'"),
    };
}

/** Analytic gradient for the line_search fixtures (named kind, matches makeObjective). */
function makeGradient(array $spec): callable
{
    return match ($spec['kind']) {
        'vquad' => static fn (array $x): array => array_map(static fn ($v) => 2.0 * $v, $x),
        'wquad' => static fn (array $x): array => [2.0 * $x[0], 6.0 * $x[1]],
        'rosen' => static fn (array $x): array => \Tessero\Optimize\Minimize::rosenDer($x),
        'shift3' => static fn (array $x): array => [2.0 * ($x[0] - 1.0), 2.0 * ($x[1] - 2.5), 2.0 * ($x[2] + 0.3)],
        'expsum' => static fn (array $x): array => array_map(static fn ($v) => 0.5 * exp(0.5 * $v) + 2.0 * $v, $x),
        'trig' => static fn (array $x): array => [cos($x[0]) * cos($x[1]) + $x[0], -sin($x[0]) * sin($x[1]) + $x[1]],
        default => throw new \RuntimeException("makeGradient: unknown kind '{$spec['kind']}'"),
    };
}

/** Rebuild a named ODE right-hand side (scipy.integrate.solve_ivp fixtures) as a PHP callable f(t, y). */
function makeOdeSystem(string $kind, array $p): callable
{
    return match ($kind) {
        'exp_decay' => static function (float $t, array $y) use ($p): array {
            $k = (float) $p['k']; $o = [];
            foreach ($y as $yi) { $o[] = -$k * $yi; }
            return $o;
        },
        'harmonic' => static function (float $t, array $y) use ($p): array {
            $w = (float) $p['w'];
            return [$y[1], -$w * $w * $y[0]];
        },
        'lotka' => static function (float $t, array $y) use ($p): array {
            $a = (float) $p['a']; $b = (float) $p['b']; $c = (float) $p['c']; $d = (float) $p['d'];
            return [$a * $y[0] - $b * $y[0] * $y[1], -$c * $y[1] + $d * $y[0] * $y[1]];
        },
        'linear2x2' => static function (float $t, array $y) use ($p): array {
            $M = $p['M'];
            return [$M[0][0] * $y[0] + $M[0][1] * $y[1], $M[1][0] * $y[0] + $M[1][1] * $y[1]];
        },
        'logistic' => static function (float $t, array $y) use ($p): array {
            $r = (float) $p['r']; $K = (float) $p['K']; $o = [];
            foreach ($y as $yi) { $o[] = $r * $yi * (1.0 - $yi / $K); }
            return $o;
        },
        'vanderpol' => static function (float $t, array $y) use ($p): array {
            $mu = (float) $p['mu'];
            return [$y[1], $mu * (1.0 - $y[0] * $y[0]) * $y[1] - $y[0]];
        },
        'robertson' => static function (float $t, array $y): array {
            return [
                -0.04 * $y[0] + 1e4 * $y[1] * $y[2],
                0.04 * $y[0] - 1e4 * $y[1] * $y[2] - 3e7 * $y[1] * $y[1],
                3e7 * $y[1] * $y[1],
            ];
        },
        'linear3x3' => static function (float $t, array $y) use ($p): array {
            $M = $p['M'];
            return [
                $M[0][0] * $y[0] + $M[0][1] * $y[1] + $M[0][2] * $y[2],
                $M[1][0] * $y[0] + $M[1][1] * $y[1] + $M[1][2] * $y[2],
                $M[2][0] * $y[0] + $M[2][1] * $y[1] + $M[2][2] * $y[2],
            ];
        },
        'stiff_linear' => static function (float $t, array $y): array {
            return [-1000.0 * $y[0] + $y[1], -$y[1]];
        },
        'stiff_linear3' => static function (float $t, array $y): array {
            $A = [[-21.0, 19.0, -20.0], [19.0, -21.0, 20.0], [40.0, -40.0, -40.0]];
            return [
                $A[0][0] * $y[0] + $A[0][1] * $y[1] + $A[0][2] * $y[2],
                $A[1][0] * $y[0] + $A[1][1] * $y[1] + $A[1][2] * $y[2],
                $A[2][0] * $y[0] + $A[2][1] * $y[1] + $A[2][2] * $y[2],
            ];
        },
        default => throw new \RuntimeException("solve_ivp: unknown ODE system: " . $kind),
    };
}

/** Rebuild a named BVP system (scipy.integrate.solve_bvp fixtures) as [fun, bc, hasP]. */
function makeBvpSystem(string $kind): array
{
    switch ($kind) {
        case 'bratu':
            $fun = static function (array $x, array $y, array $p): array {
                $o0 = []; $o1 = [];
                foreach ($x as $j => $_) { $o0[$j] = $y[1][$j]; $o1[$j] = -exp($y[0][$j]); }
                return [$o0, $o1];
            };
            $bc = static fn (array $ya, array $yb, array $p): array => [$ya[0], $yb[0]];
            return [$fun, $bc, false];
        case 'linear_sin':
            $fun = static function (array $x, array $y, array $p): array {
                $o0 = []; $o1 = [];
                foreach ($x as $j => $_) { $o0[$j] = $y[1][$j]; $o1[$j] = -$y[0][$j]; }
                return [$o0, $o1];
            };
            $bc = static fn (array $ya, array $yb, array $p): array => [$ya[0], $yb[0] - 1.0];
            return [$fun, $bc, false];
        case 'nonlin_reaction':
            $fun = static function (array $x, array $y, array $p): array {
                $o0 = []; $o1 = [];
                foreach ($x as $j => $_) { $o0[$j] = $y[1][$j]; $o1[$j] = -3.0 * $y[0][$j] * $y[1][$j]; }
                return [$o0, $o1];
            };
            $bc = static fn (array $ya, array $yb, array $p): array => [$ya[0], $yb[0] - 1.0];
            return [$fun, $bc, false];
        case 'exp_shrink':
            $fun = static function (array $x, array $y, array $p): array {
                $o0 = []; $o1 = [];
                foreach ($x as $j => $_) { $o0[$j] = $y[1][$j]; $o1[$j] = $y[0][$j]; }
                return [$o0, $o1];
            };
            $bc = static fn (array $ya, array $yb, array $p): array => [$ya[0] - 1.0, $yb[0] - M_E];
            return [$fun, $bc, false];
        case 'sturm_liouville':
            $fun = static function (array $x, array $y, array $p): array {
                $k = $p[0]; $o0 = []; $o1 = [];
                foreach ($x as $j => $_) { $o0[$j] = $y[1][$j]; $o1[$j] = -$k * $k * $y[0][$j]; }
                return [$o0, $o1];
            };
            $bc = static fn (array $ya, array $yb, array $p): array => [$ya[0], $yb[0], $ya[1] - $p[0]];
            return [$fun, $bc, true];
        default:
            throw new \RuntimeException("solve_bvp: unknown BVP system: " . $kind);
    }
}

/** Rebuild a scipy.integrate.cubature integrand f: R^ndim -> R from its named kind (mirrors fixtures_cubature.py). */
function makeCubIntegrand(string $kind): callable
{
    return match ($kind) {
        'sumsq'  => static fn (array $x): float => array_sum(array_map(static fn ($v) => $v * $v, $x)),
        'prod'   => static fn (array $x): float => (float) array_product($x),
        'coscos' => static fn (array $x): float => array_sum(array_map('cos', $x)),
        'expsum' => static fn (array $x): float => exp(array_sum($x)),
        'gauss'  => static fn (array $x): float => exp(-array_sum(array_map(static fn ($v) => $v * $v, $x))),
        'poly'   => static fn (array $x): float => array_sum(array_map(static fn ($v) => $v ** 3, $x)) + (float) array_product($x),
        'invr'   => static fn (array $x): float => 1.0 / (1.0 + array_sum(array_map(static fn ($v) => $v * $v, $x))),
        default  => throw new \RuntimeException("unknown cubature integrand '{$kind}'"),
    };
}

/** Rebuild a named permutation_test statistic (scipy.stats.permutation_test fixtures) as a callable. */
function makePermStatistic(string $kind): callable
{
    return match ($kind) {
        'mean_diff'   => static fn (array $a, array $b): float => array_sum($a) / count($a) - array_sum($b) / count($b),
        'sum_first'   => static fn (array ...$ss): float => array_sum($ss[0]),
        'mean_paired' => static fn (array $d): float => array_sum($d) / count($d),
        'pearson'     => static function (array $a, array $b): float {
            $n = count($a);
            $ma = array_sum($a) / $n;
            $mb = array_sum($b) / $n;
            $num = 0.0; $ssx = 0.0; $ssy = 0.0;
            for ($i = 0; $i < $n; $i++) {
                $da = $a[$i] - $ma; $db = $b[$i] - $mb;
                $num += $da * $db; $ssx += $da * $da; $ssy += $db * $db;
            }
            return $num / sqrt($ssx * $ssy);
        },
        default       => throw new \RuntimeException("unknown perm statistic '{$kind}'"),
    };
}


/**
 * Order-free match of two point collections to tolerance (Qhull-order-independent SET compare).
 * @param list<list<float>> $got
 * @param list<list<float>> $want
 */
function spatialSetMatch(array $got, array $want, float $tol): bool
{
    if (count($got) !== count($want)) {
        return false;
    }
    $used = array_fill(0, count($want), false);
    foreach ($got as $a) {
        $best = -1;
        $bestd = $tol;
        foreach ($want as $j => $b) {
            if ($used[$j]) {
                continue;
            }
            $sum = 0.0;
            foreach ($a as $k => $ak) {
                $dk = $ak - $b[$k];
                $sum += $dk * $dk;
            }
            $dd = sqrt($sum);
            if ($dd <= $bestd) {
                $bestd = $dd;
                $best = $j;
            }
        }
        if ($best < 0) {
            return false;
        }
        $used[$best] = true;
    }

    return true;
}

/** Rebuild a named complex ODE RHS (scipy.integrate.complex_ode fixtures) as a PHP callable.
 *  y and the return value are lists of [re, im] pairs (complex components). */
function makeOdeComplexRhs(string $kind, array $p): callable
{
    $cmul = static fn (array $a, array $b): array => [$a[0] * $b[0] - $a[1] * $b[1], $a[0] * $b[1] + $a[1] * $b[0]];
    $cadd = static fn (array $a, array $b): array => [$a[0] + $b[0], $a[1] + $b[1]];
    return match ($kind) {
        'rot' => static function (float $t, array $y) use ($p, $cmul): array {  // y' = i*w*y
            return [$cmul([0.0, (float) $p['w']], $y[0])];
        },
        'cdecay' => static function (float $t, array $y) use ($p, $cmul): array {  // y' = (a + i b) y
            return [$cmul([(float) $p['a'], (float) $p['b']], $y[0])];
        },
        'cpair' => static function (float $t, array $y) use ($cmul, $cadd): array {  // 2-component
            return [
                $cadd($cmul([0.0, 1.0], $y[0]), $cmul([-0.1, 0.0], $y[1])),
                $cmul([0.0, 2.0], $y[1]),
            ];
        },
        default => throw new \RuntimeException('complex_ode: unknown system: ' . $kind),
    };
}

/**
 * scipy.optimize.{BroydenFirst, InverseJacobian, KrylovJacobian} Jacobian-helper classes.
 *
 * Each case scripts a deterministic op sequence on one helper and compares a probe
 * (solve(v) = J^-1.v for BroydenFirst/InverseJacobian, matvec(v) = finite-diff J.v for
 * KrylovJacobian) against scipy. The residual func is a named makeObjective() 'vecsys_*'
 * kind (no callable serialised). Pure PHP (no kernel) -> identical on both backends.
 * Returns status keyed "optimize.<ClassName>".
 *
 * @param list<array<string,mixed>> $cases
 * @return array<string,string>
 */
function runNkClassCases(array $cases, string $module, int &$checked, int &$failures): array
{
    $status = [];
    foreach ($cases as $c) {
        $cls = (string) $c['cls'];
        $key = "{$module}.{$cls}";
        $rtol = (float) ($c['rtol'] ?? 1e-10);
        $func = makeObjective($c['obj']);
        $x0 = array_map('floatval', $c['x0']);
        $f0 = $func($x0);
        $probe = array_map('floatval', $c['probe']);
        $checked++;
        $ok = false;
        $msg = '';
        try {
            switch ($cls) {
                case 'BroydenFirst':
                    $jac = new \Tessero\Optimize\BroydenFirst();
                    $jac->setup($x0, $f0, $func);
                    foreach ($c['updates'] as $p) {
                        $p = array_map('floatval', $p);
                        $jac->update($p, $func($p));
                    }
                    $got = $jac->solve($probe);
                    break;
                case 'InverseJacobian':
                    $jac = new \Tessero\Optimize\InverseJacobian(new \Tessero\Optimize\BroydenFirst());
                    $jac->setup($x0, $f0, $func);
                    foreach ($c['updates'] as $p) {
                        $p = array_map('floatval', $p);
                        $jac->update($p, $func($p));
                    }
                    $got = $jac->matvec($probe);
                    break;
                case 'KrylovJacobian':
                    $jac = new \Tessero\Optimize\KrylovJacobian();
                    $jac->setup($x0, $f0, $func);
                    $got = $jac->matvec($probe);
                    break;
                default:
                    throw new \RuntimeException("runNkClassCases: unknown class '{$cls}'");
            }
            $ok = vecClose($got, $c['expect'], $rtol);
            if (! $ok) { $msg = 'value mismatch'; }
        } catch (\Throwable $e) {
            $msg = $e->getMessage();
        }
        $status[$key] = ($status[$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
        if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
    }
    return $status;
}

function runSolverCases(array $cases, string $module, int &$checked, int &$failures): array
{
    $status = [];
    foreach ($cases as $c) {
        $fn = $c['fn'];
        $key = "{$module}.{$fn}";
        $rtol = (float) ($c['rtol'] ?? 1e-9);
        $obj = isset($c['obj']) ? makeObjective($c['obj']) : null;
        $checked++;
        $ok = false;
        $msg = '';
        try {
            if ($fn === 'brentq') {
                $got = \Tessero\Optimize\Root::brentq($obj, (float) $c['a'], (float) $c['b']);
                $ok = abs($got - $c['expect']) <= $rtol * (1 + abs((float) $c['expect']));
            } elseif ($fn === 'bisect') {
                $got = \Tessero\Optimize\Root::bisect($obj, (float) $c['a'], (float) $c['b']);
                $ok = abs($got - $c['expect']) <= $rtol * (1 + abs((float) $c['expect']));
            } elseif ($fn === 'brenth') {
                $got = \Tessero\Optimize\Root::brenth($obj, (float) $c['a'], (float) $c['b']);
                $ok = abs($got - $c['expect']) <= $rtol * (1 + abs((float) $c['expect']));
            } elseif ($fn === 'ridder') {
                $got = \Tessero\Optimize\Root::ridder($obj, (float) $c['a'], (float) $c['b']);
                $ok = abs($got - $c['expect']) <= $rtol * (1 + abs((float) $c['expect']));
            } elseif ($fn === 'toms748') {
                $got = \Tessero\Optimize\Root::toms748($obj, (float) $c['a'], (float) $c['b']);
                $ok = abs($got - $c['expect']) <= $rtol * (1 + abs((float) $c['expect']));
            } elseif ($fn === 'root_scalar') {
                $bracket = isset($c['bracket']) ? array_map('floatval', $c['bracket']) : null;
                $r = \Tessero\Optimize\Root::rootScalar($obj, $c['method'] ?? null, $bracket, isset($c['x0']) ? (float) $c['x0'] : null);
                $got = $r['root'];
                $ok = abs($got - $c['expect']) <= $rtol * (1 + abs((float) $c['expect']));
            } elseif ($fn === 'fminbound') {
                $got = \Tessero\Optimize\Minimize::fminbound($obj, (float) $c['a'], (float) $c['b']);
                $ok = abs($got - $c['expect']) <= $rtol * (1 + abs((float) $c['expect']));
            } elseif ($fn === 'minimize_scalar') {
                $bracket = isset($c['bracket']) ? array_map('floatval', $c['bracket']) : null;
                $bounds = isset($c['bounds']) ? array_map('floatval', $c['bounds']) : null;
                $got = \Tessero\Optimize\Minimize::minimizeScalar($obj, $bracket, $bounds, (string) ($c['method'] ?? ''))->x[0];
                $ok = abs($got - $c['expect']) <= $rtol * (1 + abs((float) $c['expect']));
            } elseif ($fn === 'newton') {
                $got = \Tessero\Optimize\Root::newton($obj, (float) $c['x0']);
                $ok = abs($got - $c['expect']) <= $rtol * (1 + abs((float) $c['expect']));
            } elseif ($fn === 'minimize') {
                $mup = strtoupper((string) $c['method']);
                $jac = null;
                $opts = [];
                $isRosen = ($c['obj']['kind'] ?? '') === 'rosen';
                if ($isRosen && in_array($mup, ['CG', 'NEWTON-CG', 'NEWTONCG', 'DOGLEG', 'TRUST-NCG', 'TRUSTNCG', 'TRUST-EXACT', 'TRUSTEXACT', 'TRUST-KRYLOV', 'TRUSTKRYLOV'], true)) {
                    $jac = static fn (array $v): array => \Tessero\Optimize\Minimize::rosenDer($v);
                    // Hessian-vector product for Newton-CG; the 5-D trust-ncg fixture exercises the hessp path.
                    if (in_array($mup, ['NEWTON-CG', 'NEWTONCG'], true)
                        || ($mup === 'TRUST-NCG' || $mup === 'TRUSTNCG') && count($c['x0']) === 5) {
                        $opts['hessp'] = static fn (array $v, array $p): array => \Tessero\Optimize\Minimize::rosenHessProd($v, $p);
                    }
                    // Full Hessian matrix for dogleg / trust-exact (and the 2-D trust-ncg fixture).
                    if (in_array($mup, ['DOGLEG', 'TRUST-EXACT', 'TRUSTEXACT'], true)
                        || ($mup === 'TRUST-NCG' || $mup === 'TRUSTNCG') && count($c['x0']) !== 5) {
                        $opts['hess'] = static fn (array $v): array => \Tessero\Optimize\Minimize::rosenHess($v);
                    }
                    if ($mup === 'TRUST-KRYLOV' || $mup === 'TRUSTKRYLOV') {
                        if (! empty($c['hessp'])) { $opts['hessp'] = static fn (array $v, array $p): array => \Tessero\Optimize\Minimize::rosenHessProd($v, $p); }
                        else { $opts['hess'] = static fn (array $v): array => \Tessero\Optimize\Minimize::rosenHess($v); }
                    }
                }
                if (in_array($mup, ['TRUST-KRYLOV', 'TRUSTKRYLOV'], true) && ! $isRosen) {
                    $kk = $c['obj']['kind'];
                    $jac = match ($kk) {
                        'softbowl' => static fn (array $x): array => [($x[0] - 1.5) / sqrt(1 + ($x[0] - 1.5) ** 2), ($x[1] + 0.5) / sqrt(1 + ($x[1] + 0.5) ** 2)],
                        'bowl3'    => static fn (array $x): array => [2 * ($x[0] - 1), 2 * ($x[1] + 2), 4 * ($x[2] - 0.5)],
                        'qbowl'    => static fn (array $x): array => [2 * $x[0] + $x[1], 4 * $x[1] + $x[0]],
                    };
                    $opts['hess'] = match ($kk) {
                        'softbowl' => static fn (array $x): array => [[1.0 / (1 + ($x[0] - 1.5) ** 2) ** 1.5, 0.0], [0.0, 1.0 / (1 + ($x[1] + 0.5) ** 2) ** 1.5]],
                        'bowl3'    => static fn (array $x): array => [[2.0, 0, 0], [0, 2.0, 0], [0, 0, 4.0]],
                        'qbowl'    => static fn (array $x): array => [[2.0, 1.0], [1.0, 4.0]],
                    };
                }
                $got = \Tessero\Optimize\Minimize::minimize($obj, array_map('floatval', $c['x0']), $jac, (string) $c['method'], null, $opts)->x;
                $ok = vecClose($got, $c['expect'], $rtol);
                        } elseif ($fn === 'fmin') {
                $got = \Tessero\Optimize\Minimize::fmin($obj, array_map('floatval', $c['x0']));
                $ok = vecClose($got, $c['expect'], $rtol);
            } elseif ($fn === 'quad') {
                $r = \Tessero\Integrate\Quad::quad($obj, (float) $c['a'], (float) $c['b']);
                $ok = abs($r[0] - $c['expect']) <= $rtol * (1 + abs((float) $c['expect']));
            } elseif ($fn === 'fixed_quad') {
                $r = \Tessero\Integrate\Quad::fixedQuad($obj, (float) $c['a'], (float) $c['b'], (int) $c['n']);
                $ok = abs($r[0] - $c['expect']) <= $rtol * (1 + abs((float) $c['expect']));
            } elseif ($fn === 'tanhsinh') {
                $r = \Tessero\Integrate\Tanhsinh::tanhsinh($obj, (float) $c['a'], (float) $c['b']);
                $ok = abs($r['integral'] - $c['expect']) <= $rtol * (1 + abs((float) $c['expect']));
            } elseif ($fn === 'leastsq') {
                $r = \Tessero\Optimize\LeastSquares::solve($obj, array_map('floatval', $c['x0']));
                $ok = vecClose($r['x'], $c['expect'], $rtol);
            } elseif ($fn === 'least_squares') {
                $r = \Tessero\Optimize\LeastSquares::leastSquares($obj, array_map('floatval', $c['x0']));
                $ok = vecClose($r->x, $c['expect'], $rtol);
            } elseif ($fn === 'curve_fit') {
                $model = match ($c['obj']['kind']) {
                    'expresid' => static fn (float $x, float $a, float $b, float $cc): float => $a * exp($b * $x) + $cc,
                    'linresid' => static fn (float $x, float $a, float $b): float => $a * $x + $b,
                    default => throw new \RuntimeException("curve_fit: unknown model '{$c['obj']['kind']}'"),
                };
                $xd = array_map('floatval', $c['obj']['x']);
                $yd = array_map('floatval', $c['obj']['y']);
                $sigma = isset($c['sigma']) ? array_map('floatval', $c['sigma']) : null;
                [$popt, $pcov] = \Tessero\Optimize\LeastSquares::curveFit($model, $xd, $yd, array_map('floatval', $c['p0']), $sigma, (bool) ($c['absolute_sigma'] ?? false));
                $okPopt = vecClose($popt, $c['popt'], $rtol);
                $rtolPcov = (float) ($c['rtol_pcov'] ?? 1e-4);
                $okPcov = vecClose(array_merge(...$pcov), array_merge(...$c['pcov']), $rtolPcov);
                $ok = $okPopt && $okPcov;
            } elseif ($fn === 'nnls') {
                $r = \Tessero\Optimize\LeastSquares::nnls($c['A'], $c['b']);
                $ok = vecClose($r[0], $c['expect'], $rtol);
            } elseif ($fn === 'isotonic_regression') {
                $r = \Tessero\Optimize\LeastSquares::isotonicRegression($c['y'], $c['weights'] ?? null, $c['increasing'] ?? true);
                $ok = vecClose($r, $c['expect'], $rtol);
            } elseif ($fn === 'lsq_linear') {
                $r = \Tessero\Optimize\LeastSquares::lsqLinear($c['A'], $c['b']);
                $ok = vecClose($r->x, $c['expect'], $rtol);
            } elseif ($fn === 'root') {
                $got = \Tessero\Optimize\Root::root($obj, array_map('floatval', $c['x0']))->x;
                $ok = vecClose($got, $c['expect'], $rtol);
            } elseif ($fn === 'fsolve') {
                $got = \Tessero\Optimize\Root::fsolve($obj, array_map('floatval', $c['x0']));
                $ok = vecClose($got, $c['expect'], $rtol);
            } elseif ($fn === 'broyden1' || $fn === 'broyden2' || $fn === 'anderson' || $fn === 'diagbroyden'
                      || $fn === 'linearmixing' || $fn === 'excitingmixing') {
                $got = \Tessero\Optimize\NonlinSolve::{$fn}($obj, array_map('floatval', $c['x0']));
                $ok = vecClose($got, $c['expect'], $rtol);
            } elseif ($fn === 'newton_krylov') {
                $got = \Tessero\Optimize\NonlinSolve::newtonKrylov($obj, array_map('floatval', $c['x0']));
                $ok = vecClose($got, $c['expect'], $rtol);
            } elseif ($fn === 'direct') {
                $bounds = array_map(static fn ($b): array => [(float) $b[0], (float) $b[1]], $c['bounds']);
                $r = \Tessero\Optimize\Direct::minimize($obj, $bounds);
                $okX = vecClose($r->x, $c['expect'], $rtol);
                if (($c['tier'] ?? '') === 'global') {
                    $okF = abs($r->fun) <= (float) ($c['fun_atol'] ?? 1e-2);
                } else {
                    $okF = abs($r->fun - (float) $c['expect_fun']) <= $rtol * (1 + abs((float) $c['expect_fun']));
                }
                $ok = $okX && $okF;
            } elseif ($fn === 'shgo') {
                $bounds = array_map(static fn ($b): array => [(float) $b[0], (float) $b[1]], $c['bounds']);
                $r = \Tessero\Optimize\Shgo::minimize($obj, $bounds);
                $okX = vecClose($r->x, $c['expect'], $rtol);
                $okF = abs($r->fun - (float) $c['expect_fun']) <= max($rtol, 1e-9) * (1 + abs((float) $c['expect_fun']));
                $ok = $okX && $okF;
            } elseif ($fn === 'fixed_point') {
                $got = \Tessero\Optimize\Root::fixedPoint($obj, (float) $c['x0']);
                $ok = abs($got - $c['expect']) <= $rtol * (1 + abs((float) $c['expect']));
            } elseif ($fn === 'bracket') {
                $r = \Tessero\Optimize\Minimize::bracket($obj, (float) $c['a'], (float) $c['b']);
                $ok = vecClose([$r[0], $r[1], $r[2]], $c['expect'], $rtol);
            } elseif ($fn === 'linear_sum_assignment') {
                [$ri, $ci] = \Tessero\Optimize\Assignment::linearSumAssignment($c['cost'], (bool) ($c['maximize'] ?? false));
                $ok = array_map('intval', $ri) === array_map('intval', $c['expect_row']) && array_map('intval', $ci) === array_map('intval', $c['expect_col']);
            } elseif ($fn === 'quadratic_assignment') {
                $r = \Tessero\Optimize\QuadraticAssignment::faq($c['A'], $c['B'], (bool) ($c['maximize'] ?? false), (int) ($c['maxiter'] ?? 30), (float) ($c['tol'] ?? 0.03));
                $colOk = array_map('intval', $r['col_ind']) === array_map('intval', $c['expect_col']);
                $funOk = abs($r['fun'] - (float) $c['fun']) <= $rtol * (1 + abs((float) $c['fun']));
                $ok = $colOk && $funOk;
            } elseif ($fn === 'differential_evolution') {
                $bounds = array_map(static fn ($b): array => [(float) $b[0], (float) $b[1]], $c['bounds']);
                $got = \Tessero\Optimize\DifferentialEvolution::solve($obj, $bounds, $c['seed'] ?? null)->x;
                $ok = vecClose($got, $c['expect'], $rtol);
            } elseif ($fn === 'rosen') {
                $got = \Tessero\Optimize\Minimize::rosen(array_map('floatval', $c['x']));
                $ok = abs($got - $c['expect']) <= $rtol * (1 + abs((float) $c['expect']));
            } elseif ($fn === 'rosen_der') {
                $ok = vecClose(\Tessero\Optimize\Minimize::rosenDer(array_map('floatval', $c['x'])), $c['expect'], $rtol);
            } elseif ($fn === 'rosen_hess_prod') {
                $ok = vecClose(\Tessero\Optimize\Minimize::rosenHessProd(array_map('floatval', $c['x']), array_map('floatval', $c['p'])), $c['expect'], $rtol);
            } elseif ($fn === 'rosen_hess') {
                $H = \Tessero\Optimize\Minimize::rosenHess(array_map('floatval', $c['x']));
                $ok = vecClose(array_merge(...$H), array_merge(...$c['expect']), $rtol);   // flatten row-major
            } elseif ($fn === 'brent') {
                $got = \Tessero\Optimize\Minimize::brent($obj, isset($c['bracket']) ? array_map('floatval', $c['bracket']) : null);
                $ok = abs($got - $c['expect']) <= $rtol * (1 + abs((float) $c['expect']));
            } elseif ($fn === 'golden') {
                $got = \Tessero\Optimize\Minimize::golden($obj, isset($c['bracket']) ? array_map('floatval', $c['bracket']) : null);
                $ok = abs($got - $c['expect']) <= $rtol * (1 + abs((float) $c['expect']));
            } elseif ($fn === 'fmin_bfgs') {
                $ok = vecClose(\Tessero\Optimize\Minimize::fminBfgs($obj, array_map('floatval', $c['x0'])), $c['expect'], $rtol);
            } elseif ($fn === 'fmin_cg') {
                $grad = static fn (array $v): array => \Tessero\Optimize\Minimize::rosenDer($v);
                $ok = vecClose(\Tessero\Optimize\Minimize::fminCg($obj, array_map('floatval', $c['x0']), $grad), $c['expect'], $rtol);
            } elseif ($fn === 'fmin_powell') {
                $ok = vecClose(\Tessero\Optimize\Minimize::fminPowell($obj, array_map('floatval', $c['x0'])), $c['expect'], $rtol);
            } elseif ($fn === 'fmin_ncg') {
                $grad = static fn (array $v): array => \Tessero\Optimize\Minimize::rosenDer($v);
                $hessp = static fn (array $v, array $p): array => \Tessero\Optimize\Minimize::rosenHessProd($v, $p);
                $ok = vecClose(\Tessero\Optimize\Minimize::fminNcg($obj, array_map('floatval', $c['x0']), $grad, $hessp), $c['expect'], $rtol);
            } elseif ($fn === 'trust_constr') {
                [$tcf, $tcjac, $tcx0, $tcbounds, $tccons] = (static function (string $prob): array {
                    $rosen = static function (array $x): float {
                        $s = 0.0; for ($i = 0, $n = count($x); $i < $n - 1; $i++) { $s += 100.0 * ($x[$i + 1] - $x[$i] ** 2) ** 2 + (1.0 - $x[$i]) ** 2; } return $s;
                    };
                    switch ($prob) {
                        case 'p1_rosen3':
                            return [$rosen, null, [0.5, 0.5, 0.5], null, []];
                        case 'p2_boundquad':
                            return [static fn (array $x): float => ($x[0] - 2.0) ** 2 + ($x[1] + 3.0) ** 2, null, [0.0, 0.0], new \Tessero\Optimize\Bounds([-1.0, -1.0], [1.0, 1.0]), []];
                        case 'p3_lineq':
                            return [static fn (array $x): float => $x[0] ** 2 + $x[1] ** 2, null, [2.0, -1.0], null, [new \Tessero\Optimize\LinearConstraint([[1.0, 1.0]], 1.0, 1.0)]];
                        case 'p4_linineq_bnd':
                            return [static fn (array $x): float => ($x[0] - 3.0) ** 2 + ($x[1] - 2.0) ** 2, null, [0.5, 0.5], new \Tessero\Optimize\Bounds([0.0, 0.0], [INF, INF]), [new \Tessero\Optimize\LinearConstraint([[1.0, 1.0]], -INF, 4.0)]];
                        case 'p6_nleq':
                            return [static fn (array $x): float => ($x[0] - 1.0) ** 2 + ($x[1] - 2.0) ** 2, null, [1.5, 1.5], null, [new \Tessero\Optimize\NonlinearConstraint(static fn (array $x): array => [$x[0] ** 2 - $x[1]], 0.0, 0.0, static fn (array $x): array => [[2 * $x[0], -1.0]], static fn (array $x, array $v): array => [[2.0 * $v[0], 0.0], [0.0, 0.0]])]];
                        case 'p7_mixed':
                            return [static fn (array $x): float => ($x[0] - 1.5) ** 2 + ($x[1] - 1.5) ** 2, null, [0.2, 0.1], new \Tessero\Optimize\Bounds([0.0, 0.0], [5.0, 5.0]), [new \Tessero\Optimize\LinearConstraint([[1.0, -1.0]], 0.0, 0.0), new \Tessero\Optimize\NonlinearConstraint(static fn (array $x): array => [$x[0] ** 2 + $x[1] ** 2], -INF, 1.0, static fn (array $x): array => [[2 * $x[0], 2 * $x[1]]], static fn (array $x, array $v): array => [[2.0 * $v[0], 0.0], [0.0, 2.0 * $v[0]]])]];
                        case 'p8_rosen5_jac':
                            $g = static function (array $x): array {
                                $gg = array_fill(0, 5, 0.0);
                                for ($i = 0; $i < 4; $i++) { $gg[$i] += -400 * $x[$i] * ($x[$i + 1] - $x[$i] ** 2) - 2 * (1 - $x[$i]); $gg[$i + 1] += 200 * ($x[$i + 1] - $x[$i] ** 2); }
                                return $gg;
                            };
                            return [static function (array $x): float { $s = 0.0; for ($i = 0; $i < 4; $i++) { $s += 100.0 * ($x[$i + 1] - $x[$i] ** 2) ** 2 + (1 - $x[$i]) ** 2; } return $s; }, $g, [1.3, 0.7, 0.8, 1.9, 1.2], null, []];
                        default:
                            throw new \RuntimeException("trust_constr: unknown prob '{$prob}'");
                    }
                })($c['prob']);
                $tcopts = $tccons !== [] ? ['constraints' => $tccons] : [];
                $got = \Tessero\Optimize\TrustConstr::run($tcf, array_map('floatval', $tcx0), $tcjac, $tcbounds, $tcopts)->x;
                $ok = vecClose($got, $c['expect'], $rtol);
            } elseif ($fn === 'minimize_con') {
                $p = makeConProblem($c['prob']);
                $opts = $p['cons'] !== [] ? ['constraints' => $p['cons']] : [];
                $got = \Tessero\Optimize\Minimize::minimize($p['f'], array_map('floatval', $p['x0']), $p['jac'], (string) $c['method'], $p['bounds'], $opts)->x;
                $ok = vecClose($got, $c['expect'], $rtol);
            } elseif ($fn === 'fmin_tnc') {
                $p = makeConProblem($c['prob']);
                $ok = vecClose(\Tessero\Optimize\Minimize::fminTnc($p['f'], array_map('floatval', $p['x0']), $p['jac'], $p['bounds']), $c['expect'], $rtol);
            } elseif ($fn === 'fmin_l_bfgs_b') {
                $p = makeConProblem($c['prob']);
                $jac = ($c['approx_grad'] ?? false) ? null : $p['jac'];
                $ok = vecClose(\Tessero\Optimize\Minimize::fminLbfgsb($p['f'], array_map('floatval', $p['x0']), $jac, $p['bounds']), $c['expect'], $rtol);
            } elseif ($fn === 'fmin_slsqp') {
                $p = makeConProblem($c['prob']);
                $eq = []; $ineq = [];
                foreach ($p['cons'] as $cc) { if ($cc['type'] === 'eq') { $eq[] = $cc['fun']; } else { $ineq[] = $cc['fun']; } }
                $ok = vecClose(\Tessero\Optimize\Minimize::fminSlsqp($p['f'], array_map('floatval', $p['x0']), $eq, $ineq, $p['bounds'], $p['jac']), $c['expect'], $rtol);
            } elseif ($fn === 'fmin_cobyla') {
                $p = makeConProblem($c['prob']);
                $cons = array_map(static fn ($cc) => $cc['fun'], $p['cons']);
                $ok = vecClose(\Tessero\Optimize\Minimize::fminCobyla($p['f'], array_map('floatval', $p['x0']), $cons, 1.0, 1e-6), $c['expect'], $rtol);
            } elseif ($fn === 'check_grad') {
                $grad = static fn (array $v): array => \Tessero\Optimize\Minimize::rosenDer($v);
                $got = \Tessero\Optimize\Minimize::checkGrad($obj, $grad, array_map('floatval', $c['x0']));
                $ok = abs($got - $c['expect']) <= $rtol * (1 + abs((float) $c['expect']));
            } elseif ($fn === 'brute') {
                $ranges = array_map(static fn ($r): array => [(float) $r[0], (float) $r[1]], $c['ranges']);
                $got = \Tessero\Optimize\Minimize::brute($obj, $ranges, (int) ($c['Ns'] ?? 20));
                $g = is_array($got) ? $got : [$got];
                $exp = is_array($c['expect']) ? $c['expect'] : [$c['expect']];
                $ok = vecClose($g, $exp, $rtol);
            } elseif ($fn === 'dual_annealing') {
                $bounds = array_map(static fn ($b): array => [(float) $b[0], (float) $b[1]], $c['bounds']);
                $r = \Tessero\Optimize\DualAnnealing::minimize($obj, $bounds, (int) $c['maxiter'], rng: $c['seed'] ?? null, noLocalSearch: true);
                $okX = vecClose($r['x'], $c['expect'], $rtol);
                $okF = abs($r['fun'] - (float) $c['expect_fun']) <= $rtol * (1 + abs((float) $c['expect_fun']));
                $okN = (int) $r['nfev'] === (int) $c['expect_nfev'] && (int) $r['nit'] === (int) $c['expect_nit'];
                $ok = $okX && $okF && $okN;
            } elseif ($fn === 'basinhopping') {
                $got = \Tessero\Optimize\BasinHopping::solve($obj, array_map('floatval', $c['x0']), $c['seed'] ?? null, (int) $c['niter'])->x;
                $ok = vecClose($got, $c['expect'], $rtol);
            } elseif ($fn === 'approx_fprime') {
                $g = \Tessero\Optimize\LineSearch::approxFprime($obj, array_map('floatval', $c['x']));
                $ok = vecClose($g, $c['expect'], $rtol);
            } elseif ($fn === 'line_search') {
                $grad = makeGradient($c['obj']);
                [$alpha, $fcnt, $gcnt, $newf, $oldf, $slope] = \Tessero\Optimize\LineSearch::lineSearch($obj, $grad, array_map('floatval', $c['xk']), array_map('floatval', $c['pk']));
                if ($c['alpha'] === null) {
                    $ok = $alpha === null;
                } else {
                    $ok = $alpha !== null && abs($alpha - (float) $c['alpha']) <= $rtol * (1 + abs((float) $c['alpha'])) && (int) $fcnt === (int) $c['fc'] && (int) $gcnt === (int) $c['gc'] && abs($newf - (float) $c['new_fval']) <= $rtol * (1 + abs((float) $c['new_fval']));
                    if ($ok && $c['new_slope'] !== null) { $ok = vecClose($slope, $c['new_slope'], $rtol); }
                }
            } elseif ($fn === 'Bounds') {
                $b = new \Tessero\Optimize\Bounds($c['ctor']['lb'], $c['ctor']['ub']);
                if (isset($c['n'])) { [$lb, $ub] = $b->resolved((int) $c['n']); }
                else { $lb = is_array($b->lb) ? $b->lb : [$b->lb]; $ub = is_array($b->ub) ? $b->ub : [$b->ub]; }
                $ok = vecClose($lb, $c['lb'], $rtol) && vecClose($ub, $c['ub'], $rtol);
            } elseif ($fn === 'LinearConstraint') {
                $lc = new \Tessero\Optimize\LinearConstraint($c['ctor']['A'], $c['ctor']['lb'], $c['ctor']['ub']);
                $lb = is_array($lc->lb) ? $lc->lb : [$lc->lb]; $ub = is_array($lc->ub) ? $lc->ub : [$lc->ub];
                $ok = vecClose(array_merge(...$lc->A), array_merge(...$c['A']), $rtol) && vecClose($lb, $c['lb'], $rtol) && vecClose($ub, $c['ub'], $rtol);
            } elseif ($fn === 'NonlinearConstraint') {
                $nlc = new \Tessero\Optimize\NonlinearConstraint(static fn (array $x): array => $x, $c['ctor']['lb'], $c['ctor']['ub']);
                $ok = abs((float) $nlc->lb - (float) $c['lb']) <= $rtol && abs((float) $nlc->ub - (float) $c['ub']) <= $rtol;
            } elseif ($fn === 'RootResults') {
                $r = \Tessero\Optimize\Root::rootScalar(static fn (float $x): float => $x * $x - 2.0, $c['ctor']['method'], array_map('floatval', $c['ctor']['bracket']), null);
                $rr = new \Tessero\Optimize\RootResults((float) $r['root'], 0, 0, (bool) $r['converged'], (string) $r['flag'], $c['ctor']['method']);
                $ok = abs($rr->root - (float) $c['root']) <= $rtol * (1 + abs((float) $c['root'])) && $rr->converged === (bool) $c['converged'];
            } elseif ($fn === 'BFGS' || $fn === 'SR1') {
                $h = $fn === 'BFGS' ? new \Tessero\Optimize\Bfgs() : new \Tessero\Optimize\Sr1();
                $h->initialize((int) $c['n'], 'hess');
                $ok = true;
                foreach ($c['steps'] as $i => $pair) {
                    $h->update($pair[0], $pair[1]);
                    $M = $h->getMatrix();
                    foreach ($c['seq'][$i] as $r => $row) {
                        if (! vecClose($M[$r], $row, $rtol)) { $ok = false; break 2; }
                    }
                }
                if ($ok) { $ok = vecClose($h->dot($c['p']), $c['dot'], $rtol); }
            }
        } catch (\Throwable $e) {
            $msg = $e->getMessage();
        }
        $status[$key] = ($status[$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
        if (! $ok) {
            $failures++;
            echo "FAIL {$key}: " . ($msg !== '' ? $msg : 'result did not match scipy') . "\n";
        }
    }
    return $status;
}

$resultsPath = "{$root}/tools/parity/results.json";
$results = is_file($resultsPath) ? (json_decode((string) file_get_contents($resultsPath), true) ?: []) : [];
$results[$backend] ??= [];
$results['max_rel'][$backend] ??= [];
$failures = 0;
$checked = 0;
$t0 = microtime(true);
foreach ($files as $file) {
    $data = json_decode((string) file_get_contents($file), true, 64, JSON_THROW_ON_ERROR);
    $module = $data['module'] ?? '';
    if (isset($data['block_cases'])) {                       // numpy.block: nested-list assembly (pure-PHP Tessero\ArrayOps)
        foreach ($data['block_cases'] as $c) {
            $checked++;
            $w = 0.0;
            try {
                $got = \Tessero\ArrayOps::block(decodeValue($c['input'], $arrayClass));
                $p = compareValue($c['expect'], $got, 1e-12, 0.0, $w);
            } catch (\Throwable $e) {
                $p = 'threw ' . $e->getMessage();
            }
            $results[$backend]['np.block'] = ($results[$backend]['np.block'] ?? 'pass') === 'fail' ? 'fail' : ($p === null ? 'pass' : 'fail');
            $results['max_rel'][$backend]['np.block'] = null;
            if ($p !== null) { $failures++; echo "FAIL np.block: {$p}\n"; }
        }
    }
    if (isset($data['io_cases'])) {                          // numpy.loadtxt etc.: fixture provides the file content
        $np = $classes[$backend]['np'];
        $local = [];
        foreach ($data['io_cases'] as $c) {
            $key = "np.{$c['fn']}";
            $tmp = tempnam(sys_get_temp_dir(), 'tsrio');
            file_put_contents($tmp, isset($c['content_b64']) ? base64_decode($c['content_b64']) : $c['content']);
            $cargs = [$tmp];
            foreach (($c['kwargs'] ?? []) as $k => $v) {
                $cargs[camelName($k)] = decodeValue($v, $arrayClass);
            }
            $checked++;
            $w = 0.0;
            try {
                $got = [$np, camelName($c['fn'])](...$cargs);
                $p = compareValue($c['expect'], $got, 1e-12, 0.0, $w);
            } catch (\Throwable $e) {
                $p = 'threw ' . $e->getMessage();
            }
            @unlink($tmp);
            $local[$key] = ($local[$key] ?? 'pass') === 'fail' ? 'fail' : ($p === null ? 'pass' : 'fail');
            if ($p !== null) { $failures++; echo "FAIL {$key}: {$p}\n"; }
        }
        foreach (($data['savetxt_cases'] ?? []) as $c) {       // numpy.savetxt: write, read back, compare text
            $tmp = tempnam(sys_get_temp_dir(), 'tsrst');
            $cargs = [$tmp, decodeValue($c['input'], $arrayClass)];
            foreach (($c['kwargs'] ?? []) as $k => $v) { $cargs[camelName($k)] = decodeValue($v, $arrayClass); }
            $checked++;
            try {
                [$np, 'savetxt'](...$cargs);
                $got = (string) file_get_contents($tmp);
                $p = ($got === $c['expect_text']) ? null : 'text differs';
            } catch (\Throwable $e) {
                $p = 'threw ' . $e->getMessage();
            }
            @unlink($tmp);
            $local['np.savetxt'] = ($local['np.savetxt'] ?? 'pass') === 'fail' ? 'fail' : ($p === null ? 'pass' : 'fail');
            if ($p !== null) { $failures++; echo "FAIL np.savetxt: {$p}\n"; }
        }
        foreach ($local as $k => $s) { $results[$backend][$k] = $s; $results['max_rel'][$backend][$k] = null; }
        continue;
    }
    if (isset($data['matvardist_cases'])) {                 // scipy.stats matrix_t / normal_inverse_gamma (pure-PHP density facades)
        $local = [];
        foreach ($data['matvardist_cases'] as $c) {
            $key = 'stats.' . $c['kind'];
            $checked++;
            $ok = false; $msg = '';
            try {
                if ($c['kind'] === 'matrix_t') {
                    $rv = new \Tessero\Stats\MatrixT($c['mean'], $c['row'], $c['col'], (float) $c['df']);
                    $got = match ($c['method']) {
                        'pdf'    => $rv->pdf($c['X']),
                        'logpdf' => $rv->logpdf($c['X']),
                        default  => throw new \RuntimeException("unknown matrix_t method {$c['method']}"),
                    };
                } else { // normal_inverse_gamma
                    $rv = new \Tessero\Stats\NormalInverseGamma((float) $c['mu'], (float) $c['lmbda'], (float) $c['a'], (float) $c['b']);
                    $got = match ($c['method']) {
                        'pdf'    => $rv->pdf((float) $c['x'], (float) $c['s2']),
                        'logpdf' => $rv->logpdf((float) $c['x'], (float) $c['s2']),
                        'mean'   => $rv->mean(),
                        'var'    => $rv->var(),
                        default  => throw new \RuntimeException("unknown nig method {$c['method']}"),
                    };
                }
                $wf = []; $we = [$c['expect']]; array_walk_recursive($we, static function ($x) use (&$wf) { $wf[] = dec($x); });
                $g = $got;
                if (is_array($g)) {
                    $gf = []; foreach ($g as $e) { $gf[] = (is_object($e) && method_exists($e, 'item')) ? (float) $e->item() : (float) $e; }
                } elseif (is_object($g) && method_exists($g, 'toArray')) {
                    $gf = []; $ga = [$g->toArray()]; array_walk_recursive($ga, static function ($x) use (&$gf) { $gf[] = (float) $x; });
                } else {
                    $gf = [(float) $g];
                }
                $ok = count($gf) === count($wf);
                foreach ($wf as $i => $want) {
                    if (! $ok) { break; }
                    $gi = $gf[$i] ?? NAN;
                    if (is_nan($want)) { $ok = is_nan($gi); }
                    elseif (is_infinite($want)) { $ok = $gi === $want; }
                    else { $ok = abs($gi - $want) <= 1e-10 * (1 + abs($want)); }
                }
                if (! $ok) { $msg = "{$c['method']} did not match scipy.stats.{$c['kind']}"; }
            } catch (\Throwable $e) {
                $msg = $e->getMessage();
            }
            $local[$key] = ($local[$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        foreach ($local as $k => $s) { $results[$backend][$k] = $s; $results['max_rel'][$backend][$k] = null; }
        continue;
    }

    if (isset($data['metadist_cases'])) {                   // scipy.stats dist-infrastructure (pure-PHP Tessero\Stats meta-facades over Distribution)
        $local = [];
        $buildBase = static function (array $spec): \Tessero\Stats\Distribution {
            $p = $spec['params'];
            return match ($spec['name']) {
                'norm'    => \Tessero\Stats::norm($p[0], $p[1]),
                'uniform' => \Tessero\Stats::uniform($p[0], $p[1]),
                'expon'   => \Tessero\Stats::expon($p[0], $p[1]),
                default   => throw new \RuntimeException("metadist base {$spec['name']}"),
            };
        };
        foreach ($data['metadist_cases'] as $c) {
            $kind = $c['kind'];
            $key = 'stats.' . match ($kind) {
                'truncate' => 'truncate', 'order_statistic' => 'order_statistic',
                'mixture' => 'Mixture', 'exp' => 'exp', 'log' => 'log', 'abs' => 'abs',
                default => $kind,
            };
            $checked++;
            $ok = false; $msg = '';
            try {
                $rv = match ($kind) {
                    'truncate'        => new \Tessero\Stats\Truncated($buildBase($c['base']), (float) $c['lb'], (float) $c['ub']),
                    'order_statistic' => new \Tessero\Stats\OrderStatistic($buildBase($c['base']), (int) $c['n'], (int) $c['r']),
                    'mixture'         => new \Tessero\Stats\Mixture(array_map($buildBase, $c['components']), $c['weights']),
                    'exp'             => \Tessero\Stats\Transformed::exp($buildBase($c['base'])),
                    'log'             => \Tessero\Stats\Transformed::log($buildBase($c['base'])),
                    'abs'             => \Tessero\Stats\Transformed::abs($buildBase($c['base'])),
                    default           => throw new \RuntimeException("unknown metadist kind {$kind}"),
                };
                $arg = $c['arg'];
                $got = match ($c['method']) {
                    'pdf' => $rv->pdf($arg), 'logpdf' => $rv->logpdf($arg),
                    'cdf' => $rv->cdf($arg), 'logcdf' => $rv->logcdf($arg),
                    'ccdf' => $rv->ccdf($arg), 'logccdf' => $rv->logccdf($arg),
                    'icdf' => $rv->icdf($arg), 'iccdf' => $rv->iccdf($arg),
                    'mean' => $rv->mean(), 'variance' => $rv->variance(),
                    'median' => $rv->median(), 'support' => $rv->support(),
                    default => throw new \RuntimeException("unknown metadist method {$c['method']}"),
                };
                $wf = []; $we = [$c['expect']]; array_walk_recursive($we, static function ($x) use (&$wf) { $wf[] = dec($x); });
                $g = $got;
                if (is_array($g)) {
                    $gf = []; foreach ($g as $e) { $gf[] = (is_object($e) && method_exists($e, 'item')) ? (float) $e->item() : (float) $e; }
                } elseif (is_object($g) && method_exists($g, 'toArray')) {
                    $gf = []; $ga = [$g->toArray()]; array_walk_recursive($ga, static function ($x) use (&$gf) { $gf[] = (float) $x; });
                } else {
                    $gf = [(float) $g];
                }
                $ok = count($gf) === count($wf);
                foreach ($wf as $i => $want) {
                    if (! $ok) { break; }
                    $gi = $gf[$i] ?? NAN;
                    if (is_nan($want)) { $ok = is_nan($gi); }
                    elseif (is_infinite($want)) { $ok = $gi === $want; }
                    else { $ok = abs($gi - $want) <= 1e-10 * (1 + abs($want)); }
                }
                if (! $ok) { $msg = "{$c['method']} did not match scipy.stats.{$kind}"; }
            } catch (\Throwable $e) {
                $msg = $e->getMessage();
            }
            $local[$key] = ($local[$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        foreach ($local as $k => $s) { $results[$backend][$k] = $s; $results['max_rel'][$backend][$k] = null; }
        continue;
    }
    if (isset($data['matio_cases'])) {                      // scipy.io MATLAB v5 (pure-PHP Tessero\Io\MatIO)
        $local = [];
        $bump = static function (string $key, bool $ok) use (&$local): void {
            $local[$key] = ($local[$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
        };
        $cmpFlat = static function ($want, $got, float $tol = 1e-6): bool {
            if (count($want) !== count($got)) { return false; }
            foreach ($want as $i => $w) {
                if (is_string($w)) { if ((string) ($got[$i] ?? '') !== (string) $w) { return false; } continue; }
                if (abs((float) $w - (float) ($got[$i] ?? NAN)) > $tol + $tol * abs((float) $w)) { return false; }
            }
            return true;
        };
        foreach ($data['matio_cases'] as $c) {
            $checked++; $ok = false; $msg = ''; $kind = $c['kind']; $key = "scipyio.{$kind}";
            try {
                if ($kind === 'loadmat') {
                    $vars = \Tessero\Io\MatIO::read(base64_decode($c['content_b64']));
                    $ok = true;
                    foreach ($c['vars'] as $name => $exp) {
                        $v = $vars[$name] ?? null;
                        if ($v === null || $v['shape'] !== $exp['shape'] || $v['class'] !== $exp['class'] || ! $cmpFlat($exp['flat'], $v['data'])) { $ok = false; $msg = "var {$name}"; break; }
                    }
                    if ($ok) {
                        $info = \Tessero\Io\MatIO::info(base64_decode($c['content_b64']));
                        $wi = array_map(static fn ($r) => [$r[0], $r[1], $r[2]], $info);
                        $wantWhos = array_map(static fn ($r) => [$r[0], $r[1], $r[2]], $c['whos']);
                        $okWhos = $wi === $wantWhos;
                        $bump('scipyio.whosmat', $okWhos);
                        if (! $okWhos) { $ok = false; $msg = 'whos'; }
                    }
                    $key = 'scipyio.loadmat';
                } elseif ($kind === 'savemat') {
                    $bytes = \Tessero\Io\MatIO::write($c['input']);
                    $rb = \Tessero\Io\MatIO::read($bytes);
                    $ok = true;
                    foreach ($c['scipy_flat'] as $name => $exp) {
                        $v = $rb[$name] ?? null;
                        if ($v === null || $v['shape'] !== $exp['shape'] || $v['class'] !== $exp['class'] || ! $cmpFlat($exp['flat'], $v['data'])) { $ok = false; $msg = "roundtrip {$name}"; break; }
                    }
                    $key = 'scipyio.savemat';
                } else { $msg = "unknown kind {$kind}"; }
            } catch (\Throwable $e) { $msg = $e->getMessage(); }
            $bump($key, $ok);
            if (! $ok) { $failures++; echo "FAIL {$key} [{$c['name']}]: {$msg}\n"; }
        }
        foreach ($local as $k => $s) { $results[$backend][$k] = $s; $results['max_rel'][$backend][$k] = null; }
        continue;
    }
    if (isset($data['netcdf_cases'])) {                      // scipy.io netCDF-3 (pure-PHP Tessero\Io\NetCDF)
        $local = [];
        $bump = static function (string $key, bool $ok) use (&$local): void {
            $local[$key] = ($local[$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
        };
        $cmpFlat = static function ($want, $got, float $tol = 1e-6): bool {
            if (is_string($want) || is_string($got)) { return (string) $want === (string) $got; }
            if (count($want) !== count($got)) { return false; }
            foreach ($want as $i => $w) {
                if (abs((float) $w - (float) $got[$i]) > $tol + $tol * abs((float) $w)) { return false; }
            }
            return true;
        };
        $cmpAttrs = static function (array $want, array $got) use ($cmpFlat): bool {
            foreach ($want as $k => $wv) {
                if (! array_key_exists($k, $got)) { return false; }
                $gv = $got[$k];
                if (is_string($wv) || is_string($gv)) { if ((string) $wv !== (string) $gv) { return false; } }
                elseif (is_array($wv) || is_array($gv)) { if (! $cmpFlat((array) $wv, (array) $gv)) { return false; } }
                elseif (abs((float) $wv - (float) $gv) > 1e-6 + 1e-6 * abs((float) $wv)) { return false; }
            }
            return true;
        };
        $cmpDecode = static function (array $c, array $r) use ($cmpFlat, $cmpAttrs): array {
            if ((int) $r['numrecs'] !== (int) $c['numrecs']) { return [false, 'numrecs ' . $r['numrecs']]; }
            foreach ($c['dims'] as $dn => $dl) {
                if (! array_key_exists($dn, $r['dimensions'])) { return [false, "missing dim {$dn}"]; }
                if ($r['dimensions'][$dn] !== $dl) { return [false, "dim {$dn}"]; }
            }
            if (! $cmpAttrs($c['global'], $r['attrs'])) { return [false, 'global attrs differ']; }
            foreach ($c['vars'] as $vn => $ev) {
                if (! isset($r['variables'][$vn])) { return [false, "missing var {$vn}"]; }
                $rv = $r['variables'][$vn];
                if ($rv['typecode'] !== $ev['typecode']) { return [false, "var {$vn} typecode"]; }
                if ($rv['shape'] !== $ev['shape']) { return [false, "var {$vn} shape"]; }
                if (! $cmpFlat($ev['flat'], $rv['data'])) { return [false, "var {$vn} data"]; }
                if (! $cmpAttrs($ev['attrs'], $rv['attrs'])) { return [false, "var {$vn} attrs"]; }
            }
            return [true, ''];
        };
        foreach ($data['netcdf_cases'] as $c) {
            $checked++; $ok = false; $msg = '';
            try {
                if ($c['kind'] === 'netcdf_read') {
                    $r = \Tessero\Io\NetCDF::read(base64_decode($c['content_b64']));
                    [$ok, $msg] = $cmpDecode($c, $r);
                } elseif ($c['kind'] === 'netcdf_write') {
                    $bytes = \Tessero\Io\NetCDF::write($c['spec']);
                    $okBytes = $bytes === base64_decode($c['content_b64']);
                    $r = \Tessero\Io\NetCDF::read($bytes);
                    [$okRead, $msg] = $cmpDecode($c, $r);
                    $ok = $okBytes && $okRead;
                    if (! $okBytes) { $msg = 'bytes differ from scipy; ' . $msg; }
                } else { $msg = "unknown kind {$c['kind']}"; }
            } catch (\Throwable $e) { $msg = $e->getMessage(); }
            $bump('scipyio.netcdf_file', $ok);
            $bump('scipyio.netcdf_variable', $ok);
            if (! $ok) { $failures++; echo "FAIL scipyio.netcdf [{$c['name']}]: {$msg}\n"; }
        }
        foreach ($local as $k => $s) { $results[$backend][$k] = $s; $results['max_rel'][$backend][$k] = null; }
        continue;
    }
    if (isset($data['closest_stft_dual_cases'])) {          // scipy.signal.closest_STFT_dual_window (pure-PHP Tessero\Signal\ClosestStftDualWindow)
        foreach ($data['closest_stft_dual_cases'] as $c) {
            $key = 'signal.closest_STFT_dual_window';
            $rtol = (float) ($c['rtol'] ?? 1e-9);
            $atol = (float) ($c['atol'] ?? 1e-11);
            $checked++;
            $ok = true; $msg = '';
            $reC = static fn ($v) => is_array($v) ? [(float) $v[0], (float) ($v[1] ?? 0.0)] : [(float) $v, 0.0];
            try {
                $got = \Tessero\Signal\ClosestStftDualWindow::compute(
                    $c['win'], (int) $c['hop'], $c['desired_dual'] ?? null, (bool) ($c['scaled'] ?? true));
                foreach ($c['expect']['dual_win'] as $i => $ev) {
                    [$er, $ei] = $reC($ev);
                    [$gr, $gi] = $reC($got['dual_win'][$i]);
                    if (abs($gr - $er) > $atol + $rtol * abs($er) || abs($gi - $ei) > $atol + $rtol * abs($ei)) {
                        $ok = false; $msg = "dual_win[{$i}]"; break;
                    }
                }
                if ($ok) {
                    [$ear, $eai] = $reC($c['expect']['alpha']);
                    [$gar, $gai] = $reC($got['alpha']);
                    if (abs($gar - $ear) > $atol + $rtol * abs($ear) || abs($gai - $eai) > $atol + $rtol * abs($eai)) {
                        $ok = false; $msg = 'alpha';
                    }
                }
            } catch (\Throwable $e) { $ok = false; $msg = $e->getMessage(); }
            $results[$backend][$key] = ($results[$backend][$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            $results['max_rel'][$backend][$key] = null;
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        continue;
    }
    if (isset($data['scipyio_cases'])) {                     // scipy.io file formats: MatrixMarket / WAV / FortranFile (pure-PHP Tessero\Io)
        $local = [];
        $bump = static function (string $key, bool $ok) use (&$local): void {
            $local[$key] = ($local[$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
        };
        $cmpFlat = static function (array $want, array $got, float $tol = 1e-9): bool {
            if (count($want) !== count($got)) {
                return false;
            }
            foreach ($want as $i => $w) {
                if (is_string($w)) { if ((string) ($got[$i] ?? '') !== (string) $w) { return false; } continue; }
                $g = $got[$i];
                if (is_nan((float) $w)) {
                    if (! is_nan((float) $g)) { return false; }
                } elseif (abs((float) $w - (float) $g) > $tol + $tol * abs((float) $w)) {
                    return false;
                }
            }

            return true;
        };
        foreach ($data['scipyio_cases'] as $c) {
            $kind = $c['kind'];
            $checked++;
            $ok = false;
            $msg = '';
            try {
                switch ($kind) {
                    case 'mmread':
                        $r = \Tessero\Io\MatrixMarket::read(base64_decode($c['content_b64']));
                        $flat = [];
                        foreach ($r['data'] as $row) {
                            foreach ($row as $v) {
                                if (is_array($v)) { $flat[] = $v[0]; $flat[] = $v[1]; }   // complex re/im
                                else { $flat[] = $v; }
                            }
                        }
                        $okShape = $r['rows'] === $c['rows'] && $r['cols'] === $c['cols'];
                        $info = \Tessero\Io\MatrixMarket::info(base64_decode($c['content_b64']));
                        $okInfo = $info === $c['info'] || [$info[0], $info[1], $info[2], $info[3], $info[4], $info[5]] === $c['info'];
                        $ok = $okShape && $cmpFlat($c['flat'], $flat) && $okInfo;
                        if (! $ok) { $msg = $okShape ? ($okInfo ? 'data differs' : 'mminfo ' . json_encode($info) . ' want ' . json_encode($c['info'])) : "shape {$r['rows']}x{$r['cols']}"; }
                        $key = 'scipyio.mmread';
                        $bump('scipyio.mminfo', $okInfo);
                        break;

                    case 'mmwrite':
                        $text = \Tessero\Io\MatrixMarket::write($c['data'], $c['format'], $c['field']);
                        $r = \Tessero\Io\MatrixMarket::read($text);
                        $flat = [];
                        foreach ($r['data'] as $row) {
                            foreach ($row as $v) {
                                if (is_array($v)) { $flat[] = $v[0]; $flat[] = $v[1]; }
                                else { $flat[] = $v; }
                            }
                        }
                        $want = [];
                        foreach ($c['data'] as $row) {
                            foreach ($row as $v) {
                                if (is_array($v)) { $want[] = $v[0]; $want[] = $v[1]; }
                                else { $want[] = $v; }
                            }
                        }
                        $ok = $r['rows'] === $c['rows'] && $r['cols'] === $c['cols'] && $cmpFlat($want, $flat);
                        if (! $ok) { $msg = 'write/re-read differs'; }
                        $key = 'scipyio.mmwrite';
                        break;

                    case 'wavread':
                        $r = \Tessero\Io\Wav::read(base64_decode($c['content_b64']));
                        $ok = $r['rate'] === $c['rate'] && $r['channels'] === $c['channels']
                            && $r['dtype'] === $c['dtype'] && $cmpFlat($c['flat'], $r['data']);
                        if (! $ok) { $msg = "rate={$r['rate']} ch={$r['channels']} dtype={$r['dtype']}"; }
                        $key = 'scipyio.wavfile';
                        break;

                    case 'wavwrite':
                        $bytes = \Tessero\Io\Wav::write($c['rate'], $c['flat'], $c['dtype'], $c['channels']);
                        $r = \Tessero\Io\Wav::read($bytes);
                        $ok = $r['rate'] === $c['rate'] && $r['channels'] === $c['channels']
                            && $r['dtype'] === $c['dtype'] && $cmpFlat($c['flat'], $r['data']);
                        if (! $ok) { $msg = 'wav write/re-read differs'; }
                        $key = 'scipyio.wavfile';
                        break;

                    case 'fortranread':
                        $recs = \Tessero\Io\FortranFile::readRecords(base64_decode($c['content_b64']), $c['dtype'], $c['header_dtype']);
                        $ok = count($recs) === count($c['records']);
                        foreach ($c['records'] as $i => $want) {
                            if (! $ok || ! isset($recs[$i]) || ! $cmpFlat($want, $recs[$i])) { $ok = false; break; }
                        }
                        if (! $ok) { $msg = 'records differ (' . count($recs) . ' read)'; }
                        $key = 'scipyio.FortranFile';
                        break;

                    case 'fortranwrite':
                        $bytes = \Tessero\Io\FortranFile::writeRecords($c['records'], $c['dtype']);
                        $recs = \Tessero\Io\FortranFile::readRecords($bytes, $c['dtype']);
                        $ok = count($recs) === count($c['records']);
                        foreach ($c['records'] as $i => $want) {
                            if (! $ok || ! isset($recs[$i]) || ! $cmpFlat($want, $recs[$i])) { $ok = false; break; }
                        }
                        if (! $ok) { $msg = 'fortran write/re-read differs'; }
                        $key = 'scipyio.FortranFile';
                        break;

                    case 'hb_read':
                        $r = \Tessero\Io\HarwellBoeing::read(base64_decode($c['content_b64']));
                        $okShape = $r['nrows'] === $c['nrows'] && $r['ncols'] === $c['ncols'];
                        $okCsc = $r['indptr'] === $c['indptr'] && $r['indices'] === $c['indices'];
                        $dense = [];
                        for ($i = 0; $i < $r['nrows']; $i++) { $dense[$i] = array_fill(0, $r['ncols'], 0.0); }
                        for ($col = 0; $col < $r['ncols']; $col++) {
                            for ($k = $r['indptr'][$col]; $k < $r['indptr'][$col + 1]; $k++) {
                                $dense[$r['indices'][$k]][$col] = (float) $r['data'][$k];
                            }
                        }
                        $flat = [];
                        foreach ($dense as $row) { foreach ($row as $v) { $flat[] = $v; } }
                        $ok = $okShape && $okCsc && $cmpFlat($c['flat'], $flat);
                        if (! $ok) { $msg = $okShape ? ($okCsc ? 'values differ' : 'csc arrays differ') : "shape {$r['nrows']}x{$r['ncols']}"; }
                        $key = 'scipyio.hb_read';
                        break;

                    case 'hb_write':
                        $data2 = $c['is_int'] ? array_map('intval', $c['data']) : array_map('floatval', $c['data']);
                        $text = \Tessero\Io\HarwellBoeing::write($c['nrows'], $c['ncols'], $c['indptr'], $c['indices'], $data2);
                        $byteOk = ($text === base64_decode($c['content_b64']));
                        $rw = \Tessero\Io\HarwellBoeing::read($text);
                        $dense = [];
                        for ($i = 0; $i < $rw['nrows']; $i++) { $dense[$i] = array_fill(0, $rw['ncols'], 0.0); }
                        for ($col = 0; $col < $rw['ncols']; $col++) {
                            for ($k = $rw['indptr'][$col]; $k < $rw['indptr'][$col + 1]; $k++) {
                                $dense[$rw['indices'][$k]][$col] = (float) $rw['data'][$k];
                            }
                        }
                        $flat = [];
                        foreach ($dense as $row) { foreach ($row as $v) { $flat[] = $v; } }
                        $ok = $byteOk && $cmpFlat($c['flat'], $flat);
                        if (! $ok) { $msg = $byteOk ? 'roundtrip differs' : 'bytes differ from scipy'; }
                        $key = 'scipyio.hb_write';
                        break;

                    case 'readsav':
                        $vars = \Tessero\Io\IdlSave::read(base64_decode($c['content_b64']));
                        $ok = true;
                        foreach ($c['vars'] as $vn => $spec) {
                            $g = $vars[$vn] ?? null;
                            if ($g === null || $g['shape'] !== $spec['shape'] || $g['type'] !== $spec['type']
                                || ! $cmpFlat($spec['flat'], $g['data'], 1e-6)) {
                                $ok = false; $msg = "var {$vn}"; break;
                            }
                        }
                        $key = 'scipyio.readsav';
                        break;

                    default:
                        $key = "scipyio.{$kind}";
                        $msg = "unknown kind {$kind}";
                }
            } catch (\Throwable $e) {
                $key = $key ?? "scipyio.{$kind}";
                $msg = $e->getMessage();
            }
            $bump($key, $ok);
            if (! $ok) { $failures++; echo "FAIL {$key} [{$c['name']}]: {$msg}\n"; }
        }
        foreach ($local as $k => $s) { $results[$backend][$k] = $s; $results['max_rel'][$backend][$k] = null; }
        continue;
    }
    if (isset($data['sparse_npz_cases'])) {                  // scipy.sparse.save_npz / load_npz round-trip
        $local = [];
        foreach ($data['sparse_npz_cases'] as $c) {
            $key = 'sparse.' . ($c['dir'] === 'load' ? 'load_npz' : 'save_npz');
            $checked++;
            $tmp = tempnam(sys_get_temp_dir(), 'spnpz') . '.npz';
            try {
                if ($c['dir'] === 'load') {
                    file_put_contents($tmp, base64_decode($c['npz_b64']));
                    $got = \Tessero\Io\SparseNpz::load($tmp);
                } else {
                    $csrIn = [
                        'data'    => $arrayClass::array($c['csr']['data'], 'float64'),
                        'indices' => $arrayClass::array($c['csr']['indices'], 'int32'),
                        'indptr'  => $arrayClass::array($c['csr']['indptr'], 'int32'),
                        'shape'   => $c['csr']['shape'],
                    ];
                    \Tessero\Io\SparseNpz::save($tmp, $csrIn, (bool) $c['is_array']);
                    $got = \Tessero\Io\SparseNpz::load($tmp);
                }
                $e = $c['expect'];
                $flat = static fn ($v) => (is_object($v) && method_exists($v, 'toList')) ? $v->toList() : (array) $v;
                $p = null;
                $gi = array_map('intval', $flat($got['indices']));
                $gp = array_map('intval', $flat($got['indptr']));
                if ($got['format'] !== $e['format']) { $p = "format {$got['format']}"; }
                elseif ($got['shape'] !== [(int) $e['shape'][0], (int) $e['shape'][1]]) { $p = 'shape ' . json_encode($got['shape']); }
                elseif ((bool) $got['is_array'] !== (bool) $e['is_array']) { $p = 'is_array ' . var_export($got['is_array'], true); }
                else {
                    $gd = array_map('floatval', $flat($got['data']));
                    $ed = array_map(static fn ($x) => is_string($x) ? dec($x) : (float) $x, $e['data']);
                    if (count($gd) !== count($ed)) { $p = 'data length ' . count($gd) . ' vs ' . count($ed); }
                    else { foreach ($ed as $i => $wv) { if (abs($gd[$i] - (float) $wv) > 1e-12 * (1 + abs((float) $wv))) { $p = "data[{$i}] {$gd[$i]} vs {$wv}"; break; } } }
                    if ($p === null && $gi !== array_map('intval', $e['indices'])) { $p = 'indices differ'; }
                    if ($p === null && $gp !== array_map('intval', $e['indptr'])) { $p = 'indptr differ'; }
                }
            } catch (\Throwable $ex) {
                $p = 'threw ' . $ex->getMessage();
            }
            @unlink($tmp);
            $local[$key] = ($local[$key] ?? 'pass') === 'fail' ? 'fail' : ($p === null ? 'pass' : 'fail');
            if ($p !== null) { $failures++; echo "FAIL {$key}: {$p}\n"; }
        }
        foreach ($local as $k => $s) { $results[$backend][$k] = $s; $results['max_rel'][$backend][$k] = null; }
        continue;
    }
    if (isset($data['datetime_cases'])) {                    // numpy datetime64 / busday / isnat (pure-PHP, int64 counts)
        $local = [];
        foreach ($data['datetime_cases'] as $c) {
            $key = "datetime.{$c['fn']}";
            $checked++;
            $args = $c['args'];
            foreach (($c['kwargs'] ?? []) as $k => $v) {
                $args[$k] = $v;                              // named args (unit, weekmask, holidays, roll, offset)
            }
            $ok = false; $msg = '';
            try {
                $got = [\Tessero\Datetime\Datetime::class, camelName($c['fn'])](...$args);
                $ok = dtEqual($got, $c['expect']);
                if (! $ok) { $msg = 'got ' . json_encode($got) . ' want ' . json_encode($c['expect']); }
            } catch (\Throwable $e) {
                $msg = $e->getMessage();
            }
            $local[$key] = ($local[$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        foreach ($local as $k => $s) { $results[$backend][$k] = $s; $results['max_rel'][$backend][$k] = null; }
        continue;
    }
    if (isset($data['spatial_cases'])) {                     // scipy.spatial.cKDTree: construct a tree, then query
        $local = [];
        foreach ($data['spatial_cases'] as $c) {
            $key = "spatial.{$c['fn']}";
            $checked++;
            $ok = false; $msg = '';
            try {
                $tree = new \Tessero\Spatial\KDTree($c['data']);
                [$d, $i] = $tree->query($c['query'], (int) ($c['k'] ?? 1));
                $ok = vecClose(flattenNums($d), flattenNums($c['expect']['distances']), 1e-9)
                    && flattenNums($i) === flattenNums($c['expect']['indices']);
                if (! $ok) { $msg = 'distances or indices did not match scipy'; }
            } catch (\Throwable $e) {
                $msg = $e->getMessage();
            }
            $local[$key] = ($local[$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        foreach ($local as $k => $s) { $results[$backend][$k] = $s; $results['max_rel'][$backend][$k] = null; }
        continue;
    }
    // ===== scipy.cluster.hierarchy data-structure classes (pure-PHP Tessero\Cluster\Hierarchy) =====
    // Place EARLY in the per-fixture loop. ClusterNode/to_tree tree structure, DisjointSet union-find op log,
    // dendrogram(no_plot=True) dict payload (default + custom palette) + set_link_color_palette effect.
    if (isset($data['totree_cases']) || isset($data['dendro_cases']) || isset($data['disjoint_cases'])) {
        $local = [];
        $mark = static function (string $key, bool $ok, string $msg) use (&$local, &$failures): void {
            $local[$key] = ($local[$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        };
        $tol = static fn (float $a, float $b): bool => $a === $b
            || abs($a - $b) <= 1e-12 * max(abs($a), abs($b)) + 0.0;

        foreach (($data['totree_cases'] ?? []) as $c) {
            $checked++;
            $okNode = true; $okTree = true; $msg = '';
            try {
                $Z = decodeValue($c['Z'], $arrayClass);
                [$root, $nodes] = \Tessero\Cluster\Hierarchy\Trees::toTree($Z, true);
                $exp = $c['expect'];
                $N = count($exp['ids']);
                for ($k = 0; $k < $N; $k++) {
                    $nd = $nodes[$k];
                    if ($nd->getId() !== (int) $exp['ids'][$k]) { $okNode = false; $msg = "id[$k]"; break; }
                    if ($nd->getCount() !== (int) $exp['counts'][$k]) { $okNode = false; $msg = "count[$k]"; break; }
                    if (! $tol((float) $nd->dist, (float) $exp['dists'][$k])) { $okNode = false; $msg = "dist[$k]"; break; }
                    if ($nd->isLeaf() !== (bool) $exp['is_leaf'][$k]) { $okNode = false; $msg = "is_leaf[$k]"; break; }
                    $le = $exp['left'][$k]; $ri = $exp['right'][$k];
                    $gl = $nd->getLeft() === null ? null : $nd->getLeft()->getId();
                    $gr = $nd->getRight() === null ? null : $nd->getRight()->getId();
                    if ($gl !== ($le === null ? null : (int) $le)) { $okNode = false; $msg = "left[$k]"; break; }
                    if ($gr !== ($ri === null ? null : (int) $ri)) { $okNode = false; $msg = "right[$k]"; break; }
                }
                $pre = array_map('intval', $root->preOrder());
                $wantPre = array_map('intval', $exp['preorder']);
                if ($pre !== $wantPre) { $okTree = false; $msg = $msg ?: 'preorder'; }
            } catch (\Throwable $e) { $okNode = $okTree = false; $msg = $e->getMessage(); }
            $mark('hierarchy.ClusterNode', $okNode && $okTree, $msg);
            $mark('hierarchy.to_tree', $okNode && $okTree, $msg);
        }

        foreach (($data['dendro_cases'] ?? []) as $c) {
            $checked++;
            $ok = true; $msg = '';
            try {
                $Z = decodeValue($c['Z'], $arrayClass);
                \Tessero\Cluster\Hierarchy\Trees::setLinkColorPalette($c['palette'] ?? null);
                $d = \Tessero\Cluster\Hierarchy\Trees::dendrogram($Z);
                \Tessero\Cluster\Hierarchy\Trees::setLinkColorPalette(null);
                $exp = $c['expect'];
                foreach (['icoord', 'dcoord'] as $kk) {
                    if (count($d[$kk]) !== count($exp[$kk])) { $ok = false; $msg = "$kk nrows"; break; }
                    foreach ($exp[$kk] as $ri => $row) {
                        foreach ($row as $ci => $v) {
                            if (! $tol((float) $d[$kk][$ri][$ci], (float) $v)) { $ok = false; $msg = "$kk [$ri][$ci]"; break 3; }
                        }
                    }
                }
                if ($ok) {
                    if (array_map('strval', $d['ivl']) !== array_map('strval', $exp['ivl'])) { $ok = false; $msg = 'ivl'; }
                    elseif (array_map('intval', $d['leaves']) !== array_map('intval', $exp['leaves'])) { $ok = false; $msg = 'leaves'; }
                    elseif (array_map('strval', $d['color_list']) !== array_map('strval', $exp['color_list'])) { $ok = false; $msg = 'color_list'; }
                    else {
                        $gl = array_map(static fn ($x) => $x === null ? null : (string) $x, $d['leaves_color_list']);
                        $el = array_map(static fn ($x) => $x === null ? null : (string) $x, $exp['leaves_color_list']);
                        if ($gl !== $el) { $ok = false; $msg = 'leaves_color_list'; }
                    }
                }
            } catch (\Throwable $e) {
                \Tessero\Cluster\Hierarchy\Trees::setLinkColorPalette(null);
                $ok = false; $msg = $e->getMessage();
            }
            $mark('hierarchy.dendrogram', $ok, $msg);
            $mark('hierarchy.set_link_color_palette', $ok, $msg);
        }

        foreach (($data['disjoint_cases'] ?? []) as $c) {
            $checked++;
            $ok = true; $msg = '';
            try {
                $ds = new \Tessero\Cluster\Hierarchy\DisjointSet($c['elements']);
                foreach ($c['ops'] as $op) {
                    $a = $op['args'];
                    switch ($op['op']) {
                        case 'merge':    $got = $ds->merge($a[0], $a[1]); break;
                        case 'getitem':  $got = $ds[$a[0]]; break;
                        case 'subset_size': $got = $ds->subsetSize($a[0]); break;
                        case 'contains': $got = isset($ds[$a[0]]); break;
                        case 'connected': $got = $ds->connected($a[0], $a[1]); break;
                        case 'subset':   $got = $ds->subset($a[0]); sort($got); $got = array_map('intval', $got); break;
                        default: throw new \RuntimeException('bad op ' . $op['op']);
                    }
                    $want = $op['ret'];
                    if (is_array($want)) { $want = array_map('intval', $want); }
                    if ($got !== $want) { $ok = false; $msg = $op['op'] . ' => ' . json_encode($got) . ' != ' . json_encode($want); break; }
                }
                if ($ok) {
                    if (count($ds) !== (int) $c['len']) { $ok = false; $msg = 'len'; }
                    elseif ($ds->nSubsets !== (int) $c['n_subsets']) { $ok = false; $msg = 'n_subsets'; }
                    elseif (array_map('intval', iterator_to_array($ds, false)) !== array_map('intval', $c['iter'])) { $ok = false; $msg = 'iter'; }
                    else {
                        $gs = array_map(static function ($s) { $s = array_map('intval', $s); sort($s); return $s; }, $ds->subsets());
                        $es = array_map(static function ($s) { $s = array_map('intval', $s); sort($s); return $s; }, $c['subsets']);
                        if ($gs !== $es) { $ok = false; $msg = 'subsets'; }
                    }
                }
            } catch (\Throwable $e) { $ok = false; $msg = $e->getMessage(); }
            $mark('hierarchy.DisjointSet', $ok, $msg);
        }

        foreach (($data['disjoint_err_cases'] ?? []) as $c) {
            $checked++;
            $threw = false;
            try {
                $ds = new \Tessero\Cluster\Hierarchy\DisjointSet($c['elements']);
                $ds[$c['args'][0]];
            } catch (\Throwable $e) { $threw = true; }
            $mark('hierarchy.DisjointSet', $threw, 'expected KeyError-like throw on missing element');
        }

        foreach ($local as $k => $s) { $results[$backend][$k] = $s; $results['max_rel'][$backend][$k] = null; }
        continue;
    }

    if (isset($data['sphvor_cases']) || isset($data['halfspace_cases'])) {   // scipy.spatial.SphericalVoronoi + HalfspaceIntersection (pure-PHP convex-hull dual)
        $local = [];
        foreach (($data['sphvor_cases'] ?? []) as $c) {
            $key = 'spatial.SphericalVoronoi';
            $checked++;
            $ok = false; $msg = '';
            try {
                $center = array_key_exists('center', $c) && $c['center'] !== null ? $c['center'] : null;
                $sv = new \Tessero\Spatial\SphericalVoronoi($c['points'], (float) $c['radius'], $center);
                $ok = spatialSetMatch($sv->vertices, $c['vertices'], 1e-9);
                if (! $ok) { $msg = 'SphericalVoronoi vertex set did not match scipy'; }
            } catch (\Throwable $e) { $msg = $e->getMessage(); }
            $local[$key] = ($local[$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        foreach (($data['halfspace_cases'] ?? []) as $c) {
            $key = 'spatial.HalfspaceIntersection';
            $checked++;
            $ok = false; $msg = '';
            try {
                $hi = new \Tessero\Spatial\HalfspaceIntersection($c['halfspaces'], $c['interior_point']);
                $okInt = spatialSetMatch($hi->intersections, $c['intersections'], 1e-9);
                $dv = $hi->dualVertices; sort($dv);
                $exp = array_map('intval', $c['dual_vertices']); sort($exp);
                $okDv = ($dv === $exp);
                $ok = $okInt && $okDv;
                if (! $ok) { $msg = $okInt ? 'dual_vertices set did not match scipy' : 'intersections set did not match scipy'; }
            } catch (\Throwable $e) { $msg = $e->getMessage(); }
            $local[$key] = ($local[$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        foreach ($local as $k => $s) { $results[$backend][$k] = $s; $results['max_rel'][$backend][$k] = null; }
        continue;
    }
    if (isset($data['splinalg_linop_cases'])) {              // scipy.sparse.linalg LinearOperator / aslinearoperator / LaplacianNd (pure-PHP Tessero\Sparse\Linalg)
        $local = [];
        foreach ($data['splinalg_linop_cases'] as $c) {
            if ($c['op'] === 'laplacian') { $key = 'splinalg.LaplacianNd'; }
            elseif (($c['source'] ?? '') === 'csr') { $key = 'splinalg.aslinearoperator'; }
            elseif ($c['op'] === 'linop' && in_array(($c['act'] ?? ''), ['matvec', 'rmatvec'], true) && ($c['source'] ?? '') === 'matrix' && !isset($c['kind2']) && !isset($c['scalar'])) { $key = 'splinalg.aslinearoperator'; }
            else { $key = 'splinalg.LinearOperator'; }
            $checked++;
            $p = null;
            try {
                $got = runLinopCase($c);
                if (!vecClose(flattenNums($got), flattenNums($c['expect']), 1e-12)) { $p = 'mismatch'; }
            } catch (\Throwable $e) { $p = 'threw ' . $e->getMessage(); }
            $local[$key] = ($local[$key] ?? 'pass') === 'fail' ? 'fail' : ($p === null ? 'pass' : 'fail');
            if ($p !== null) { $failures++; echo "FAIL {$key}: {$p}\n"; }
        }
        foreach ($local as $k => $s) { $results[$backend][$k] = $s; $results['max_rel'][$backend][$k] = null; }
        continue;
    }
    if (isset($data['mgc_cases'])) {
        $local = [];
        foreach ($data['mgc_cases'] as $c) {
            $key = 'stats.multiscale_graphcorr';
            $rtol = (float) ($c['rtol'] ?? 1e-11);
            $checked++;
            $ok = false; $msg = '';
            try {
                $x = array_map(static fn ($r) => is_array($r) ? array_map('floatval', $r) : (float) $r, $c['x']);
                $y = array_map(static fn ($r) => is_array($r) ? array_map('floatval', $r) : (float) $r, $c['y']);
                $got = \Tessero\Stats\MultiscaleGraphcorr::multiscaleGraphcorr(
                    $x,
                    $y,
                    (bool) ($c['compute_distance'] ?? true),
                    (int) $c['reps'],
                    (int) $c['seed'],
                    (bool) ($c['is_twosamp'] ?? false),
                );
                $es = (float) $c['expect']['statistic'];
                $ep = (float) $c['expect']['pvalue'];
                $oks = abs($got['statistic'] - $es) <= $rtol * (1 + abs($es));
                $okp = abs($got['pvalue'] - $ep) <= 1e-12; // p-value is a rational k/(reps+1): exact
                $ok = $oks && $okp;
                if (! $ok) { $msg = 'did not match scipy'; }
            } catch (\Throwable $ex) { $msg = $ex->getMessage(); }
            $local[$key] = ($local[$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            if (! $ok) { $failures++; echo "FAIL {$key} ({$c['name']}): {$msg}\n"; }
        }
        foreach ($local as $k => $sx) { $results[$backend][$k] = $sx; $results['max_rel'][$backend][$k] = null; }
        continue;
    }

    if (isset($data['sobol_cases'])) {                       // scipy.stats.qmc.Sobol (pure-PHP Tessero\Stats\Qmc\Sobol)
        $key = 'stats.qmc.Sobol';
        $sRtol = (float) ($data['tol']['rtol'] ?? 1e-12);
        $sAtol = (float) ($data['tol']['atol'] ?? 1e-14);
        foreach ($data['sobol_cases'] as $c) {
            $checked++;
            $w = 0.0; $problem = null;
            try {
                $dim = (int) $c['dim']; $bits = (int) $c['bits']; $n = (int) $c['n'];
                $scr = (bool) $c['scramble']; $seed = $c['seed'] === null ? null : (int) $c['seed'];
                $got = (new \Tessero\Stats\Qmc\Sobol($dim, $scr, $seed, $bits))->random($n)->toArray();
                $want = $c['expect'];
                for ($i = 0; $i < $n && $problem === null; $i++) {
                    for ($j = 0; $j < $dim; $j++) {
                        [$ok, $rel] = close((float) $got[$i][$j], (float) $want[$i][$j], $sRtol, $sAtol);
                        if ($rel !== INF && $rel > $w) { $w = $rel; }
                        if (! $ok) { $problem = sprintf('dim=%d bits=%d scr=%d [%d][%d] got %.17g want %.17g',
                            $dim, $bits, $scr ? 1 : 0, $i, $j, (float) $got[$i][$j], (float) $want[$i][$j]); break; }
                    }
                }
            } catch (\Throwable $e) { $problem = 'threw ' . get_class($e) . ': ' . $e->getMessage(); }
            $results[$backend][$key] = ($results[$backend][$key] ?? 'pass') === 'fail' ? 'fail' : ($problem === null ? 'pass' : 'fail');
            $results['max_rel'][$backend][$key] = max((float) ($results['max_rel'][$backend][$key] ?? 0.0), $w);
            if ($problem !== null) { $failures++; echo "FAIL {$key}: {$problem}\n"; }
        }
        // NO continue: fall through so sobolindices_cases (same stats_sobol.json) also runs
    }
    if (isset($data['sobolindices_cases'])) {                // scipy.stats.sobol_indices (pure-PHP Tessero\Stats\SobolIndices)
        $key = 'stats.sobol_indices';
        $siRtol = (float) ($data['tol']['rtol'] ?? 1e-12);
        $siAtol = (float) ($data['tol']['atol'] ?? 1e-14);
        foreach ($data['sobolindices_cases'] as $c) {
            $checked++;
            $crtol = (float) ($c['rtol'] ?? $siRtol);
            $w = 0.0; $problem = null;
            try {
                $func = makeSobolIndicesFunc((string) $c['kind']);
                $dists = array_map(static fn ($p) => [(float) $p[0], (float) $p[1]], $c['dists']);
                $res = \Tessero\Stats\SobolIndices::sobolIndices($func, (int) $c['n'], $dists, (int) $c['seed']);
                foreach (['first_order', 'total_order'] as $kk) {
                    $got = $res[$kk]; $want = $c[$kk];
                    for ($o = 0; $o < count($want) && $problem === null; $o++) {
                        for ($i = 0; $i < count($want[$o]); $i++) {
                            [$ok, $rel] = close((float) $got[$o][$i], (float) $want[$o][$i], $crtol, $siAtol);
                            if ($rel !== INF && $rel > $w) { $w = $rel; }
                            if (! $ok) { $problem = sprintf('%s %s [%d][%d] got %.17g want %.17g',
                                $c['kind'], $kk, $o, $i, (float) $got[$o][$i], (float) $want[$o][$i]); break; }
                        }
                    }
                }
            } catch (\Throwable $e) { $problem = 'threw ' . get_class($e) . ': ' . $e->getMessage(); }
            $results[$backend][$key] = ($results[$backend][$key] ?? 'pass') === 'fail' ? 'fail' : ($problem === null ? 'pass' : 'fail');
            $results['max_rel'][$backend][$key] = max((float) ($results['max_rel'][$backend][$key] ?? 0.0), $w);
            if ($problem !== null) { $failures++; echo "FAIL {$key}: {$problem}\n"; }
        }
        continue;
    }

    if (isset($data['splu_cases'])) {                        // scipy.sparse.linalg.splu / factorized / SuperLU (pure-PHP solve layer over spsolve)
        $local = [];
        $splClass = $classes[$backend]['splinalg'];          // Tessero\SparseLinalg | Tessero\Ext\SparseLinalg
        foreach ($data['splu_cases'] as $c) {
            $checked++;
            $A = decodeValue($c['A'], $arrayClass)->toArray();
            $b = decodeValue($c['b'], $arrayClass)->toArray();
            $wantShape = [(int) $c['shape'][0], (int) $c['shape'][1]];
            $tol = $c['tol'] ?? ['rtol' => 1e-9, 'atol' => 1e-9];
            $rtol = (float) ($tol['rtol'] ?? 1e-9); $atol = (float) ($tol['atol'] ?? 1e-9);

            // flatten the expected x (vector or matrix) to a comparable float list
            $wantFlat = [];
            $we = [$c['expect']['data'] ?? $c['expect']];
            array_walk_recursive($we, static function ($x) use (&$wantFlat) {
                $wantFlat[] = is_string($x) ? dec($x) : (float) $x;
            });

            $flat = static function ($v): array {
                if (is_object($v) && method_exists($v, 'toArray')) { $v = $v->toArray(); }
                $out = []; $vv = [$v];
                array_walk_recursive($vv, static function ($x) use (&$out) { $out[] = (float) $x; });
                return $out;
            };
            $cmp = static function (array $got) use ($wantFlat, $rtol, $atol): ?string {
                if (count($got) !== count($wantFlat)) { return 'length ' . count($got) . ' vs ' . count($wantFlat); }
                foreach ($wantFlat as $i => $wv) {
                    if (abs($got[$i] - $wv) > $atol + $rtol * abs($wv)) { return "elem {$i} {$got[$i]} vs {$wv}"; }
                }
                return null;
            };

            foreach (['splu', 'factorized', 'SuperLU'] as $variant) {
                $key = 'splinalg.' . $variant;
                $p = null;
                try {
                    if ($variant === 'factorized') {
                        $solve = \Tessero\Sparse\Linalg\SuperLU::factorized($A, $splClass);
                        $got = $flat($solve($b));             // __invoke, like scipy's returned callable
                        $p = $cmp($got);
                    } else {
                        $lu = \Tessero\Sparse\Linalg\SuperLU::splu($A, $splClass);
                        if ($lu->shape() !== $wantShape) { $p = 'shape ' . json_encode($lu->shape()); }
                        else { $p = $cmp($flat($lu->solve($b))); }
                    }
                } catch (\Throwable $e) {
                    $p = 'threw ' . $e->getMessage();
                }
                $local[$key] = ($local[$key] ?? 'pass') === 'fail' ? 'fail' : ($p === null ? 'pass' : 'fail');
                if ($p !== null) { $failures++; echo "FAIL {$key}: {$p}\n"; }
            }
        }
        foreach ($local as $k => $s) { $results[$backend][$k] = $s; $results['max_rel'][$backend][$k] = null; }
        continue;
    }

    if (isset($data['ode_cases'])) {                    // scipy.integrate.ode / complex_ode (stateful stepper facade over SolveIvp; pure-PHP)
        $local = [];
        foreach ($data['ode_cases'] as $c) {
            $key = 'integrate.ode';
            $checked++;
            $ok = true; $msg = '';
            $complex = (bool) ($c['complex'] ?? false);
            try {
                if ($complex) {
                    $rhs = makeOdeComplexRhs((string) $c['kind'], (array) $c['params']);
                    $ode = \Tessero\Integrate\Ode::complexOde($rhs);
                    $ode->setIntegrator((string) $c['integrator'], (float) $c['rtol'], (float) $c['atol']);
                    $ode->setInitialValue($c['y0'], (float) $c['t0']);
                } else {
                    $rhs = makeOdeSystem((string) $c['kind'], (array) $c['params']);
                    $ode = new \Tessero\Integrate\Ode($rhs);
                    $ode->setIntegrator((string) $c['integrator'], (float) $c['rtol'], (float) $c['atol']);
                    $ode->setInitialValue(array_map('floatval', $c['y0']), (float) $c['t0']);
                }
                foreach ($c['ts'] as $i => $t) {
                    $y = $ode->integrate((float) $t);
                    if (! $ode->successful()) { $ok = false; $msg = 'not successful at t=' . $t; break; }
                    $exp = $c['expect'][$i];
                    foreach ($exp as $j => $ev) {
                        if ($complex) {
                            $gr = (float) $y[$j][0]; $gi = (float) $y[$j][1];
                            $er = (float) $ev[0]; $ei = (float) $ev[1];
                            if (abs($gr - $er) > 1e-7 + 1e-6 * abs($er) || abs($gi - $ei) > 1e-7 + 1e-6 * abs($ei)) {
                                $ok = false; $msg = 'off at t=' . $t . ' comp ' . $j; break 2;
                            }
                        } else {
                            $g = (float) $y[$j];
                            if (abs($g - (float) $ev) > 1e-7 + 1e-6 * abs((float) $ev)) {
                                $ok = false; $msg = 'off at t=' . $t . ' comp ' . $j; break 2;
                            }
                        }
                    }
                }
            } catch (\Throwable $e) {
                $ok = false; $msg = $e->getMessage();
            }
            $local[$key] = ($local[$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            if (! $ok) { $failures++; echo 'FAIL ' . $key . ': ' . $msg . "\n"; }
        }
        foreach ($local as $k => $s) { $results[$backend][$k] = $s; $results['max_rel'][$backend][$k] = null; }
        continue;
    }
    if (isset($data['dunnett_cases'])) {                    // scipy.stats.dunnett (pure-PHP Tessero\StatsDunnett)
        foreach ($data['dunnett_cases'] as $c) {
            $key = 'stats.dunnett';
            $rtol = (float) ($c['rtol'] ?? 1e-9);
            $atol = (float) ($c['atol'] ?? 1e-11);
            $checked++;
            $ok = false; $msg = '';
            try {
                $got = \Tessero\StatsDunnett::dunnett(
                    $c['samples'],
                    $c['control'],
                    (string) ($c['alternative'] ?? 'two-sided'),
                    (int) $c['seed']
                );
                $expS = $c['expect']['statistic'];
                $expP = $c['expect']['pvalue'];
                $ok = count($got['statistic']) === count($expS)
                    && count($got['pvalue']) === count($expP);
                for ($i = 0; $ok && $i < count($expS); $i++) {
                    $es = abs($got['statistic'][$i] - (float) $expS[$i]);
                    $ep = abs($got['pvalue'][$i] - (float) $expP[$i]);
                    if ($es > $atol + $rtol * abs((float) $expS[$i])) { $ok = false; }
                    if ($ep > $atol + $rtol * abs((float) $expP[$i])) { $ok = false; }
                }
                if (! $ok) { $msg = 'did not match scipy'; }
            } catch (\Throwable $e) {
                $msg = $e->getMessage();
            }
            $results[$backend][$key] = ($results[$backend][$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            $results['max_rel'][$backend][$key] = null;
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        continue;
    }
    if (isset($data['rvhistogram_cases'])) {                // scipy.stats.rv_histogram (pure-PHP Tessero\Stats\RvHistogram)
        foreach ($data['rvhistogram_cases'] as $c) {
            $key = 'stats.rv_histogram';
            $rtol = (float) ($c['rtol'] ?? 1e-9);
            $checked++;
            $ok = false; $msg = '';
            try {
                $d = new \Tessero\Stats\RvHistogram(
                    array_map('floatval', $c['counts']),
                    array_map('floatval', $c['bin_edges']),
                    (bool) $c['density'],
                );
                $method = (string) $c['method'];
                if (in_array($method, ['pdf', 'cdf', 'sf', 'ppf'], true)) {
                    $got = $d->{$method}(array_map('floatval', $c['arg']));
                } else {
                    $got = [$d->{$method}()];
                }
                $ok = true;
                foreach ($c['expect'] as $i => $e) {
                    $g = is_array($got) ? $got[$i] : $got;
                    if (abs($g - (float) $e) > $rtol * (1 + abs((float) $e))) { $ok = false; $msg = "{$method} idx {$i}"; break; }
                }
            } catch (\Throwable $e) {
                $msg = $e->getMessage();
            }
            $results[$backend][$key] = ($results[$backend][$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            $results['max_rel'][$backend][$key] = null;
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        continue;
    }
    if (isset($data['lsqbiv_cases'])) {                      // scipy.interpolate.LSQBivariateSpline (pure-PHP, fixed-knot tensor LS)
        $local = [];
        foreach ($data['lsqbiv_cases'] as $c) {
            $key = 'interpolate.LSQBivariateSpline';
            $checked++;
            $ok = false; $msg = '';
            try {
                $sp = new \Tessero\Interpolate\LSQBivariateSpline(
                    $c['x'], $c['y'], $c['z'], $c['tx'], $c['ty'], (int) $c['kx'], (int) $c['ky']);
                $got = $sp($c['xq'], $c['yq']);
                $ok = vecClose(flattenNums($got), flattenNums($c['expect']), 1e-9);
                if (! $ok) { $msg = 'values did not match scipy'; }
            } catch (\Throwable $e) {
                $msg = $e->getMessage();
            }
            $local[$key] = ($local[$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        foreach ($local as $k => $s) { $results[$backend][$k] = $s; $results['max_rel'][$backend][$k] = null; }
        continue;
    }

    // ===== CORRECTED czt_cases branch (scipy.signal.CZT) =====
    // Place EARLY in the per-fixture loop (alongside zoomfft_cases / findpeakscwt_cases),
    // before the generic numeric comparison.
    //
    // ROOT-CAUSE FIX: Tessero\Signal\Czt is a thin pure-PHP wrapper that forwards to the FFI
    // facade Tessero\Signal::czt (it hardcodes `use Tessero\Signal`). Feeding it a per-backend
    // $arrayClass NDArray breaks on ext: the FFI czt routine rejects a Tessero\Ext\NDArray with
    // "Arrays hold numbers or booleans, got Tessero\Ext\NDArray". Mirror the sibling wrapper
    // classes (ZoomFFT, FindPeaksCwt, PlacePoles) which always feed the FFI facade regardless of
    // the backend under test: build the complex inputs with the FFI \Tessero\NDArray, NOT $arrayClass.
    // (czt genuinely needs complex NDArray inputs for x/w/a, so a plain PHP array cannot be used.)
    if (isset($data['czt_cases'])) {                         // scipy.signal.CZT (pure-PHP Tessero\Signal\Czt over landed czt)
        $nd = \Tessero\NDArray::class;                        // FFI NDArray: the Czt wrapper always forwards to the FFI facade
        foreach ($data['czt_cases'] as $c) {
            $key = 'signal.CZT';
            $rtol = (float) ($c['rtol'] ?? 1e-12);
            $checked++;
            $ok = false; $msg = '';
            try {
                $cx = static function ($pair) use ($nd) {       // complex scalar from [re,im] (1-elem array), or null
                    if ($pair === null) { return null; }
                    return $nd::complex($nd::array([(float) $pair[0]], 'float64'),
                                        $nd::array([(float) $pair[1]], 'float64'));
                };
                $re = []; $im = [];
                foreach ($c['x'] as $p) { $re[] = (float) $p[0]; $im[] = (float) $p[1]; }
                $x = $nd::complex($nd::array($re, 'float64'), $nd::array($im, 'float64'));
                $czt = new \Tessero\Signal\Czt((int) $c['n'], $c['m'], $cx($c['w']), $cx($c['a']));
                $got = $czt($x);
                $ga = $got->toArray();
                $exp = $c['expect'];
                $ok = count($ga) === count($exp);
                foreach ($exp as $i => $e) {
                    if (! $ok || abs($ga[$i][0] - $e[0]) > $rtol * (1 + abs($e[0]))
                              || abs($ga[$i][1] - $e[1]) > $rtol * (1 + abs($e[1]))) { $ok = false; break; }
                }
                if (! $ok) { $msg = 'did not match scipy.signal.czt'; }
            } catch (\Throwable $e) { $msg = $e->getMessage(); }
            $results[$backend][$key] = ($results[$backend][$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            $results['max_rel'][$backend][$key] = null;
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        // NO continue: fall through so the zoomfft_cases branch (same signal_classes.json file) also runs.
        // This branch MUST be placed immediately BEFORE the zoomfft_cases branch, which ends in continue.
    }

    if (isset($data['splinefilter_cases'])) {               // scipy.signal.spline_filter (pure-PHP Tessero\Signal\SplineFilter over landed symiirorder2/cspline2d/sepfir2d)
        $sfSignal = $backend === 'ext' ? 'Tessero\Ext\Signal' : \Tessero\Signal::class;
        $sfNd = $arrayClass;
        foreach ($data['splinefilter_cases'] as $c) {
            $key = 'signal.spline_filter';
            $rtol = (float) ($c['rtol'] ?? 1e-10);
            $atol = (float) ($c['atol'] ?? 1e-12);
            $checked++;
            $ok = false; $msg = ''; $worstRel = 0.0;
            try {
                $in = $sfNd::array(array_map(static fn ($row) => array_map('floatval', $row), $c['input']), 'float64');
                $got = \Tessero\Signal\SplineFilter::filter($in, (float) $c['lmbda'], $sfSignal, $sfNd);
                $ga = $got->toList();
                $exp = [];
                foreach ($c['expect'] as $row) { foreach ($row as $v) { $exp[] = (float) $v; } }
                $ok = count($ga) === count($exp);
                if ($ok) {
                    foreach ($exp as $i => $e) {
                        $d = abs($ga[$i] - $e);
                        if ($d > $atol + $rtol * abs($e)) { $ok = false; $msg = sprintf('idx %d got %.17g want %.17g', $i, $ga[$i], $e); break; }
                        $rel = abs($e) > 0 ? $d / abs($e) : $d;
                        if ($rel > $worstRel) { $worstRel = $rel; }
                    }
                } else {
                    $msg = 'length ' . count($ga) . ' != ' . count($exp);
                }
            } catch (\Throwable $e) { $msg = $e->getMessage(); }
            $results[$backend][$key] = ($results[$backend][$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            $results['max_rel'][$backend][$key] = max((float) ($results['max_rel'][$backend][$key] ?? 0.0), $worstRel);
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        // fall through: czt_cases/zoomfft_cases live in the same signal_classes.json file (zoomfft ends in continue)
    }

    if (isset($data['zoomfft_cases'])) {                     // scipy.signal.ZoomFFT (pure-PHP Tessero\Signal\ZoomFft over landed zoom_fft)
        foreach ($data['zoomfft_cases'] as $c) {
            $key = 'signal.ZoomFFT';
            $rtol = (float) ($c['rtol'] ?? 1e-12);
            $checked++;
            $ok = false; $msg = '';
            try {
                $zf = new \Tessero\Signal\ZoomFft((int) $c['n'], $c['fn'], $c['m'], $c['fs'], (bool) $c['endpoint']);
                $ga = $zf->transform(array_map('floatval', $c['x']))->toArray();
                $exp = $c['expect'];
                $ok = count($ga) === count($exp);
                foreach ($exp as $i => $e) {
                    if (! $ok || abs($ga[$i][0] - $e[0]) > $rtol * (1 + abs($e[0]))
                              || abs($ga[$i][1] - $e[1]) > $rtol * (1 + abs($e[1]))) { $ok = false; break; }
                }
                if (! $ok) { $msg = 'did not match scipy.signal.zoom_fft'; }
            } catch (\Throwable $e) { $msg = $e->getMessage(); }
            $results[$backend][$key] = ($results[$backend][$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            $results['max_rel'][$backend][$key] = null;
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        continue;
    }
    if (isset($data['covariance_cases'])) {                  // scipy.stats.Covariance (pure-PHP Tessero\Stats\Covariance)
        $cflat = static function ($a) {                       // flatten nested float/complex array to a flat float list
            $f = []; array_walk_recursive($a, static function ($v) use (&$f) { $f[] = (float) $v; });
            return $f;
        };
        foreach ($data['covariance_cases'] as $c) {
            $key = 'stats.Covariance';
            $rtol = (float) ($c['rtol'] ?? 1e-10);
            $checked++;
            $ok = false; $msg = '';
            try {
                $arg = $c['arg'];
                $cov = match ($c['kind']) {
                    'precision' => \Tessero\Stats\Covariance::fromPrecision($arg['P']),
                    'cholesky'  => \Tessero\Stats\Covariance::fromCholesky($arg['L']),
                    'diagonal'  => \Tessero\Stats\Covariance::fromDiagonal($arg['d']),
                    'eigh'      => \Tessero\Stats\Covariance::fromEigendecomposition([$arg['w'], $arg['v']]),
                    default     => throw new \RuntimeException("covariance kind {$c['kind']}"),
                };
                $pairs = [
                    [$cov->whiten($c['x1']), $c['whiten1']],
                    [$cov->whiten($c['xm']), $c['whitenm']],
                    [$cov->colorize($c['x1']), $c['colorize1']],
                    [$cov->colorize($c['xm']), $c['colorizem']],
                    [[$cov->logPdet()], [$c['log_pdet']]],
                    [$cov->covariance(), $c['cov']],
                ];
                $ok = true;
                foreach ($pairs as $p) {
                    $gf = $cflat($p[0]); $ef = $cflat($p[1]);
                    if (count($gf) !== count($ef)) { $ok = false; break; }
                    foreach ($ef as $i => $e) {
                        if (abs($gf[$i] - $e) > $rtol * (1 + abs($e))) { $ok = false; break 2; }
                    }
                }
                if ($ok && $cov->rank() !== $c['rank']) { $ok = false; $msg = 'rank mismatch'; }
                if (! $ok && $msg === '') { $msg = "did not match scipy.stats.Covariance.{$c['kind']}"; }
            } catch (\Throwable $e) { $msg = $e->getMessage(); }
            $results[$backend][$key] = ($results[$backend][$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            $results['max_rel'][$backend][$key] = null;
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
    }
    if (isset($data['censored_cases'])) {                    // scipy.stats.CensoredData (pure-PHP Tessero\Stats\CensoredData)
        foreach ($data['censored_cases'] as $c) {
            $key = 'stats.CensoredData';
            $checked++;
            $ok = false; $msg = '';
            try {
                $arg = $c['arg'];
                $decIv = static function ($iv) {              // decode "inf"/"-inf" sentinels in interval rows
                    if ($iv === null) { return null; }
                    return array_map(static function ($row) {
                        return array_map(static function ($v) {
                            return $v === 'inf' ? INF : ($v === '-inf' ? -INF : (float) $v);
                        }, $row);
                    }, $iv);
                };
                $cd = match ($c['ctor']) {
                    'ctor' => new \Tessero\Stats\CensoredData(
                        $arg['uncensored'] ?? null, $arg['left'] ?? null, $arg['right'] ?? null,
                        $decIv($arg['interval'] ?? null)),
                    'right_censored'    => \Tessero\Stats\CensoredData::rightCensored($arg['x'], $arg['censored']),
                    'left_censored'     => \Tessero\Stats\CensoredData::leftCensored($arg['x'], $arg['censored']),
                    'interval_censored' => \Tessero\Stats\CensoredData::intervalCensored($arg['low'], $arg['high']),
                    default             => throw new \RuntimeException("censored ctor {$c['ctor']}"),
                };
                $ok = $cd->uncensored() === array_map('floatval', $c['uncensored'])
                    && $cd->left() === array_map('floatval', $c['left'])
                    && $cd->right() === array_map('floatval', $c['right'])
                    && $cd->interval() === array_map(static fn ($r) => array_map('floatval', $r), $c['interval'])
                    && $cd->len() === $c['len']
                    && $cd->numCensored() === $c['num_censored'];
                if (! $ok) { $msg = "did not match scipy.stats.CensoredData ({$c['ctor']})"; }
            } catch (\Throwable $e) { $msg = $e->getMessage(); }
            $results[$backend][$key] = ($results[$backend][$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            $results['max_rel'][$backend][$key] = null;
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        continue;
    }
    if (isset($data['class_cases'])) {                       // deterministic exception/config classes (construction + attributes)
        $local = [];
        foreach ($data['class_cases'] as $c) {
            $key = "{$c['module']}.{$c['name']}";
            $checked++;
            $ok = false; $msg = '';
            try {
                if ($c['name'] === 'NoConvergence') {
                    $thrown = false;
                    try { throw new \Tessero\Optimize\NoConvergence((string) $c['ctor'][0]); }
                    catch (\Exception $e) { $thrown = ($e->getMessage() === $c['message']); }
                    $ok = $thrown && ($c['is_exception'] === true);
                } elseif ($c['name'] === 'QhullError') {
                    $q = new \Tessero\Spatial\QhullError((string) $c['ctor'][0]);
                    $ok = ($q instanceof \RuntimeException) === ($c['is_runtime'] === true)
                        && $q->getMessage() === $c['message'];
                } elseif ($c['name'] === 'BootstrapMethod') {
                    $o = new \Tessero\Stats\BootstrapMethod();
                    $f = $c['fields'];
                    $ok = $o->n_resamples === $f['n_resamples'] && $o->batch === $f['batch']
                        && $o->rng === $f['rng'] && $o->method === $f['method'];
                } elseif ($c['name'] === 'MonteCarloMethod') {
                    $o = new \Tessero\Stats\MonteCarloMethod();
                    $f = $c['fields'];
                    $ok = $o->n_resamples === $f['n_resamples'] && $o->batch === $f['batch']
                        && $o->rvs === $f['rvs'] && $o->rng === $f['rng'];
                } elseif ($c['name'] === 'PermutationMethod') {
                    $o = new \Tessero\Stats\PermutationMethod();
                    $f = $c['fields'];
                    $ok = $o->n_resamples === $f['n_resamples'] && $o->batch === $f['batch']
                        && $o->rng === $f['rng'];
                } else {
                    throw new \RuntimeException("unknown class case {$c['name']}");
                }
                if (! $ok) { $msg = 'construction/attribute surface did not match scipy'; }
            } catch (\Throwable $e) {
                $msg = $e->getMessage();
            }
            $local[$key] = ($local[$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        foreach ($local as $k => $s) { $results[$backend][$k] = $s; $results['max_rel'][$backend][$k] = null; }
        continue;
    }
    // ===================================================================================
    // scipy.signal LTI system classes + ShortTimeFFT  (pure-PHP, both backends)
    //   lti/dlti factories, StateSpace/TransferFunction/ZerosPolesGain, ShortTimeFFT.
    //   State-space is non-unique, so ss equality is tested via the impulse/step
    //   responses (invariants) and the tf/zpk conversions, never raw A/B/C/D.
    //   Poles/zeros are compared as sorted complex multisets.
    // Insert EARLY in the foreach($files ...) loop (alongside the other *_cases arms).
    // ===================================================================================
    if (isset($data['lti_cases']) || isset($data['dlti_cases']) || isset($data['stft_cases'])) {
        // sorted-complex-multiset comparison (poles/zeros order is implementation-defined)
        $cmpSet = static function ($got, $exp, float $rtol, float $atol): bool {
            $norm = static function ($arr): array {
                $o = [];
                foreach ((array) $arr as $v) {
                    $o[] = is_array($v) ? [(float) $v[0], (float) ($v[1] ?? 0.0)] : [(float) $v, 0.0];
                }
                usort($o, static fn ($a, $b) => ($a[0] <=> $b[0]) ?: ($a[1] <=> $b[1]));
                return $o;
            };
            $g = $norm($got); $e = $norm($exp);
            if (count($g) !== count($e)) { return false; }
            foreach ($e as $i => $ev) {
                foreach ([0, 1] as $j) {
                    if (abs($g[$i][$j] - $ev[$j]) > $atol + $rtol * abs($ev[$j])) { return false; }
                }
            }
            return true;
        };
        // flat (real or [re,im]) element-wise comparison
        $cmpFlat = static function ($got, $exp, float $rtol, float $atol): bool {
            $flat = static function ($arr): array {
                $o = [];
                foreach ((array) $arr as $v) {
                    if (is_array($v)) { $o[] = (float) $v[0]; $o[] = (float) ($v[1] ?? 0.0); }
                    else { $o[] = (float) $v; }
                }
                return $o;
            };
            $g = $flat($got); $e = $flat($exp);
            if (count($g) !== count($e)) { return false; }
            foreach ($e as $i => $ev) {
                if (abs($g[$i] - $ev) > $atol + $rtol * abs($ev)) { return false; }
            }
            return true;
        };
        $mark = static function (string $key, bool $ok, string $msg) use (&$results, $backend, &$failures) {
            $results[$backend][$key] = ($results[$backend][$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            $results['max_rel'][$backend][$key] = null;
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        };

        foreach (($data['lti_cases'] ?? []) as $c) {
            $checked++;
            $ok = true; $msg = '';
            // the representation class exercised for this case gets credited too
            $reprKey = ['tf' => 'signal.TransferFunction', 'zpk' => 'signal.ZerosPolesGain', 'ss' => 'signal.StateSpace'][$c['kind']];
            try {
                $s = \Tessero\Signal\Lti::create(...$c['args']);
                $tf = $s->toTf();
                $ok = $ok && $cmpFlat($tf->num, $c['tf_num'], 1e-7, 1e-9);
                $ok = $ok && $cmpFlat($tf->den, $c['tf_den'], 1e-7, 1e-9);
                $zpk = $s->toZpk();
                $ok = $ok && $cmpSet($zpk->z, $c['zpk_z'], 1e-6, 1e-8);
                $ok = $ok && $cmpSet($zpk->p, $c['zpk_p'], 1e-6, 1e-8);
                $ok = $ok && abs($zpk->k - (float) $c['zpk_k']) <= 1e-9 + 1e-7 * abs((float) $c['zpk_k']);
                $ok = $ok && $cmpSet($s->poles(), $c['poles'], 1e-6, 1e-8);
                $ok = $ok && $cmpSet($s->zeros(), $c['zeros'], 1e-6, 1e-8);
                $imp = $s->impulse($c['T']);
                $ok = $ok && $cmpFlat($imp['yout'], $c['impulse'], 1e-6, 1e-8);
                $stp = $s->step($c['T']);
                $ok = $ok && $cmpFlat($stp['yout'], $c['step'], 1e-6, 1e-8);
                $bd = $s->bode($c['w']);
                $ok = $ok && $cmpFlat($bd['mag'], $c['mag'], 1e-6, 1e-8);
                $ok = $ok && $cmpFlat($bd['phase'], $c['phase'], 1e-6, 1e-8);
                if (! $ok) { $msg = 'did not match scipy'; }
            } catch (\Throwable $e) {
                $ok = false; $msg = $e->getMessage();
            }
            $mark('signal.lti', $ok, $msg);
            $mark($reprKey, $ok, $msg);
        }

        foreach (($data['dlti_cases'] ?? []) as $c) {
            $checked++;
            $ok = true; $msg = '';
            try {
                $d = \Tessero\Signal\Dlti::create($c['args'], (float) $c['dt']);
                $ok = $ok && $cmpSet($d->poles(), $c['poles'], 1e-6, 1e-8);
                $ok = $ok && $cmpSet($d->zeros(), $c['zeros'], 1e-6, 1e-8);
                $di = $d->dimpulse((int) $c['n']);
                $ok = $ok && $cmpFlat($di['yout'], $c['dimpulse'], 1e-6, 1e-8);
                $ds = $d->dstep((int) $c['n']);
                $ok = $ok && $cmpFlat($ds['yout'], $c['dstep'], 1e-6, 1e-8);
                if (! $ok) { $msg = 'did not match scipy'; }
            } catch (\Throwable $e) {
                $ok = false; $msg = $e->getMessage();
            }
            $mark('signal.dlti', $ok, $msg);
        }

        foreach (($data['stft_cases'] ?? []) as $c) {
            $checked++;
            $ok = true; $msg = '';
            try {
                $S = new \Tessero\Signal\ShortTimeFFT(
                    $c['win'], (int) $c['hop'], (float) $c['fs'],
                    $c['mfft'] !== null ? (int) $c['mfft'] : null, (string) $c['fft_mode']
                );
                $ok = $ok && ($S->fPts() === (int) $c['f_pts']);
                $ok = $ok && ($S->pMin() === (int) $c['p_min']);
                $ok = $ok && ($S->pMax(count($c['x'])) === (int) $c['p_max']);
                $ok = $ok && abs($S->deltaT() - (float) $c['delta_t']) <= 1e-11 + 1e-9 * abs((float) $c['delta_t']);
                $ok = $ok && abs($S->deltaF() - (float) $c['delta_f']) <= 1e-11 + 1e-9 * abs((float) $c['delta_f']);
                $ok = $ok && $cmpFlat($S->dualWin(), $c['dual_win'], 1e-9, 1e-11);
                $ok = $ok && $cmpFlat($S->f(), $c['f'], 1e-9, 1e-11);
                $Sx = $S->stft($c['x']);
                $gotSx = []; foreach ($Sx as $row) { foreach ($row as $v) { $gotSx[] = $v; } }
                $expSx = []; foreach ($c['Sx'] as $row) { foreach ($row as $v) { $expSx[] = $v; } }
                $ok = $ok && $cmpFlat($gotSx, $expSx, 1e-8, 1e-10);
                $xr = $S->istft($Sx, 0, count($c['x']));
                $ok = $ok && $cmpFlat($xr, $c['istft'], 1e-7, 1e-9);
                $Px = $S->spectrogram($c['x']);
                $gotPx = []; foreach ($Px as $row) { foreach ($row as $v) { $gotPx[] = $v; } }
                $expPx = []; foreach ($c['spectrogram'] as $row) { foreach ($row as $v) { $expPx[] = $v; } }
                $ok = $ok && $cmpFlat($gotPx, $expPx, 1e-8, 1e-10);
                if (! $ok) { $msg = 'did not match scipy'; }
            } catch (\Throwable $e) {
                $ok = false; $msg = $e->getMessage();
            }
            $mark('signal.ShortTimeFFT', $ok, $msg);
        }
        continue;
    }

    if (isset($data['findpeakscwt_cases'])) {               // scipy.signal.find_peaks_cwt (pure-PHP Tessero\Signal\FindPeaksCwt)
        foreach ($data['findpeakscwt_cases'] as $c) {
            $key = 'signal.find_peaks_cwt';
            $checked++;
            $ok = false; $msg = '';
            try {
                $got = \Tessero\Signal\FindPeaksCwt::find(
                    array_map('floatval', $c['vector']),
                    array_map('floatval', $c['widths']),
                    null,
                    null,
                    null,
                    (float) ($c['min_snr'] ?? 1.0),
                    (float) ($c['noise_perc'] ?? 10.0),
                    null,
                );
                $exp = array_map('intval', $c['expect']);
                $ok = $got === $exp;
                if (! $ok) { $msg = 'did not match scipy: got ' . json_encode($got) . ' expect ' . json_encode($exp); }
            } catch (\Throwable $e) {
                $msg = $e->getMessage();
            }
            $results[$backend][$key] = ($results[$backend][$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            $results['max_rel'][$backend][$key] = null;
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        continue;
    }
    if (isset($data['placepoles_cases'])) {                 // scipy.signal.place_poles (pure-PHP Tessero\Signal\PlacePoles, single-input)
        foreach ($data['placepoles_cases'] as $c) {
            $key = 'signal.place_poles';
            $rtol = (float) ($c['rtol'] ?? 1e-6);
            $checked++;
            $ok = false; $msg = '';
            try {
                $poles = array_map(static fn($p) => [(float) $p[0], (float) $p[1]], $c['poles']);
                $got = \Tessero\Signal\PlacePoles::place($c['A'], $c['B'], $poles, (string) ($c['method'] ?? 'YT'));
                $K = $got['gain_matrix'][0];
                $exp = $c['expect']['gain_matrix'][0];
                $ok = count($K) === count($exp);
                foreach ($exp as $j => $e) {
                    if (! $ok || abs($K[$j] - (float) $e) > $rtol * (1 + abs((float) $e))) { $ok = false; break; }
                }
                if (! $ok) { $msg = 'did not match scipy'; }
            } catch (\Throwable $e) {
                $msg = $e->getMessage();
            }
            $results[$backend][$key] = ($results[$backend][$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            $results['max_rel'][$backend][$key] = null;
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        continue;
    }
    if (isset($data['ppccplot_cases'])) {                   // scipy.stats.ppcc_plot (pure-PHP Tessero\StatsFns::ppccPlot)
        foreach ($data['ppccplot_cases'] as $c) {
            $key = 'stats.ppcc_plot';
            $rtol = (float) ($c['rtol'] ?? 1e-9);
            $checked++;
            $ok = false; $msg = '';
            try {
                [$svals, $ppcc] = \Tessero\StatsFns::ppccPlot(
                    array_map('floatval', $c['x']),
                    (float) $c['a'],
                    (float) $c['b'],
                    (int) $c['n'],
                );
                $ok = true;
                foreach (['svals' => $svals, 'ppcc' => $ppcc] as $name => $got) {
                    foreach ($c['expect'][$name] as $i => $e) {
                        if (abs($got[$i] - (float) $e) > $rtol * (1 + abs((float) $e))) { $ok = false; $msg = "{$name}[{$i}]"; break 2; }
                    }
                }
            } catch (\Throwable $e) {
                $msg = $e->getMessage();
            }
            $results[$backend][$key] = ($results[$backend][$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            $results['max_rel'][$backend][$key] = null;
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        continue;
    }
    if (isset($data['solver_cases'])) {                      // scipy.optimize / scipy.integrate: callable objectives
        foreach (runSolverCases($data['solver_cases'], $module, $checked, $failures) as $k => $s) {
            $results[$backend][$k] = $s;
            $results['max_rel'][$backend][$k] = null;
        }
        if (isset($data['nkclass_cases'])) {               // optimize.json ALSO carries Jacobian-helper classes; process before continue
            foreach (runNkClassCases($data['nkclass_cases'], $module, $checked, $failures) as $k => $s) {
                $results[$backend][$k] = $s;
                $results['max_rel'][$backend][$k] = null;
            }
        }
        continue;
    }
    if (isset($data['nkclass_cases'])) {               // scipy.optimize Jacobian-helper classes
        foreach (runNkClassCases($data['nkclass_cases'], $module, $checked, $failures) as $k => $s) {
            $results[$backend][$k] = $s;
            $results['max_rel'][$backend][$k] = null;
        }
        continue;
    }
    if (isset($data['labcomp_cases'])) {                     // scipy.ndimage.labeled_comprehension (pure-PHP Tessero\LabeledComprehension; named reducer over gathered group values)
        $lcReducers = [
            'mean'   => static fn (array $v): float => array_sum($v) / count($v),
            'max'    => static fn (array $v): float => (float) max($v),
            'min'    => static fn (array $v): float => (float) min($v),
            'sum'    => static fn (array $v): float => (float) array_sum($v),
            'ptp'    => static fn (array $v): float => (float) (max($v) - min($v)),
            'median' => static function (array $v): float {
                sort($v); $n = count($v); $m = intdiv($n, 2);
                return $n % 2 ? (float) $v[$m] : ((float) $v[$m - 1] + (float) $v[$m]) / 2.0;
            },
            'posmin' => static fn (array $vals, array $pos): float => (float) min($pos),  // pass_positions=true
        ];
        $cmpNestedLC = static function ($want, $got, float $rtol, float $atol, float &$worst) use (&$cmpNestedLC): ?string {
            if (is_array($want)) {
                if (! is_array($got) || count($got) !== count($want)) { return 'shape/length mismatch'; }
                foreach ($want as $i => $w) { $p = $cmpNestedLC($w, $got[$i], $rtol, $atol, $worst); if ($p !== null) { return "[{$i}] {$p}"; } }
                return null;
            }
            [$ok, $rel] = close((float) $got, (float) $want, $rtol, $atol);
            if ($rel !== INF && $rel > $worst) { $worst = $rel; }
            return $ok ? null : sprintf('got %.17g want %.17g', (float) $got, (float) $want);
        };
        foreach ($data['labcomp_cases'] as $c) {
            $key = 'ndimage.labeled_comprehension';
            $checked++;
            $w = 0.0;
            try {
                $fn = $lcReducers[$c['reducer']] ?? null;
                if ($fn === null) { throw new \RuntimeException("unknown reducer '{$c['reducer']}'"); }
                $default = $c['default'] === null ? null : (float) $c['default'];
                $got = \Tessero\LabeledComprehension::labeledComprehension(
                    $c['input'], $c['labels'], $c['index'], $fn, $default, (bool) $c['pass_positions'],
                );
                $p = $cmpNestedLC($c['expect'], $got, 1e-12, 0.0, $w);
            } catch (\Throwable $e) {
                $p = 'threw ' . $e->getMessage();
            }
            $results[$backend][$key] = ($results[$backend][$key] ?? 'pass') === 'fail' ? 'fail' : ($p === null ? 'pass' : 'fail');
            $results['max_rel'][$backend][$key] = null;
            if ($p !== null) { $failures++; echo "FAIL {$key}: {$p}\n"; }
        }
        continue;
    }
    if (isset($data['vecfilter_cases'])) {                   // scipy.ndimage.vectorized_filter (pure-PHP Tessero\VectorizedFilter over NdimageGeneric; named axis-reducer callable(window, axis))
        $vfReducers = [
            'mean'   => static fn (array $wn, $ax): float => array_sum($wn) / count($wn),
            'max'    => static fn (array $wn, $ax): float => (float) max($wn),
            'min'    => static fn (array $wn, $ax): float => (float) min($wn),
            'sum'    => static fn (array $wn, $ax): float => (float) array_sum($wn),
            'ptp'    => static fn (array $wn, $ax): float => (float) (max($wn) - min($wn)),
            'median' => static function (array $wn, $ax): float {
                sort($wn); $n = count($wn); $m = intdiv($n, 2);
                return $n % 2 ? (float) $wn[$m] : ((float) $wn[$m - 1] + (float) $wn[$m]) / 2.0;
            },
        ];
        $cmpNestedVF = static function ($want, $got, float $rtol, float $atol, float &$worst) use (&$cmpNestedVF): ?string {
            if (is_array($want)) {
                if (! is_array($got) || count($got) !== count($want)) { return 'shape/length mismatch'; }
                foreach ($want as $i => $w) { $p = $cmpNestedVF($w, $got[$i], $rtol, $atol, $worst); if ($p !== null) { return "[{$i}] {$p}"; } }
                return null;
            }
            [$ok, $rel] = close((float) $got, (float) $want, $rtol, $atol);
            if ($rel !== INF && $rel > $worst) { $worst = $rel; }
            return $ok ? null : sprintf('got %.17g want %.17g', (float) $got, (float) $want);
        };
        foreach ($data['vecfilter_cases'] as $c) {
            $key = 'ndimage.vectorized_filter';
            $checked++;
            $w = 0.0;
            try {
                $fn = $vfReducers[$c['reducer']] ?? null;
                if ($fn === null) { throw new \RuntimeException("unknown reducer '{$c['reducer']}'"); }
                $got = \Tessero\VectorizedFilter::vectorizedFilter(
                    $c['input'], $fn, $c['size'], $c['footprint'],
                    $c['mode'], (float) $c['cval'], $c['origin'],
                );
                $p = $cmpNestedVF($c['expect'], $got, 1e-12, 0.0, $w);
            } catch (\Throwable $e) {
                $p = 'threw ' . $e->getMessage();
            }
            $results[$backend][$key] = ($results[$backend][$key] ?? 'pass') === 'fail' ? 'fail' : ($p === null ? 'pass' : 'fail');
            $results['max_rel'][$backend][$key] = null;
            if ($p !== null) { $failures++; echo "FAIL {$key}: {$p}\n"; }
        }
        continue;
    }
    if (isset($data['statsmvs_cases'])) {                    // scipy.stats bayes_mvs / mvsdist (pure-PHP Tessero\StatsFns)
        $dec = static fn ($v) => $v === 'inf' ? INF : ($v === '-inf' ? -INF : ($v === 'nan' ? NAN : (float) $v));
        $ap = static function ($a, $b, $rtol = 1e-12) {
            if (is_infinite($a) && is_infinite($b)) return ($a > 0) === ($b > 0);
            if (is_nan($a) && is_nan($b)) return true;
            if (is_infinite($a) || is_infinite($b) || is_nan($a) || is_nan($b)) return false;
            return abs($a - $b) <= $rtol * (1 + abs($b));
