            'mean'   => static fn (array $w): float => array_sum($w) / count($w),
            'max'    => static fn (array $w): float => (float) max($w),
            'min'    => static fn (array $w): float => (float) min($w),
            'sum'    => static fn (array $w): float => (float) array_sum($w),
