        $decodeNan = static fn ($v): float => (is_string($v) && strtolower($v) === 'nan') ? NAN : (float) $v;
        foreach ($data['cloughtocher_cases'] as $c) {
            $key = 'interpolate.CloughTocher2DInterpolator';
            $checked++;
            $ok = true; $msg = '';
            try {
                $interp = new \Tessero\Interpolate\CloughTocher2DInterpolator($c['points'], $c['values']);
                $got = flattenNums($interp->query($c['query']));
                $exp = flattenNums($c['expect']);
                if (count($got) !== count($exp)) {
                    $ok = false; $msg = 'length mismatch';
                } else {
                    foreach ($exp as $i => $ev) {
                        $e = $decodeNan($ev); $g = (float) $got[$i];
                        if (is_nan($e) || is_nan($g)) {
                            if (is_nan($e) !== is_nan($g)) { $ok = false; $msg = 'NaN-outside-hull mismatch'; break; }
                        } elseif (abs($g - $e) > 1e-9 * (1 + abs($e))) {
                            $ok = false; $msg = 'values did not match scipy'; break;
                        }
                    }
                }
            } catch (\Throwable $ex) {
                $ok = false; $msg = $ex->getMessage();
            }
            $local[$key] = ($local[$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        foreach ($local as $k => $s) { $results[$backend][$k] = $s; $results['max_rel'][$backend][$k] = null; }
        continue;
    }


    if (isset($data['aaa_cases'])) {                         // scipy.interpolate.AAA (pure-PHP greedy barycentric rational approximation over Linalg::svd)
        $local = [];
        foreach ($data['aaa_cases'] as $c) {
            $key = 'interpolate.AAA';
            $checked++;
            $ok = true; $msg = '';
            try {
                $a = new \Tessero\Interpolate\AAA($c['x'], $c['y']);
                if (isset($c['nsupport']) && count($a->supportPoints) !== (int) $c['nsupport']) {
                    $ok = false; $msg = 'support-point count did not match scipy (' . count($a->supportPoints) . ' vs ' . (int) $c['nsupport'] . ')';
                } else {
                    $got = flattenNums($a->query($c['query']));
                    $exp = flattenNums($c['expect']);
                    if (count($got) !== count($exp)) {
                        $ok = false; $msg = 'length mismatch';
                    } else {
                        foreach ($exp as $i => $ev) {
                            $e = (float) $ev; $g = (float) $got[$i];
                            if (abs($g - $e) > 1e-9 * (1 + abs($e))) {
                                $ok = false; $msg = 'values did not match scipy'; break;
                            }
                        }
                    }
                }
            } catch (\Throwable $ex) {
                $ok = false; $msg = $ex->getMessage();
            }
            $local[$key] = ($local[$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        foreach ($local as $k => $s) { $results[$backend][$k] = $s; $results['max_rel'][$backend][$k] = null; }
        continue;
    }
    if (isset($data['statfn2_cases'])) {                     // scipy.stats 2x2-table exact tests (pure-PHP Tessero\StatsBarnard)
        foreach ($data['statfn2_cases'] as $c) {
            $fn = $c['fn'];
            $key = "stats.{$fn}";
            $rtol = (float) ($c['rtol'] ?? 1e-7);
            $checked++;
            $ok = false; $msg = '';
            try {
                $got = match ($fn) {
                    'barnard_exact' => \Tessero\StatsBarnard::barnardExact($c['table'], $c['alternative'] ?? 'two-sided', (bool) ($c['pooled'] ?? true), (int) ($c['n'] ?? 32)),
                };
                $expStat = $c['expect']['statistic'];
                $expStat = $expStat === null ? NAN : (float) $expStat;
                $expP = (float) $c['expect']['pvalue'];
                $okStat = (is_nan($expStat) && is_nan($got['statistic'])) || abs($got['statistic'] - $expStat) <= $rtol * (1 + abs($expStat));
                $okP = abs($got['pvalue'] - $expP) <= $rtol * (1 + abs($expP));
                $ok = $okStat && $okP;
                if (! $ok) { $msg = 'did not match scipy'; }
            } catch (\Throwable $e) {
                $msg = $e->getMessage();
            }
            $results[$backend][$key] = ($results[$backend][$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            $results['max_rel'][$backend][$key] = null;
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        continue;
    }
    if (isset($data['boschloo_cases'])) {                    // scipy.stats.boschloo_exact (pure-PHP Tessero\Boschloo)
        foreach ($data['boschloo_cases'] as $c) {
            $key = 'stats.boschloo_exact';
            $rtol = (float) ($c['rtol'] ?? 1e-9);
            $atol = (float) ($c['atol'] ?? 1e-11);
            $checked++;
            $ok = false; $msg = '';
            try {
                $got = \Tessero\Boschloo::boschlooExact($c['table'], $c['alternative'] ?? 'two-sided', (int) ($c['n'] ?? 32));
                $cmp = static function ($exp, float $val) use ($rtol, $atol): bool {
                    if ($exp === 'nan' || (is_float($exp) && is_nan($exp))) { return is_nan($val); }
                    $e = (float) $exp;
                    return abs($val - $e) <= $atol + $rtol * abs($e);
                };
                $ok = $cmp($c['expect']['statistic'], (float) $got['statistic']) && $cmp($c['expect']['pvalue'], (float) $got['pvalue']);
                if (! $ok) { $msg = 'did not match scipy'; }
            } catch (\Throwable $e) {
                $msg = $e->getMessage();
            }
            $results[$backend][$key] = ($results[$backend][$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            $results['max_rel'][$backend][$key] = null;
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        continue;
    }
    if (isset($data['logrank_cases'])) {                    // scipy.stats.logrank (pure-PHP Tessero\LogRank)
        foreach ($data['logrank_cases'] as $c) {
            $key = 'stats.logrank';
            $rtol = (float) ($c['rtol'] ?? 1e-9);
            $checked++;
            $ok = false; $msg = '';
            try {
                $got = \Tessero\LogRank::logrank(
                    array_map('floatval', $c['x_uncensored']),
                    array_map('floatval', $c['x_right']),
                    array_map('floatval', $c['y_uncensored']),
                    array_map('floatval', $c['y_right']),
                    (string) ($c['alternative'] ?? 'two-sided')
                );
                $es = abs($got['statistic'] - (float) $c['expect']['statistic']);
                $ep = abs($got['pvalue'] - (float) $c['expect']['pvalue']);
                $ok = $es <= $rtol * (1 + abs((float) $c['expect']['statistic'])) && $ep <= $rtol * (1 + abs((float) $c['expect']['pvalue']));
                if (! $ok) { $msg = 'did not match scipy'; }
            } catch (\Throwable $e) {
                $msg = $e->getMessage();
            }
            $results[$backend][$key] = ($results[$backend][$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            $results['max_rel'][$backend][$key] = null;
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        continue;
    }
    if (isset($data['statsfn_cases'])) {                     // scipy.stats optimiser-based helpers (pure-PHP Tessero\StatsFns)
        foreach ($data['statsfn_cases'] as $c) {
            $fn = $c['fn'];
            $key = "stats.{$fn}";
            $x = array_map('floatval', $c['x']);
            $rtol = (float) ($c['rtol'] ?? 1e-5);
            $checked++;
            $ok = false; $msg = '';
            try {
                $got = match ($fn) {
                    'boxcox_normmax' => \Tessero\StatsFns::boxcoxNormmax($x, $c['method'] ?? 'pearsonr'),
                    'yeojohnson_normmax' => \Tessero\StatsFns::yeojohnsonNormmax($x),
                    'ppcc_max' => \Tessero\StatsFns::ppccMax($x),
                };
                $ok = abs($got - $c['expect']) <= $rtol * (1 + abs((float) $c['expect']));
                if (! $ok) { $msg = 'did not match scipy'; }
            } catch (\Throwable $e) {
                $msg = $e->getMessage();
            }
            $results[$backend][$key] = ($results[$backend][$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            $results['max_rel'][$backend][$key] = null;
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        continue;
    }
    if (isset($data['specseq_cases'])) {                     // scipy.special sequence/derivative families (pure-PHP Tessero\SpecialSeq)
        foreach ($data['specseq_cases'] as $c) {
            $fn = $c['fn'];
            $key = "special.{$fn}";
            $a = $c['args'];
            $rtol = (float) ($c['rtol'] ?? 1e-8);
            $checked++;
            $ok = false; $msg = '';
            try {
                $r = match ($fn) {
                    'legendre_p' => \Tessero\SpecialSeq::legendreP((int) $a[0], (float) $a[1], (int) ($a[2] ?? 0)),
                    'legendre_p_all' => \Tessero\SpecialSeq::legendrePAll((int) $a[0], (float) $a[1], (int) ($a[2] ?? 0)),
                    'lqn' => \Tessero\SpecialSeq::lqn((int) $a[0], (float) $a[1]),
                    'riccati_jn' => \Tessero\SpecialSeq::riccatiJn((int) $a[0], (float) $a[1]),
                    'riccati_yn' => \Tessero\SpecialSeq::riccatiYn((int) $a[0], (float) $a[1]),
                    'assoc_legendre_p' => \Tessero\SpecialSeq::assocLegendreP((int) $a[0], (int) $a[1], (float) $a[2], (int) ($a[3] ?? 0), (bool) ($a[4] ?? false)),
                    'assoc_legendre_p_all' => \Tessero\SpecialSeq::assocLegendrePAll((int) $a[0], (int) $a[1], (float) $a[2], (int) ($a[3] ?? 0), (bool) ($a[4] ?? false)),
                    'sph_legendre_p' => \Tessero\SpecialSeq::sphLegendreP((int) $a[0], (int) $a[1], (float) $a[2], (int) ($a[3] ?? 0)),
                    'sph_legendre_p_all' => \Tessero\SpecialSeq::sphLegendrePAll((int) $a[0], (int) $a[1], (float) $a[2], (int) ($a[3] ?? 0)),
                    'sph_harm_y_all' => \Tessero\SpecialSeq::sphHarmYAll((int) $a[0], (int) $a[1], (float) $a[2], (float) $a[3]),
                    'lqmn' => \Tessero\SpecialSeq::lqmn((int) $a[0], (int) $a[1], (float) $a[2]),
                    'stirling2' => \Tessero\SpecialSeq::stirling2((int) $a[0], (int) $a[1]),
                };
                $ok = vecClose(flattenNums($r), array_map('floatval', $c['expect']), $rtol);
                if (! $ok) { $msg = 'did not match scipy'; }
            } catch (\Throwable $e) {
                $msg = $e->getMessage();
            }
            $results[$backend][$key] = ($results[$backend][$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            $results['max_rel'][$backend][$key] = null;
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        continue;
    }
    if (isset($data['orthopoly_cases'])) {                   // scipy.special polynomial factories -> OrthoPoly1d callables
        foreach ($data['orthopoly_cases'] as $c) {
            $fn = $c['fn'];
            $key = "special.{$fn}";
            $a = $c['args'];
            $rtol = (float) ($c['rtol'] ?? 1e-9);
            $checked++;
            $ok = false; $msg = '';
            try {
                $p = match ($fn) {
                    'legendre' => \Tessero\OrthoPoly::legendre((int) $a[0]),
                    'chebyt' => \Tessero\OrthoPoly::chebyt((int) $a[0]),
                    'chebyu' => \Tessero\OrthoPoly::chebyu((int) $a[0]),
                    'chebyc' => \Tessero\OrthoPoly::chebyc((int) $a[0]),
                    'chebys' => \Tessero\OrthoPoly::chebys((int) $a[0]),
                    'hermite' => \Tessero\OrthoPoly::hermite((int) $a[0]),
                    'hermitenorm' => \Tessero\OrthoPoly::hermitenorm((int) $a[0]),
                    'laguerre' => \Tessero\OrthoPoly::laguerre((int) $a[0]),
                    'genlaguerre' => \Tessero\OrthoPoly::genlaguerre((int) $a[0], (float) $a[1]),
                    'gegenbauer' => \Tessero\OrthoPoly::gegenbauer((int) $a[0], (float) $a[1]),
                    'jacobi' => \Tessero\OrthoPoly::jacobi((int) $a[0], (float) $a[1], (float) $a[2]),
                    'sh_legendre' => \Tessero\OrthoPoly::shLegendre((int) $a[0]),
                    'sh_chebyt' => \Tessero\OrthoPoly::shChebyt((int) $a[0]),
                    'sh_chebyu' => \Tessero\OrthoPoly::shChebyu((int) $a[0]),
                    'sh_jacobi' => \Tessero\OrthoPoly::shJacobi((int) $a[0], (float) $a[1], (float) $a[2]),
                };
                $ok = vecClose($p->c, array_map('floatval', $c['c']), $rtol)
                    && vecClose($p($c['xs']), array_map('floatval', $c['ys']), $rtol);
                if (! $ok) { $msg = 'coefficients or evaluation did not match scipy'; }
            } catch (\Throwable $e) {
                $msg = $e->getMessage();
            }
            $results[$backend][$key] = ($results[$backend][$key] ?? 'pass') === 'fail' ? 'fail' : ($ok ? 'pass' : 'fail');
            $results['max_rel'][$backend][$key] = null;
            if (! $ok) { $failures++; echo "FAIL {$key}: {$msg}\n"; }
        }
        continue;
    }
    if ($module === 'constants') {                           // scipy.constants: scalar constants + helper functions
        $allok = true;
        foreach ($data['values'] as $name => $v) {
            $checked++;
            $got = (float) constant("Tessero\\Constants::{$name}");
            if (abs($got - (float) $v) > 1e-12 * (1 + abs((float) $v))) { $allok = false; $failures++; echo "FAIL constants.{$name}: {$got} vs {$v}\n"; }
        }
        $results[$backend]['constants.values'] = $allok ? 'pass' : 'fail';
        $results['max_rel'][$backend]['constants.values'] = null;
        $helpers = [
            'convert_temperature' => static fn (array $c): float => \Tessero\Constants::convertTemperature((float) $c['val'], (string) $c['old'], (string) $c['new']),
            'lambda2nu' => static fn (array $c): float => \Tessero\Constants::lambda2nu((float) $c['x']),
            'nu2lambda' => static fn (array $c): float => \Tessero\Constants::nu2lambda((float) $c['x']),
        ];
        foreach ($helpers as $hn => $call) {
            $hok = true;
            foreach ($data[$hn] ?? [] as $c) {
                $checked++;
                if (abs($call($c) - (float) $c['expect']) > 1e-9 * (1 + abs((float) $c['expect']))) { $hok = false; $failures++; echo "FAIL constants.{$hn}\n"; }
            }
            $results[$backend]["constants.{$hn}"] = $hok ? 'pass' : 'fail';
            $results['max_rel'][$backend]["constants.{$hn}"] = null;
        }
        foreach (['value', 'precision'] as $fn) {            // float-valued CODATA lookups
            $ok = true;
            foreach ($data[$fn] ?? [] as $c) {
                $checked++;
                $got = (float) \Tessero\Constants::$fn($c['key']);
                if (abs($got - (float) $c['expect']) > 1e-12 * (1 + abs((float) $c['expect']))) { $ok = false; $failures++; echo "FAIL constants.{$fn}: {$c['key']}\n"; }
            }
            $results[$backend]["constants.{$fn}"] = $ok ? 'pass' : 'fail';
            $results['max_rel'][$backend]["constants.{$fn}"] = null;
        }
        $uok = true;
        foreach ($data['unit'] ?? [] as $c) {
            $checked++;
            if (\Tessero\Constants::unit($c['key']) !== $c['expect']) { $uok = false; $failures++; echo "FAIL constants.unit: {$c['key']}\n"; }
        }
        $results[$backend]['constants.unit'] = $uok ? 'pass' : 'fail';
        $results['max_rel'][$backend]['constants.unit'] = null;
        $fok = true;
        foreach ($data['find'] ?? [] as $c) {
            $checked++;
            if (\Tessero\Constants::find($c['sub']) !== $c['expect']) { $fok = false; $failures++; echo "FAIL constants.find: {$c['sub']}\n"; }
        }
        $results[$backend]['constants.find'] = $fok ? 'pass' : 'fail';
        $results['max_rel'][$backend]['constants.find'] = null;
        $pcok = count(\Tessero\Constants::physicalConstants()) === ($data['physical_constants_count'] ?? -1);
        $checked++;
        if (! $pcok) { $failures++; echo "FAIL constants.physical_constants: count mismatch\n"; }
        $results[$backend]['constants.physical_constants'] = $pcok ? 'pass' : 'fail';
        $results['max_rel'][$backend]['constants.physical_constants'] = null;
        continue;
    }
    $class = $classes[$backend][$module] ?? null;
    if ($class === null || ! class_exists($class)) {
        fwrite(STDERR, "no {$module} class on the {$backend} backend\n");
        exit(2);
    }
    $status = [];
    $maxRel = [];
    // scipy.stats returns Python ints or floats for scalar results as its internals happen to produce them
    // (support() of a discrete distribution is (0, 5.0)); compare those as numbers
    $GLOBALS['scalarKindLoose'] = ($data['kind'] ?? '') === 'distributions';
    if (isset($data['calls'])) {
        foreach ($data['calls'] as $blk) {
            $fn = $blk['fn'];
            if ($only !== null && ! isset($only[$fn])) {
                continue;
            }
            $key = "{$module}.{$fn}";
            $method = camelName($fn);
            if (! method_exists($class, $method)) {       // not implemented on this backend: reported, not failed
                $status[$key] = 'missing';
                echo "MISSING {$key}: no {$class}::{$method}()\n";
                continue;
            }
            $rtol = (float) ($blk['tol']['rtol'] ?? CALL_RTOL[$fn] ?? ($module === 'random' ? CALL_RTOL['random'] : 1e-12));
            $atol = (float) ($blk['tol']['atol'] ?? CALL_ATOL[$fn] ?? 0.0);
            $problems = [];
            $worst = 0.0;
            foreach ($blk['cases'] as $ci => $case) {
                if (isset($case['dist_args'])) {             // scipy.stats: calls on one frozen distribution
                    $dargs = array_map(static fn ($v) => decodeValue($v, $arrayClass), $case['dist_args']);
                    foreach ($case['dist_kwargs'] as $k => $v) {
                        $dargs[$k] = decodeValue($v, $arrayClass);
                    }
                    try {
                        $dist = $class::$method(...$dargs);
                    } catch (\Throwable $e) {
                        $problems[] = "case {$ci}: constructing threw " . get_class($e) . ': ' . $e->getMessage();
                        continue;
                    }
                    foreach ($case['calls'] as $k => $c) {
                        $checked++;
                        $p = runCall($dist, camelName($c['method']), $c, $arrayClass, $rtol, $atol, $worst);
                        if ($p !== null) {
                            $problems[] = "case {$ci} " . describeCall(['args' => $case['dist_args'], 'kwargs' => $case['dist_kwargs']])
                                . "->{$c['method']}" . describeCall($c) . ": {$p}";
                        }
                    }
                    continue;
                }
                if (isset($case['seed'])) {                   // Generator methods: one generator per seed, calls in order
                    $gen = $class::defaultRng($case['seed']);
                    foreach ($case['calls'] as $k => $c) {
                        $checked++;
                        $p = runCall($gen, camelName($fn), $c, $arrayClass, $rtol, $atol, $worst);
                        if ($p !== null) {
                            $problems[] = "seed {$case['seed']} call {$k} " . describeCall($c) . ": {$p}";
                        }
                    }
                    continue;
                }
                $checked++;
                // a per-call tolerance the generator derived from the call's own data (with its reason in "why")
                $crtol = isset($case['tol']['rtol']) ? max($rtol, (float) $case['tol']['rtol']) : $rtol;
                $p = runCall($class, camelName($fn), $case, $arrayClass, $crtol, $atol, $worst);
                if ($p !== null) {
                    $problems[] = "call {$ci} " . describeCall($case) . ": {$p}";
                }
            }
            $status[$key] = $problems === [] ? 'pass' : 'fail';
            $maxRel[$key] = $worst;
            if ($problems !== []) {
                $failures++;
                echo "FAIL {$key}: " . count($problems) . ' of ' . count($blk['cases']) . " call(s)\n";
                foreach (array_slice($problems, 0, $verbose ? 20 : 3) as $p) {
                    echo "    {$p}\n";
                }
            }
        }
    }
    foreach ($data['blocks'] ?? [] as $blk) {
        $fn = $blk['fn'];
        if ($only !== null && ! isset($only[$fn])) {
            continue;
        }
        $key = "{$module}.{$fn}";
        if (! method_exists($class, camelName($fn))) {
            $status[$key] = 'missing';
            echo "MISSING {$key}: no {$class}::" . camelName($fn) . "()\n";
            continue;
        }
        $status[$key] ??= 'pass';
        $maxRel[$key] ??= 0.0;
        $rtol = (float) ($blk['tol']['rtol'] ?? 1e-13);
        $atol = (float) ($blk['tol']['atol'] ?? 0.0);
        $method = camelName($fn);
        $isInt = $blk['int'];
        $cols = [];
        foreach ($blk['args'] as $c) {
            $allInt = $isInt && array_reduce($c, static fn (bool $acc, mixed $v): bool => $acc && is_int($v), true);
            $cols[] = $allInt ? $c : array_map('dec', $c);
        }
        // "undef": SciPy's own code has undefined behaviour on that row (tools/parity/ub_scan.py): not compared
        $expect = array_map(static fn (array $c): array => array_map('dec', $c), $blk['expect']);
        $nrows = count($cols[0] ?? []);
        $nout = count($expect);
        $problems = [];
        // arrays
        try {
            $args = [];
            foreach ($cols as $c) {
                $args[] = $arrayClass::array($c, is_int($c[0] ?? 0.0) && $isInt ? 'int64' : 'float64');
            }
            $r = $class::$method(...$args);
            $outs = $nout === 1 ? [$r] : array_values($r);
            foreach ($outs as $o => $arr) {
                $got = $arr->toList();
                for ($i = 0; $i < $nrows; $i++) {
                    if ($expect[$o][$i] === null) {
                        continue;
                    }
                    [$ok, $rel] = close((float) $got[$i], $expect[$o][$i], $rtol, $atol);
                    $checked++;
                    if ($rel !== INF && $rel > $maxRel[$key]) {
                        $maxRel[$key] = $rel;
                    }
                    if (! $ok) {
                        $problems[] = sprintf('array row %d out %d: args (%s) got %.17g want %.17g', $i, $o,
                            implode(', ', array_map(static fn (array $c) => var_export($c[$i], true), $cols)), $got[$i], $expect[$o][$i]);
                    }
                }
            }
        } catch (\Throwable $e) {
            $problems[] = 'array call threw ' . get_class($e) . ': ' . $e->getMessage();
        }
        // scalars (a sample)
        $step = max(1, intdiv($nrows, 40));
        for ($i = 0; $i < $nrows; $i += $step) {
            $sargs = array_map(static fn (array $c) => $c[$i], $cols);
            try {
                $r = $class::$method(...$sargs);
                $outs = $nout === 1 ? [$r] : array_values($r);
                foreach ($outs as $o => $v) {
                    if ($expect[$o][$i] === null) {
                        continue;
                    }
                    [$ok] = close((float) $v, $expect[$o][$i], $rtol, $atol);
                    $checked++;
                    if (! $ok) {
                        $problems[] = sprintf('scalar row %d out %d: args (%s) got %.17g want %.17g', $i, $o,
                            implode(', ', array_map(static fn ($v) => var_export($v, true), $sargs)), $v, $expect[$o][$i]);
                    }
                }
            } catch (\Throwable $e) {
                $problems[] = "scalar row {$i} threw " . get_class($e) . ': ' . $e->getMessage();
            }
        }
        if ($problems !== []) {
            $status[$key] = 'fail';
            $failures++;
            echo "FAIL {$key}" . ($isInt ? ' (integer loop)' : '') . ': ' . count($problems) . " mismatch(es)\n";
            foreach (array_slice($problems, 0, $verbose ? 20 : 3) as $p) {
                echo "    {$p}\n";
            }
        }
    }
    foreach ($status as $k => $s) {
        $results[$backend][$k] = $s;
        $results['max_rel'][$backend][$k] = $maxRel[$k] ?? null;
    }
}
ksort($results[$backend]);
if ($record) {
    file_put_contents($resultsPath, json_encode($results, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES) . "\n");
}
$pass = count(array_filter($results[$backend], static fn ($s) => $s === 'pass'));
$missing = count(array_filter($results[$backend], static fn ($s) => $s === 'missing'));
printf("%s: %d functions pass, %d fail, %d not implemented; %d values checked in %.1fs\n", $backend, $pass,
    count($results[$backend]) - $pass - $missing, $missing, $checked, microtime(true) - $t0);
exit($failures > 0 ? 1 : 0);
